{"command":"cat > src/logger.rs <<'RS'
use std::sync::OnceLock;

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Level { Error = 1, Warn = 2, Info = 3, Debug = 4, Trace = 5 }

pub struct Filter { global: Option<u8>, targets: Vec<(String, u8)> }

fn parse_level(s: &str) -> Option<u8> {
    match s.to_ascii_lowercase().as_str() {
        "off" => Some(0),
        "error" => Some(1),
        "warn" => Some(2),
        "info" => Some(3),
        "debug" => Some(4),
        "trace" => Some(5),
        _ => None,
    }
}

fn filter() -> &'static Filter {
    static F: OnceLock<Filter> = OnceLock::new();
    F.get_or_init(|| {
        match std::env::var("RUST_LOG") {
            Err(_) => Filter { global: Some(3), targets: Vec::new() },
            Ok(val) => {
                if val.trim().is_empty() {
                    return Filter { global: Some(3), targets: Vec::new() };
                }
                let mut global: Option<u8> = None;
                let mut targets: Vec<(String, u8)> = Vec::new();
                let mut any_target_directive = false;
                for raw in val.split(',') {
                    let part = raw.trim();
                    if part.is_empty() { continue; }
                    // Strip any /regex/ suffix
                    let part = part.split('/').next().unwrap_or(part).trim();
                    if let Some((t, l)) = part.split_once('=') {
                        let t = t.trim();
                        if let Some(lv) = parse_level(l.trim()) {
                            if t.is_empty() { global = Some(lv); } else { targets.push((t.to_string(), lv)); any_target_directive = true; }
                        } else if let Ok(n) = l.trim().parse::<u8>() {
                            targets.push((t.to_string(), n.min(5))); any_target_directive = true;
                        }
                    } else if let Some(lv) = parse_level(part) {
                        global = Some(lv);
                    } else {
                        // A bare target name: env_logger enables it at trace,
                        // everything else falls back to the default (error).
                        let name = part.trim();
                        if name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-' || c == ':' || c == '.') {
                            targets.push((name.to_string(), 5));
                            any_target_directive = true;
                        } else {
                            // Unparsable filter: env_logger ends up silencing
                            // output for our purposes.
                            global = Some(0);
                            targets.clear();
                            any_target_directive = false;
                        }
                    }
                }
                if any_target_directive && global.is_none() {
                    global = Some(1); // env_logger: only errors elsewhere
                }
                Filter { global, targets }
            }
        }
    })
}

pub fn enabled(level: Level, target: &str) -> bool {
    let f = filter();
    let lv = level as u8;
    // The most specific (longest) matching target directive wins.
    let mut best: Option<(usize, u8)> = None;
    for (t, l) in &f.targets {
        if target == t || target.starts_with(&format!("{}::", t)) || target.starts_with(t.as_str()) {
            let specificity = t.len();
            if best.map_or(true, |(bl, _)| specificity >= bl) {
                best = Some((specificity, *l));
            }
        }
    }
    if let Some((_, l)) = best {
        return lv <= l;
    }
    match f.global {
        Some(g) => lv <= g,
        None => lv <= 3,
    }
}

pub fn log(level: Level, target: &str, msg: &str) {
    if !enabled(level, target) { return; }
    let name = match level { Level::Error => "ERROR", Level::Warn => "WARN", Level::Info => "INFO", Level::Debug => "DEBUG", Level::Trace => "TRACE" };
    let ts = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
    for (i, line) in msg.split('\n').enumerate() {
        if i == 0 {
            eprintln!("{} [{}] ({}): {}", ts, name, target, line);
        } else {
            eprintln!("{}", line);
        }
    }
    // env_logger writes the message (which may itself end in blank lines)
    // followed by a single newline. split('\n') above already emits each
    // line, so a trailing \n in msg produces the extra blank lines. To
    // mirror that, if msg ends with '\n' we have already printed the
    // pieces; nothing more needed.
}

#[macro_export]
macro_rules! log_error { ($target:expr, $($arg:tt)*) => { $crate::logger::log($crate::logger::Level::Error, $target, &format!($($arg)*)) }; }
#[macro_export]
macro_rules! log_warn { ($target:expr, $($arg:tt)*) => { $crate::logger::log($crate::logger::Level::Warn, $target, &format!($($arg)*)) }; }
#[macro_export]
macro_rules! log_info { ($target:expr, $($arg:tt)*) => { $crate::logger::log($crate::logger::Level::Info, $target, &format!($($arg)*)) }; }
#[macro_export]
macro_rules! log_debug { ($target:expr, $($arg:tt)*) => { $crate::logger::log($crate::logger::Level::Debug, $target, &format!($($arg)*)) }; }
#[macro_export]
macro_rules! log_trace { ($target:expr, $($arg:tt)*) => { $crate::logger::log($crate::logger::Level::Trace, $target, &format!($($arg)*)) }; }

pub fn fatal(chain: &[String]) -> ! {
    if let Some((first, rest)) = chain.split_first() {
        log(Level::Error, "mdbook_core::utils", &format!("Error: {}", first));
        for c in rest {
            log(Level::Error, "mdbook_core::utils", &format!("\tCaused By: {}", c));
        }
    }
    std::process::exit(101);
}

pub fn fatal_msg(msg: impl Into<String>) -> ! {
    fatal(&[msg.into()])
}
RS
echo done"}

