use serde_json::{json, Map, Value};
use std::path::{Path, PathBuf};

pub fn get<'a>(cfg: &'a Value, path: &[&str]) -> Option<&'a Value> {
    let mut cur = cfg;
    for p in path {
        cur = cur.as_object()?.get(*p)?;
    }
    Some(cur)
}
pub fn get_str(cfg: &Value, path: &[&str]) -> Option<String> {
    get(cfg, path).and_then(|v| v.as_str()).map(|s| s.to_string())
}
pub fn get_bool(cfg: &Value, path: &[&str]) -> Option<bool> {
    get(cfg, path).and_then(|v| v.as_bool())
}
pub fn get_i64(cfg: &Value, path: &[&str]) -> Option<i64> {
    get(cfg, path).and_then(|v| v.as_i64())
}
pub fn get_str_list(cfg: &Value, path: &[&str]) -> Vec<String> {
    match get(cfg, path) {
        Some(Value::Array(a)) => a.iter().filter_map(|v| v.as_str().map(|s| s.to_string())).collect(),
        _ => Vec::new(),
    }
}
pub fn type_desc(v: &Value) -> String {
    match v {
        Value::String(s) => format!("string \"{}\"", s),
        Value::Number(n) => {
            if n.is_i64() || n.is_u64() { format!("integer `{}`", n) } else { format!("floating point `{}`", n) }
        }
        Value::Bool(b) => format!("boolean `{}`", b),
        Value::Array(_) => "sequence".to_string(),
        Value::Object(_) => "map".to_string(),
        Value::Null => "unit".to_string(),
    }
}

fn err_invalid_type(v: &Value, expected: &str, key: &str) -> ! {
    crate::logger::fatal(&[
        "Invalid configuration file".to_string(),
        format!("invalid type: {}, expected {}\nin `{}`\n", type_desc(v), expected, key),
    ])
}
fn err_unknown_variant(v: &str, expected: &str, key: &str) -> ! {
    crate::logger::fatal(&[
        "Invalid configuration file".to_string(),
        format!("unknown variant `{}`, expected {}\nin `{}`\n", v, expected, key),
    ])
}

pub fn validate(cfg: &Value) {
    let check_str = |path: &[&str], key: &str| {
        if let Some(v) = get(cfg, path) {
            if !v.is_string() { err_invalid_type(v, "a string", key); }
        }
    };
    let check_bool = |path: &[&str], key: &str| {
        if let Some(v) = get(cfg, path) {
            if !v.is_bool() { err_invalid_type(v, "a boolean", key); }
        }
    };
    let check_str_list = |path: &[&str], key: &str| {
        if let Some(v) = get(cfg, path) {
            match v {
                Value::Array(a) => {
                    for item in a { if !item.is_string() { err_invalid_type(item, "a string", key); } }
                }
                _ => err_invalid_type(v, "a sequence", key),
            }
        }
    };
    check_str(&["book", "title"], "title");
    check_str(&["book", "description"], "description");
    check_str(&["book", "src"], "src");
    check_str(&["book", "language"], "language");
    check_str_list(&["book", "authors"], "authors");
    if let Some(v) = get(cfg, &["book", "text-direction"]) {
        match v.as_str() {
            None => err_invalid_type(v, "text direction", "text-direction"),
            Some("ltr") | Some("rtl") => {}
            Some(other) => err_unknown_variant(other, "`ltr` or `rtl`", "text-direction"),
        }
    }
    if let Some(v) = get(cfg, &["rust", "edition"]) {
        match v.as_str() {
            None => err_invalid_type(v, "RustEdition", "edition"),
            Some("2015") | Some("2018") | Some("2021") | Some("2024") => {}
            Some(other) => err_unknown_variant(other, "one of `2024`, `2021`, `2018`, `2015`", "edition"),
        }
    }
    check_str(&["build", "build-dir"], "build-dir");
    check_bool(&["build", "create-missing"], "create-missing");
    check_bool(&["build", "use-default-preprocessors"], "use-default-preprocessors");
    // output.html basics
    let html = get(cfg, &["output", "html"]);
    if let Some(h) = html {
        if h.is_object() {
            for (k, v) in h.as_object().unwrap() {
                match k.as_str() {
                    "default-theme" | "preferred-dark-theme" | "theme" | "git-repository-url" | "git-repository-icon" | "edit-url-template" | "site-url" | "cname" | "input-404" => {
                        if !v.is_string() { err_invalid_type(v, "a string", k); }
                    }
                    "smart-punctuation" | "curly-quotes" | "mathjax-support" | "copy-fonts" | "no-section-label" | "hash-files" => {
                        if !v.is_bool() { err_invalid_type(v, "a boolean", k); }
                    }
                    "additional-css" | "additional-js" => {
                        if !v.is_array() { err_invalid_type(v, "a sequence", k); }
                    }
                    _ => {}
                }
            }
        } else if !h.is_null() {
            // [output] html = ??? ignore
        }
    }
}

pub fn apply_env(cfg: &mut Value) {
    crate::log_debug!("mdbook_core::config", "Updating the config from environment variables");
    let mut vars: Vec<(String, String)> = std::env::vars().filter(|(k, _)| k.starts_with("MDBOOK_")).collect();
    vars.sort();
    for (key, value) in vars {
        let suffix = &key["MDBOOK_".len()..];
        if suffix.is_empty() { continue; }
        let path: Vec<String> = suffix.split("__").map(|part| part.to_ascii_lowercase().replace('_', "-")).collect();
        let parsed: Value = serde_json::from_str(&value).unwrap_or_else(|_| Value::String(value.clone()));
        set_path(cfg, &path, parsed);
    }
}

fn set_path(cfg: &mut Value, path: &[String], value: Value) {
    if !cfg.is_object() { *cfg = json!({}); }
    let mut cur = cfg;
    for (i, part) in path.iter().enumerate() {
        if i + 1 == path.len() {
            let map = cur.as_object_mut().unwrap();
            if let (Some(existing), Value::Object(new)) = (map.get_mut(part), &value) {
                deep_merge(existing, value.clone());
            } else {
                map.insert(part.clone(), value.clone());
            }
            return;
        }
        let map = cur.as_object_mut().unwrap();
        let entry = map.entry(part.clone()).or_insert_with(|| json!({}));
        if !entry.is_object() { *entry = json!({}); }
        cur = entry;
    }
}

fn deep_merge(dst: &mut Value, src: Value) {
    match (dst, src) {
        (Value::Object(d), Value::Object(s)) => {
            for (k, v) in s {
                match d.get_mut(&k) {
                    Some(existing) => deep_merge(existing, v),
                    None => { d.insert(k, v); }
                }
            }
        }
        (d, s) => { *d = s; }
    }
}

pub fn load_config(root: &Path) -> Value {
    let cfg_path = root.join("book.toml");
    let mut cfg = json!({});
    if cfg_path.is_file() {
        crate::log_debug!("mdbook_driver::mdbook", "Loading config from {}", cfg_path.display());
        match std::fs::read_to_string(&cfg_path) {
            Ok(text) => {
                match text.parse::<toml::Table>() {
                    Ok(table) => {
                        cfg = serde_json::to_value(table).unwrap_or_else(|_| json!({}));
                    }
                    Err(e) => {
                        crate::logger::fatal(&[
                            "Invalid configuration file".to_string(),
                            format!("{}\n", e.to_string().trim_end()),
                        ]);
                    }
                }
            }
            Err(e) => {
                crate::logger::fatal(&[
                    "Invalid configuration file".to_string(),
                    format!("{}", e),
                ]);
            }
        }
    }
    apply_env(&mut cfg);
    // warn about unknown top-level fields
    if let Some(obj) = cfg.as_object() {
        let known = ["book", "build", "rust", "preprocessor", "output"];
        for k in obj.keys() {
            if !known.contains(&k.as_str()) {
                crate::log_warn!("mdbook_core::config", "Invalid field \"{}\" in book.toml", k);
            }
        }
    }
    validate(&cfg);
    cfg
}

pub fn root_dir(arg: Option<&String>) -> PathBuf {
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    match arg {
        None => cwd,
        Some(d) => {
            let p = PathBuf::from(d);
            if p.is_absolute() { p } else { cwd.join(p) }
        }
    }
}

pub fn src_dir(root: &Path, cfg: &Value) -> PathBuf {
    let src = get_str(cfg, &["book", "src"]).unwrap_or_else(|| "src".to_string());
    root.join(src)
}

pub fn build_dir(root: &Path, cfg: &Value, dest: Option<&String>) -> PathBuf {
    match dest {
        Some(d) => {
            let p = PathBuf::from(d);
            if p.is_absolute() { p } else { root.join(p) }
        }
        None => {
            let bd = get_str(cfg, &["build", "build-dir"]).unwrap_or_else(|| "book".to_string());
            root.join(bd)
        }
    }
}

pub fn _unused(_m: &Map<String, Value>) {}
