use std::collections::HashMap;

#[derive(Clone, Default)]
pub struct MdCtx {
    pub smart_punctuation: bool,
    pub hidelines: HashMap<String, String>,
}

#[derive(Default)]
pub struct HeadingState {
    pub counts: HashMap<String, usize>,
}

impl HeadingState {
    pub fn new() -> Self { Self::default() }
    pub fn unique_id(&mut self, base: &str) -> String {
        let n = self.counts.entry(base.to_string()).or_insert(0);
        let id = if *n == 0 { base.to_string() } else { format!("{}-{}", base, n) };
        *n += 1;
        id
    }
}

pub fn anchor_id(text: &str) -> String {
    let mut out = String::new();
    for ch in text.chars() {
        if ch.is_alphanumeric() || ch == '_' || ch == '-' {
            out.extend(ch.to_lowercase());
        } else if ch.is_whitespace() {
            out.push('-');
        }
    }
    out
}

pub fn escape_html(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for ch in s.chars() {
        match ch { '&' => out.push_str("&amp;"), '<' => out.push_str("&lt;"), '>' => out.push_str("&gt;"), '"' => out.push_str("&quot;"), _ => out.push(ch) }
    }
    out
}
fn escape_attr(s: &str) -> String { escape_html(s) }

// ---------- plain text extraction ----------
pub fn strip_inline(text: &str) -> String {
    // Remove markdown formatting, leaving readable text.
    let mut s = text.to_string();
    // footnote refs
    // images -> alt, links -> text (handled by scanner below mostly)
    let mut out = String::new();
    let bytes: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if c == '`' {
            let mut j = i;
            while j < bytes.len() && bytes[j] == '`' { j += 1; }
            let ticks = j - i;
            // find closing
            if let Some(end) = find_run(&bytes, j, '`', ticks) {
                for k in j..end { out.push(bytes[k]); }
                i = end + ticks;
            } else { i = j; }
            continue;
        }
        if c == '!' && i + 1 < bytes.len() && bytes[i+1] == '[' {
            if let Some((txt, _dest, next)) = parse_link(&s, i + 1) { out.push_str(&strip_inline(&txt)); i = next; continue; }
        }
        if c == '[' {
            // footnote
            if i + 1 < bytes.len() && bytes[i+1] == '^' {
                if let Some(end) = s[i..].find(']') { i += end + 1; continue; }
            }
            if let Some((txt, _dest, next)) = parse_link(&s, i) { out.push_str(&strip_inline(&txt)); i = next; continue; }
        }
        if c == '<' {
            if let Some(end) = s[i..].find('>') {
                let tag = &s[i..i+end+1];
                if tag.starts_with("<http") || tag.starts_with("<mailto") { out.push_str(&tag[1..tag.len()-1]); }
                i += end + 1; continue;
            }
        }
        if c == '*' || c == '_' || c == '~' { i += 1; continue; }
        if c == '\\' && i + 1 < bytes.len() { if i+1 < s.len() {} i += 1; if i < bytes.len() { out.push(bytes[i]); i+=1;} continue; }
        out.push(c);
        i += 1;
        let _ = &mut s;
    }
    out
}

fn find_run(chars: &[char], start: usize, ch: char, n: usize) -> Option<usize> {
    let mut i = start;
    while i < chars.len() {
        if chars[i] == ch {
            let mut j = i; while j < chars.len() && chars[j] == ch { j += 1; }
            if j - i == n { return Some(i); }
            i = j;
        } else { i += 1; }
    }
    None
}

// Parse a link starting at '[' index in string s (byte index of '[').
// Returns (text, dest_with_optional_title, next_byte_index)
pub fn parse_link(s: &str, start: usize) -> Option<(String, String, usize)> {
    let b = s.as_bytes();
    if b.get(start) != Some(&b'[') { return None; }
    // find matching ] handling nesting
    let mut depth = 0i32;
    let mut i = start;
    let mut close = None;
    while i < b.len() {
        match b[i] {
            b'\\' => { i += 2; continue; }
            b'[' => depth += 1,
            b']' => { depth -= 1; if depth == 0 { close = Some(i); break; } }
            _ => {}
        }
        i += 1;
    }
    let close = close?;
    let text = &s[start+1..close];
    let after = close + 1;
    if b.get(after) == Some(&b'(') {
        // find ) with parens nesting and <> dest
        let mut j = after + 1;
        let mut d = 1i32;
        let mut end = None;
        while j < b.len() {
            match b[j] {
                b'\\' => { j += 2; continue; }
                b'(' => d += 1,
                b')' => { d -= 1; if d == 0 { end = Some(j); break; } }
                _ => {}
            }
            j += 1;
        }
        let end = end?;
        let inside = s[after+1..end].trim().to_string();
        return Some((text.to_string(), inside, end + 1));
    }
    if b.get(after) == Some(&b'[') {
        if let Some(end_rel) = s[after..].find(']') {
            let label = &s[after+1..after+end_rel];
            let lookup = if label.is_empty() { text } else { label };
            // references are resolved by caller; signal with special marker
            return Some((text.to_string(), format!("\u{1}ref:{}", lookup), after + end_rel + 1));
        }
        return None;
    }
    // shortcut ref
    Some((text.to_string(), format!("\u{1}ref:{}", text), after))
}

pub fn split_dest_title(inside: &str) -> (String, Option<String>) {
    let t = inside.trim();
    if t.starts_with('<') {
        if let Some(end) = t.find('>') {
            let dest = t[1..end].to_string();
            let rest = t[end+1..].trim();
            let title = parse_title(rest);
            return (dest, title);
        }
    }
    // dest is first whitespace-separated token
    let mut split = t.splitn(2, |c: char| c.is_whitespace());
    let dest = split.next().unwrap_or("").to_string();
    let rest = split.next().unwrap_or("").trim();
    (dest, parse_title(rest))
}
fn parse_title(rest: &str) -> Option<String> {
    let r = rest.trim();
    if r.len() >= 2 {
        let first = r.chars().next().unwrap();
        let last = r.chars().last().unwrap();
        if (first == '"' && last == '"') || (first == '\'' && last == '\'') || (first == '(' && last == ')') {
            return Some(r[1..r.len()-1].to_string());
        }
    }
    None
}

/// Rewrite a .md link destination to .html, as mdBook does.
pub fn adjust_link(dest: &str, is_image: bool) -> String {
    if dest.is_empty() { return dest.to_string(); }
    // Split fragment
    let (path, frag) = match dest.split_once('#') {
        Some((p, f)) => (p, Some(f)),
        None => (dest, None),
    };
    if path.is_empty() {
        return dest.to_string();
    }
    // External / scheme / protocol-relative / absolute paths are left alone,
    // except that absolute links ending in .md are still ... left alone.
    if path.contains("://") || path.starts_with("//") || path.starts_with("mailto:") {
        return dest.to_string();
    }
    if !is_image {
        if let Some(stripped) = path.strip_suffix(".md") {
            let newpath = if stripped.ends_with("README") || stripped.ends_with("/README") || stripped == "README" {
                // README.md is rendered through the index preprocessor in
                // normal chapter paths, but plain content links to README.md
                // in the original keep README.html; links handled by the
                // preprocessor already rewrote chapter paths.
                format!("{}.html", stripped)
            } else {
                format!("{}.html", stripped)
            };
            return match frag { Some(f) => format!("{}#{}", newpath, f), None => newpath };
        }
        if path.ends_with(".md#") { }
    }
    dest.to_string()
}

pub struct InlineCtx<'a> {
    pub ctx: &'a MdCtx,
    pub refs: &'a HashMap<String, (String, Option<String>)>,
    pub footnotes: &'a Vec<(String, String)>,
    pub footnote_numbers: &'a mut HashMap<String, usize>,
    pub footnote_order: &'a mut Vec<String>,
}

fn smarten(text: &str) -> String {
    let mut out = String::new();
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i..].starts_with(&['-', '-', '-']) { out.push('\u{2014}'); i += 3; continue; }
        if chars[i..].starts_with(&['-', '-']) { out.push('\u{2013}'); i += 2; continue; }
        if chars[i..].starts_with(&['.', '.', '.']) { out.push('\u{2026}'); i += 3; continue; }
        let c = chars[i];
        if c == '"' {
            let prev = if i == 0 { None } else { Some(chars[i-1]) };
            if prev.is_none() || prev.unwrap().is_whitespace() || "([{".contains(prev.unwrap()) { out.push('\u{201c}'); } else { out.push('\u{201d}'); }
            i += 1; continue;
        }
        if c == '\'' {
            let prev = if i == 0 { None } else { Some(chars[i-1]) };
            let next = chars.get(i+1).copied();
            if prev.map_or(false, |p| p.is_alphanumeric()) { out.push('\u{2019}'); }
            else if next.map_or(false, |n| n.is_alphanumeric()) && (prev.is_none() || prev.unwrap().is_whitespace() || "([{".contains(prev.unwrap())) { out.push('\u{2018}'); }
            else { out.push('\u{2019}'); }
            i += 1; continue;
        }
        out.push(c); i += 1;
    }
    out
}

pub fn render_inline(text: &str, ic: &mut InlineCtx) -> String {
    let mut out = String::new();
    let b = text.as_bytes();
    let mut i = 0usize;
    let mut plain_start = 0usize;
    // Helper to flush plain text [plain_start, upto)
    macro_rules! flush {
        ($upto:expr) => {
            if $upto > plain_start {
                let seg = &text[plain_start..$upto];
                let seg = if ic.ctx.smart_punctuation { smarten(seg) } else { seg.to_string() };
                out.push_str(&escape_html_preserving_entities(&seg));
            }
        }
    }
    while i < b.len() {
        let c = b[i] as char;
        // escaped char
        if b[i] == b'\\' && i + 1 < b.len() && (b[i+1] as char).is_ascii_punctuation() {
            flush!(i);
            out.push_str(&escape_html(&(b[i+1] as char).to_string()));
            i += 2; plain_start = i; continue;
        }
        // code span
        if b[i] == b'`' {
            let mut j = i; while j < b.len() && b[j] == b'`' { j += 1; }
            let ticks = j - i;
            if let Some(end) = find_backtick_close(text, j, ticks) {
                flush!(i);
                let mut content = text[j..end].replace('\n', " ");
                if content.len() > 1 && content.starts_with(' ') && content.ends_with(' ') && content.trim() != "" {
                    content = content[1..content.len()-1].to_string();
                }
                out.push_str("<code>"); out.push_str(&escape_html(&content)); out.push_str("</code>");
                i = end + ticks; plain_start = i; continue;
            } else { i = j; continue; }
        }
        // footnote ref
        if b[i] == b'[' && i + 1 < b.len() && b[i+1] == b'^' {
            if let Some(rel_end) = text[i..].find(']') {
                let label = &text[i+2..i+rel_end];
                if ic.footnotes.iter().any(|(l, _)| l == label) {
                    flush!(i);
                    let num = if let Some(n) = ic.footnote_numbers.get(label) { *n } else {
                        let n = ic.footnote_order.len() + 1;
                        ic.footnote_numbers.insert(label.to_string(), n);
                        ic.footnote_order.push(label.to_string());
                        n
                    };
                    out.push_str(&format!("<sup class=\"footnote-reference\" id=\"fr-{}-{}\"><a href=\"#footnote-{}\">{}</a></sup>", label, num, label, num));
                    i += rel_end + 1; plain_start = i; continue;
                }
            }
        }
        // image
        if b[i] == b'!' && i + 1 < b.len() && b[i+1] == b'[' {
            if let Some((alt, inside, next)) = parse_link(text, i + 1) {
                flush!(i);
                let (dest, title) = resolve_dest(&inside, ic.refs);
                let alt_text = strip_inline(&alt);
                out.push_str(&format!("<img src=\"{}\" alt=\"{}\"", escape_attr(&adjust_link(&dest, true)), escape_attr(&alt_text)));
                if let Some(t) = title { out.push_str(&format!(" title=\"{}\"", escape_attr(&t))); }
                out.push_str(" />");
                i = next; plain_start = i; continue;
            }
        }
        // link
        if b[i] == b'[' {
            if let Some((txt, inside, next)) = parse_link(text, i) {
                // Only commit if it resolves (inline dest or known ref or empty)
                let resolved = resolve_dest_opt(&inside, ic.refs);
                if let Some((dest, title)) = resolved {
                    flush!(i);
                    let inner = render_inline(&txt, ic);
                    out.push_str(&format!("<a href=\"{}\"", escape_attr(&adjust_link(&dest, false))));
                    if let Some(t) = title { out.push_str(&format!(" title=\"{}\"", escape_attr(&t))); }
                    out.push_str(">"); out.push_str(&inner); out.push_str("</a>");
                    i = next; plain_start = i; continue;
                }
            }
            i += 1; continue;
        }
        // html / autolink
        if b[i] == b'<' {
            if let Some(rel_end) = text[i..].find('>') {
                let tag = &text[i..i+rel_end+1];
                let inner = &tag[1..tag.len()-1];
                if inner.starts_with("http://") || inner.starts_with("https://") || inner.starts_with("ftp://") {
                    flush!(i);
                    out.push_str(&format!("<a href=\"{}\">{}</a>", escape_attr(inner), escape_html(inner)));
                    i += rel_end + 1; plain_start = i; continue;
                }
                if inner.contains('@') && !inner.contains(' ') && !inner.starts_with('/') && inner.chars().next().map_or(false, |ch| ch.is_ascii_alphabetic()) {
                    flush!(i);
                    out.push_str(&format!("<a href=\"mailto:{}\">{}</a>", escape_attr(inner), escape_html(inner)));
                    i += rel_end + 1; plain_start = i; continue;
                }
                if is_html_tag(inner) {
                    flush!(i);
                    out.push_str(tag);
                    i += rel_end + 1; plain_start = i; continue;
                }
            }
            i += 1; continue;
        }
        // strikethrough
        if text[i..].starts_with("~~") {
            if let Some(end) = text[i+2..].find("~~") {
                if end > 0 {
                    flush!(i);
                    let inner = render_inline(&text[i+2..i+2+end], ic);
                    out.push_str("<del>"); out.push_str(&inner); out.push_str("</del>");
                    i += 2 + end + 2; plain_start = i; continue;
                }
            }
        }
        // strong
        if text[i..].starts_with("**") || text[i..].starts_with("__") {
            let delim = &text[i..i+2];
            if let Some(end) = find_delim(text, i + 2, delim) {
                if end > i + 2 {
                    flush!(i);
                    let inner = render_inline(&text[i+2..end], ic);
                    out.push_str("<strong>"); out.push_str(&inner); out.push_str("</strong>");
                    i = end + 2; plain_start = i; continue;
                }
            }
        }
        // emphasis
        if b[i] == b'*' || b[i] == b'_' {
            let delim = (b[i] as char).to_string();
            // underscore emphasis requires word boundary before
            let ok = if b[i] == b'_' {
                i == 0 || !(b[i-1] as char).is_alphanumeric()
            } else { true };
            if ok {
                if let Some(end) = find_em_close(text, i + 1, &delim) {
                    if end > i + 1 {
                        // closing underscore must be followed by non-alnum
                        let ok2 = if b[i] == b'_' { end + 1 >= b.len() || !(b[end+1] as char).is_alphanumeric() } else { true };
                        if ok2 {
                            flush!(i);
                            let inner = render_inline(&text[i+1..end], ic);
                            out.push_str("<em>"); out.push_str(&inner); out.push_str("</em>");
                            i = end + 1; plain_start = i; continue;
                        }
                    }
                }
            }
        }
        let _ = c;
        i += utf8_len(b[i]);
    }
    flush!(text.len());
    out
}

fn utf8_len(first: u8) -> usize {
    if first < 0x80 { 1 } else if first >> 5 == 0b110 { 2 } else if first >> 4 == 0b1110 { 3 } else if first >> 3 == 0b11110 { 4 } else { 1 }
}

fn find_backtick_close(text: &str, start: usize, ticks: usize) -> Option<usize> {
    let b = text.as_bytes();
    let mut i = start;
    while i < b.len() {
        if b[i] == b'`' {
            let mut j = i; while j < b.len() && b[j] == b'`' { j += 1; }
            if j - i == ticks { return Some(i); }
            i = j;
        } else { i += 1; }
    }
    None
}
fn find_delim(text: &str, start: usize, delim: &str) -> Option<usize> {
    text[start..].find(delim).map(|p| start + p)
}
fn find_em_close(text: &str, start: usize, delim: &str) -> Option<usize> {
    // single delim not part of a double
    let b = text.as_bytes();
    let d = delim.as_bytes()[0];
    let mut i = start;
    while i < b.len() {
        if b[i] == d {
            // skip runs of 2+ (allow if we later need)
            let mut j = i; while j < b.len() && b[j] == d { j += 1; }
            if j - i == 1 { return Some(i); }
            if j - i >= 2 { i = j; continue; }
            i = j;
        } else { i += 1; }
    }
    None
}

fn is_html_tag(inner: &str) -> bool {
    let t = inner.trim();
    if t.starts_with("!--") { return true; }
    let name_part = t.trim_start_matches('/').trim();
    if name_part.is_empty() { return false; }
    let first = name_part.chars().next().unwrap();
    if !first.is_ascii_alphabetic() && first != '!' && first != '?' { return false; }
    // tag name followed by space, /, >, or end
    true
}

pub fn escape_html_preserving_entities(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'&' {
            // entity?
            if let Some(rel) = s[i..].find(';') {
                if rel >= 2 && rel <= 10 {
                    let ent = &s[i+1..i+rel];
                    if ent.chars().all(|c| c.is_ascii_alphanumeric() || c == '#') && !ent.is_empty() {
                        out.push_str(&s[i..i+rel+1]); i += rel + 1; continue;
                    }
                }
            }
            out.push_str("&amp;"); i += 1; continue;
        }
        if b[i] == b'<' { out.push_str("&lt;"); i += 1; continue; }
        if b[i] == b'>' { out.push_str("&gt;"); i += 1; continue; }
        let len = utf8_len(b[i]);
        out.push_str(&s[i..(i+len).min(s.len())]); i += len;
    }
    out
}

fn resolve_dest(inside: &str, refs: &HashMap<String, (String, Option<String>)>) -> (String, Option<String>) {
    resolve_dest_opt(inside, refs).unwrap_or_else(|| (String::new(), None))
}
fn resolve_dest_opt(inside: &str, refs: &HashMap<String, (String, Option<String>)>) -> Option<(String, Option<String>)> {
    if let Some(label) = inside.strip_prefix('\u{1}') {
        let label = label.strip_prefix("ref:").unwrap_or(label);
        let key = normalize_ref(label);
        return refs.get(&key).cloned();
    }
    Some(split_dest_title(inside))
}
pub fn normalize_ref(s: &str) -> String {
    s.split_whitespace().collect::<Vec<_>>().join(" ").to_ascii_lowercase()
}

// ------------------ block rendering ------------------

pub struct RenderState<'a> {
    pub ctx: &'a MdCtx,
    pub headings: HeadingState,
    pub refs: HashMap<String, (String, Option<String>)>,
    pub footnotes: Vec<(String, String)>,
}

pub fn render_markdown(md: &str, ctx: &MdCtx) -> String {
    let mut st = RenderState { ctx, headings: HeadingState::new(), refs: HashMap::new(), footnotes: Vec::new() };
    render_markdown_with_state(md, &mut st)
}

pub fn render_markdown_with_state(md: &str, st: &mut RenderState) -> String {
    // Collect reference definitions and footnote definitions first.
    let (cleaned, refs, footnotes) = preprocess_defs(md);
    st.refs = refs;
    st.footnotes = footnotes;
    let lines: Vec<String> = cleaned.lines().map(|s| s.to_string()).collect();
    let mut footnote_numbers: HashMap<String, usize> = HashMap::new();
    let mut footnote_order: Vec<String> = Vec::new();
    let mut html = render_blocks(&lines, st, &mut footnote_numbers, &mut footnote_order);
    if !footnote_order.is_empty() {
        html.push_str("<hr>\n<ol class=\"footnote-definition\">");
        for label in &footnote_order {
            if let Some((_, text)) = st.footnotes.iter().find(|(l, _)| l == label) {
                let num = footnote_numbers.get(label).copied().unwrap_or(1);
                let mut ic = InlineCtx { ctx: st.ctx, refs: &st.refs.clone(), footnotes: &st.footnotes.clone(), footnote_numbers: &mut HashMap::new(), footnote_order: &mut Vec::new() };
                let rendered = render_paragraph_content(text, &mut ic);
                html.push_str(&format!("<li id=\"footnote-{}\">\n<p>{} <a href=\"#fr-{}-{}\">↩</a></p>\n</li>\n", label, rendered, label, num));
            }
        }
        html.push_str("</ol>");
    }
    html
}

fn render_paragraph_content(text: &str, ic: &mut InlineCtx) -> String {
    render_inline(text, ic)
}

fn preprocess_defs(md: &str) -> (String, HashMap<String, (String, Option<String>)>, Vec<(String, String)>) {
    let mut refs = HashMap::new();
    let mut footnotes: Vec<(String, String)> = Vec::new();
    let lines: Vec<&str> = md.lines().collect();
    let mut out_lines: Vec<String> = Vec::new();
    let mut i = 0;
    let mut in_fence = false;
    let mut fence_char = '`';
    let mut fence_len = 0usize;
    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim_start();
        // fence tracking
        if let Some((ch, n)) = fence_start(trimmed) {
            if !in_fence { in_fence = true; fence_char = ch; fence_len = n; }
            else if ch == fence_char && n >= fence_len { in_fence = false; }
            out_lines.push(line.to_string()); i += 1; continue;
        }
        if in_fence { out_lines.push(line.to_string()); i += 1; continue; }
        // footnote definition
        if let Some(rest) = trimmed.strip_prefix("[^") {
            if let Some(end) = rest.find("]:") {
                let label = &rest[..end];
                if !label.contains(' ') {
                    let mut text = rest[end+2..].trim_start().to_string();
                    let mut j = i + 1;
                    while j < lines.len() && (lines[j].starts_with("    ") || lines[j].starts_with('\t') || lines[j].trim().is_empty()) && !lines[j].trim().is_empty() {
                        text.push('\n');
                        text.push_str(lines[j].trim());
                        j += 1;
                    }
                    footnotes.push((label.to_string(), text));
                    i = j; continue;
                }
            }
        }
        // reference definition: [label]: dest "title"
        if trimmed.starts_with('[') && !trimmed.starts_with("[^") {
            if let Some(end) = trimmed.find("]:") {
                let label = &trimmed[1..end];
                let rest = trimmed[end+2..].trim();
                if !rest.is_empty() {
                    let (dest, title) = split_dest_title(rest);
                    refs.insert(normalize_ref(label), (dest, title));
                    i += 1; continue;
                }
            }
        }
        out_lines.push(line.to_string());
        i += 1;
    }
    (out_lines.join("\n"), refs, footnotes)
}

pub fn fence_start(trimmed: &str) -> Option<(char, usize)> {
    let mut chars = trimmed.chars();
    let first = chars.next()?;
    if first != '`' && first != '~' { return None; }
    let mut n = 1;
    for c in chars { if c == first { n += 1; } else { break; } }
    if n >= 3 { Some((first, n)) } else { None }
}

struct ListItem {
    indent: usize,
    content_indent: usize,
    ordered_start: Option<u64>,
    marker_len: usize,
    first_text: String,
    extra_lines: Vec<String>,
    children: Vec<ListItem>,
    loose_blank: bool,
}

fn parse_list_item_line(line: &str) -> Option<(usize, usize, Option<u64>, String)> {
    let b = line.as_bytes();
    let mut indent = 0;
    while indent < b.len() && b[indent] == b' ' { indent += 1; }
    if indent > 3 && false { return None; }
    let rest = &line[indent..];
    let rb = rest.as_bytes();
    if rb.is_empty() { return None; }
    // unordered
    if (rb[0] == b'-' || rb[0] == b'*' || rb[0] == b'+') && (rb.len() == 1 || rb[1] == b' ' || rb[1] == b'\t') {
        let mut spaces = 1; while spaces < rb.len() && (rb[spaces] == b' ' || rb[spaces] == b'\t') { spaces += 1; }
        let content = if rb.len() > spaces { &rest[spaces..] } else { "" };
        return Some((indent, indent + spaces, None, content.to_string()));
    }
    // ordered
    let mut j = 0; while j < rb.len() && rb[j].is_ascii_digit() { j += 1; }
    if j >= 1 && j <= 9 && j < rb.len() && (rb[j] == b'.' || rb[j] == b')') && (j + 1 >= rb.len() || rb[j+1] == b' ' || rb[j+1] == b'\t') {
        let num: u64 = rest[..j].parse().unwrap_or(1);
        let mut spaces = j + 1; while spaces < rb.len() && (rb[spaces] == b' ' || rb[spaces] == b'\t') { spaces += 1; }
        let content = if rb.len() > spaces { &rest[spaces..] } else { "" };
        return Some((indent, indent + spaces, Some(num), content.to_string()));
    }
    None
}

fn render_blocks(lines: &[String], st: &mut RenderState, fn_numbers: &mut HashMap<String, usize>, fn_order: &mut Vec<String>) -> String {
    let mut out = String::new();
    let mut i = 0usize;
    while i < lines.len() {
        let line = &lines[i];
        let trimmed = line.trim();
        if trimmed.is_empty() { i += 1; continue; }
        // fenced code
        let tstart = line.trim_start();
        if let Some((fch, flen)) = fence_start(tstart) {
            let info_full = tstart[flen..].trim().to_string();
            let mut content = String::new();
            i += 1;
            while i < lines.len() {
                let l = &lines[i];
                let lt = l.trim_start();
                if let Some((c2, n2)) = fence_start(lt) {
                    if c2 == fch && n2 >= flen {
                        // closing fence must not have info (except spaces)
                        i += 1; break;
                    }
                }
                content.push_str(l); content.push('\n');
                i += 1;
            }
            out.push_str(&crate::codeblock::render_code_block(&info_full, &content, st.ctx));
            continue;
        }
        // ATX heading
        if let Some((level, text, custom_id, classes)) = parse_atx_heading(line) {
            let plain = strip_inline(&text);
            let id = if let Some(cid) = custom_id { st.headings.unique_id(&cid) } else { let base = anchor_id(&plain); st.headings.unique_id(&base) };
            // Recompute id handling: unique_id on custom should not suffix first time
            let mut ic = InlineCtx { ctx: st.ctx, refs: &st.refs.clone(), footnotes: &st.footnotes.clone(), footnote_numbers: fn_numbers, footnote_order: fn_order };
            let inner = render_inline(&text, &mut ic);
            let class_attr = if classes.is_empty() { String::new() } else { format!(" class=\"{}\"", classes.join(" ")) };
            out.push_str(&format!("<h{} id=\"{}\"{}><a class=\"header\" href=\"#{}\">{}</a></h{}>\n", level, escape_attr(&id), class_attr, escape_attr(&id), inner, level));
            i += 1; continue;
        }
        // thematic break
        if is_thematic_break(trimmed) {
            out.push_str("<hr />\n"); i += 1; continue;
        }
        // blockquote
        if tstart.starts_with('>') {
            let mut inner_lines: Vec<String> = Vec::new();
            while i < lines.len() {
                let l = &lines[i];
                let lt = l.trim_start();
                if lt.starts_with('>') {
                    let mut stripped = lt[1..].to_string();
                    if stripped.starts_with(' ') { stripped.remove(0); }
                    inner_lines.push(stripped);
                    i += 1;
                } else if !l.trim().is_empty() && !inner_lines.is_empty() {
                    // lazy continuation
                    inner_lines.push(l.clone());
                    i += 1;
                } else { break; }
            }
            let inner_html = render_blocks(&inner_lines, st, fn_numbers, fn_order);
            out.push_str("<blockquote>\n"); out.push_str(&inner_html); out.push_str("</blockquote>\n");
            continue;
        }
        // table
        if line.contains('|') && i + 1 < lines.len() && is_table_delim(&lines[i+1]) {
            let header_cells = split_table_row(line);
            let aligns = table_aligns(&lines[i+1]);
            if !aligns.is_empty() && aligns.len() == header_cells.len() {
                i += 2;
                let mut rows: Vec<Vec<String>> = Vec::new();
                while i < lines.len() && !lines[i].trim().is_empty() && lines[i].contains('|') {
                    rows.push(split_table_row(&lines[i]));
                    i += 1;
                }
                out.push_str("<div class=\"table-wrapper\"><table><thead><tr>");
                for (idx, cell) in header_cells.iter().enumerate() {
                    let mut ic = InlineCtx { ctx: st.ctx, refs: &st.refs.clone(), footnotes: &st.footnotes.clone(), footnote_numbers: fn_numbers, footnote_order: fn_order };
                    let inner = render_inline(cell.trim(), &mut ic);
                    out.push_str(&align_cell("th", &inner, aligns.get(idx).copied().unwrap_or("")));
                }
                out.push_str("</tr></thead><tbody>\n");
                for row in &rows {
                    out.push_str("<tr>");
                    for idx in 0..header_cells.len() {
                        let cell = row.get(idx).cloned().unwrap_or_default();
                        let mut ic = InlineCtx { ctx: st.ctx, refs: &st.refs.clone(), footnotes: &st.footnotes.clone(), footnote_numbers: fn_numbers, footnote_order: fn_order };
                        let inner = render_inline(cell.trim(), &mut ic);
                        out.push_str(&align_cell("td", &inner, aligns.get(idx).copied().unwrap_or("")));
                    }
                    out.push_str("</tr>\n");
                }
                out.push_str("</tbody></table>\n</div>\n");
                continue;
            }
        }
        // list
        if parse_list_item_line(line).is_some() {
            let (html, next) = render_list(lines, i, st, fn_numbers, fn_order);
            out.push_str(&html);
            i = next;
            continue;
        }
        // HTML block
        if is_html_block_start(tstart) {
            let mut block_lines: Vec<String> = Vec::new();
            while i < lines.len() && !lines[i].trim().is_empty() {
                block_lines.push(lines[i].clone());
                i += 1;
            }
            out.push_str(&block_lines.join("\n")); out.push('\n');
            continue;
        }
        // indented code
        if line.starts_with("    ") || line.starts_with('\t') {
            let mut content = String::new();
            while i < lines.len() && (lines[i].starts_with("    ") || lines[i].starts_with('\t') || lines[i].trim().is_empty()) {
                if lines[i].trim().is_empty() {
                    // peek ahead
                    if i + 1 < lines.len() && (lines[i+1].starts_with("    ") || lines[i+1].starts_with('\t')) { content.push('\n'); i += 1; continue; } else { break; }
                }
                let stripped = if let Some(s) = lines[i].strip_prefix("    ") { s.to_string() } else if let Some(s) = lines[i].strip_prefix('\t') { s.to_string() } else { lines[i].clone() };
                content.push_str(&stripped); content.push('\n');
                i += 1;
            }
            out.push_str("<pre><code>"); out.push_str(&escape_html(&content)); out.push_str("</code></pre>\n");
            continue;
        }
        // paragraph (with setext check)
        let mut para_lines: Vec<String> = Vec::new();
        let mut setext_level: Option<usize> = None;
        while i < lines.len() {
            let l = &lines[i];
            if para_lines.is_empty() {
                para_lines.push(l.clone()); i += 1;
                // setext on next line
                if i < lines.len() {
                    let nt = lines[i].trim();
                    if nt.chars().all(|c| c == '=') && !nt.is_empty() { setext_level = Some(1); i += 1; }
                    else if nt.chars().all(|c| c == '-') && !nt.is_empty() { setext_level = Some(2); i += 1; }
                }
                break;
            }
            if l.trim().is_empty() { break; }
            // interruptions
            let lt = l.trim_start();
            if fence_start(lt).is_some() || parse_atx_heading(l).is_some() || is_thematic_break(l.trim()) || lt.starts_with('>') || parse_list_item_line(l).is_some() {
                break;
            }
            para_lines.push(l.clone()); i += 1;
        }
        if let Some(level) = setext_level {
            let text = para_lines.join(" ");
            let plain = strip_inline(&text);
            let base = anchor_id(&plain);
            let id = st.headings.unique_id(&base);
