            let mut processed: Vec<String> = Vec::new();
            for l in &para_lines {
                if l.ends_with("  ") { processed.push(format!("{}<br />", l.trim_end())); }
                else if l.ends_with('\\') { processed.push(format!("{}<br />", &l[..l.len()-1])); }
