pub fn is_table_delim(line: &str) -> bool {
    let t = line.trim();
    if !t.contains('-') { return false; }
    let cells = split_table_row(t);
    if cells.is_empty() { return false; }
    cells.iter().all(|c| {
        let ct = c.trim();
        !ct.is_empty() && ct.chars().all(|ch| ch == '-' || ch == ':') && ct.contains('-')
    })
}
fn table_aligns(line: &str) -> Vec<&'static str> {
    split_table_row(line).iter().map(|c| {
        let ct = c.trim();
        let left = ct.starts_with(':'); let right = ct.ends_with(':');
        match (left, right) { (true, true) => "center", (false, true) => "right", (true, false) => "left", _ => "" }
    }).collect()
}
pub fn split_table_row(line: &str) -> Vec<String> {
    let mut t = line.trim().to_string();
    if t.starts_with('|') { t.remove(0); }
    if t.ends_with('|') && !t.ends_with("\\|") { t.pop(); }
    // split on unescaped |
    let mut cells = Vec::new();
    let mut cur = String::new();
    let mut chars = t.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' && chars.peek() == Some(&'|') { cur.push('|'); chars.next(); }
        else if c == '|' { cells.push(cur.clone()); cur.clear(); }
        else { cur.push(c); }
    }
    cells.push(cur);
    cells
}

fn is_thematic_break(t: &str) -> bool {
    let compact: String = t.chars().filter(|c| *c != ' ' && *c != '\t').collect();
    if compact.len() < 3 { return false; }
    let first = compact.chars().next().unwrap();
    (first == '-' || first == '*' || first == '_') && compact.chars().all(|c| c == first)
}

fn parse_atx_heading(line: &str) -> Option<(usize, String, Option<String>, Vec<String>)> {
    let t = line.trim_start();
    let indent = line.len() - t.len();
    if indent > 3 { return None; }
    let mut level = 0; let b = t.as_bytes();
    while level < b.len() && b[level] == b'#' { level += 1; }
    if level == 0 || level > 6 { return None; }
    if level < b.len() && b[level] != b' ' && b[level] != b'\t' { return None; }
    let mut text = t[level..].trim().to_string();
    // closing hashes
    if text.ends_with('#') {
        let trimmed = text.trim_end_matches('#');
        if trimmed.ends_with(' ') || trimmed.is_empty() { text = trimmed.trim_end().to_string(); }
    }
    // heading attributes { #id .class }
    let mut custom_id = None;
    let mut classes: Vec<String> = Vec::new();
    if text.ends_with('}') {
        if let Some(open) = text.rfind('{') {
            let attrs = text[open+1..text.len()-1].trim().to_string();
            let before = text[..open].trim_end().to_string();
            let mut valid = true;
            let mut tmp_id = None; let mut tmp_classes = Vec::new();
            for tok in attrs.split_whitespace() {
                if let Some(id) = tok.strip_prefix('#') { tmp_id = Some(id.to_string()); }
                else if let Some(cl) = tok.strip_prefix('.') { tmp_classes.push(cl.to_string()); }
                else { valid = false; break; }
            }
            if valid && (!attrs.is_empty()) { custom_id = tmp_id; classes = tmp_classes; text = before; }
        }
    }
    Some((level, text, custom_id, classes))
}

fn is_html_block_start(t: &str) -> bool {
    if !t.starts_with('<') { return false; }
