/// Break the info string into (language, class tokens, hidelines-override)
fn parse_info(info: &str) -> (String, Vec<String>, Option<String>) {
    let tokens: Vec<String> = info.split(|c| c == ',' || c == ' ' || c == '\t').filter(|s| !s.is_empty()).map(|s| s.to_string()).collect();
    if tokens.is_empty() { return (String::new(), Vec::new(), None); }
    let mut hidelines = None;
    for t in &tokens {
        if let Some(v) = t.strip_prefix("hidelines=") { hidelines = Some(v.to_string()); }
    }
    (tokens[0].clone(), tokens, hidelines)
}

pub fn has_main(code: &str) -> bool {
    // mdBook looks for a `fn main` definition
    for line in code.lines() {
        let t = line.trim_start();
        if t.starts_with("fn main(") || t.starts_with("fn main (") || t.starts_with("pub fn main(") || t.starts_with("pub(crate) fn main(") {
            return true;
        }
    }
    code.contains("fn main()")
}

pub fn render_code_block(info: &str, content: &str, ctx: &MdCtx) -> String {
    render_code_block_cfg(info, content, ctx, true)
}

pub struct CodeCfg {
    pub playground_runnable: bool,
}

pub fn render_code_block_cfg(info: &str, content: &str, ctx: &MdCtx, playground_runnable: bool) -> String {
    let (lang, tokens, hidelines_override) = parse_info(info);
    let class_attr = if tokens.is_empty() {
        String::new()
    } else {
        let mut classes = Vec::new();
        classes.push(format!("language-{}", lang));
        for t in &tokens[1..] { classes.push(t.clone()); }
        format!(" class=\"{}\"", classes.join(" "))
    };
    let is_rust = lang == "rust";
    let hide_prefix: Option<String> = if let Some(h) = hidelines_override {
        Some(h)
    } else if let Some(p) = ctx.hidelines.get(&lang) {
        Some(p.clone())
    } else if is_rust {
        Some("#".to_string())
    } else { None };

    let classes_contain = |name: &str| tokens.iter().any(|t| t == name);
    let runnable = is_rust && playground_runnable
        && (classes_contain("mdbook-runnable") || (!classes_contain("ignore") && !classes_contain("noplayground")));

    if !is_rust && hide_prefix.is_none() {
        // Plain pulldown-cmark rendering.
        return format!("<pre><code{}>{}</code></pre>\n", class_attr, escape_html(content));
    }

    // Process hidden lines.
    let mut processed = String::new();
    let lines: Vec<&str> = content.lines().collect();
    for line in &lines {
        if let Some(prefix) = &hide_prefix {
            if is_rust && prefix == "#" {
                let indent_len = line.len() - line.trim_start().len();
                let indent = &line[..indent_len];
                let rest = &line[indent_len..];
                if rest == "#" || rest.starts_with("# ") {
                    let visible = if rest == "#" { "" } else { &rest[2..] };
                    processed.push_str(&format!("<span class=\"boring\">{}{}\n</span>", escape_html(indent), escape_html(visible)));
                    continue;
                } else if let Some(stripped) = rest.strip_prefix("##") {
                    processed.push_str(&escape_html(indent)); processed.push_str(&escape_html(&format!("#{}", stripped))); processed.push('\n');
                    continue;
                }
            } else {
                let indent_len = line.len() - line.trim_start().len();
                let indent = &line[..indent_len];
                let rest = &line[indent_len..];
                if rest.starts_with(prefix.as_str()) {
                    let visible = &rest[prefix.len()..];
                    processed.push_str(&format!("<span class=\"boring\">{}{}\n</span>", escape_html(indent), escape_html(visible)));
                    continue;
                }
            }
        }
        processed.push_str(&escape_html(line)); processed.push('\n');
    }

    if is_rust {
        if runnable {
            let mut inner = String::new();
            if !has_main(content) {
                inner.push_str("<span class=\"boring\">#![allow(unused)]\n</span>");
                inner.push_str("<span class=\"boring\">fn main() {\n</span>");
                inner.push_str(&processed);
                inner.push_str("<span class=\"boring\">}</span>");
            } else {
                // strip trailing newline to match original rendering
                let trimmed = processed.strip_suffix('\n').unwrap_or(&processed);
                inner.push_str(trimmed);
            }
            return format!("<pre><pre class=\"playground\"><code{}>{}</code></pre></pre>\n", class_attr, inner);
        } else {
            let trimmed = processed.strip_suffix('\n').unwrap_or(&processed);
            return format!("<pre><code{}>{}</code></pre>\n", class_attr, trimmed);
        }
    }

    // non-rust with hidelines
    format!("<pre><code{}>{}</code></pre>\n", class_attr, processed)
}
