use std::collections::HashSet;
use std::path::{Path, PathBuf};

#[derive(Clone, Debug)]
pub struct Chapter {
    pub name: String,
    pub location: Option<PathBuf>, // relative to src dir, as written (without fragment)
    pub location_raw: Option<String>,
    pub number: Option<Vec<u32>>,
    pub sub_items: Vec<Item>,
    pub content: String,
    pub path_html: Option<PathBuf>, // output path relative, e.g. sub/ch.html (after index conversion)
    pub source_path_display: String, // for test logs: "sub/ch.md"
}

#[derive(Clone, Debug)]
pub enum Item {
    Chapter(Chapter),
    Separator,
    PartTitle(String),
}

#[derive(Clone, Debug, Default)]
pub struct Book {
    pub items: Vec<Item>, // prefix, numbered, suffix in order (flat top-level, with sub_items in chapters)
}

impl Book {
    pub fn chapters_flat(&self) -> Vec<&Chapter> {
        let mut out = Vec::new();
        fn walk<'a>(items: &'a [Item], out: &mut Vec<&'a Chapter>) {
            for it in items {
                if let Item::Chapter(ch) = it {
                    out.push(ch);
                    walk(&ch.sub_items, out);
                }
            }
        }
        walk(&self.items, &mut out);
        out
    }
    pub fn chapters_flat_mut(&mut self) -> Vec<&mut Chapter> {
        let mut out = Vec::new();
        fn walk<'a>(items: &'a mut [Item], out: &mut Vec<&'a mut Chapter>) {
            for it in items.iter_mut() {
                if let Item::Chapter(ch) = it {
                    // SAFETY not needed: use raw pointer trick via split? Instead collect with recursion on each
                    out.push(ch as *mut Chapter);
                }
            }
        }
        // The above approach is awkward; implement iterative pointer collection:
        let mut ptrs: Vec<*mut Chapter> = Vec::new();
        fn collect(items: &mut [Item], ptrs: &mut Vec<*mut Chapter>) {
            for it in items.iter_mut() {
                if let Item::Chapter(ch) = it {
                    ptrs.push(ch as *mut Chapter);
                    collect(&mut ch.sub_items, ptrs);
                }
            }
        }
        collect(&mut self.items, &mut ptrs);
        ptrs.into_iter().map(|p| unsafe { &mut *p }).collect()
    }
}

pub struct Summary {
    pub items: Vec<Item>,
}

fn strip_md_formatting(text: &str) -> String {
    crate::markdown::strip_inline(text)
}

struct NumState {
    counters: Vec<u32>,
