        if let Some((indent, content_indent, _ord, content)) = parse_list_marker(raw_line) {
            first_element_consumed = true;
            if suffix_started {
                return Err(vec![
                    format!("Summary parsing failed for file=\"{}\"", summary_path.display()),
                    "There was an error parsing the suffix chapters".to_string(),
                    format!("failed to parse SUMMARY.md line {}, column {}: Suffix chapters cannot be followed by a list", line_no, 1),
                ]);
            }
            numbered_started = true;
            // compute depth using list stack
            // pop siblings/deeper levels
            while let Some(&(ind, _ci)) = list_stack.last() {
                if indent < ind {
                    list_stack.pop();
                } else if indent == ind {
                    list_stack.pop();
                    break;
                } else {
                    break;
                }
            }
            // If indent is greater than top but not reaching its content indent, it's a sibling
            if let Some(&(ind, ci)) = list_stack.last() {
                if indent > ind && indent < ci {
                    list_stack.pop();
                }
            }
            let depth = list_stack.len();
            // parse link at start of content
            let content_trim = content.trim_start();
            match parse_summary_link(content_trim) {
                Some((name, dest)) => {
                    let ch = make_chapter(name, dest, &mut seen_paths, summary_path)?;
                    list_stack.push((indent, content_indent));
                    let _ = depth;
                    flat.push(FlatEntry { depth: list_stack.len() - 1, item: Item::Chapter(ch) });
                }
                None => {
                    // warn like original
                    let got = describe_first_token(content_trim);
                    crate::log_warn!("mdbook_summary", "Expected a start of a link, actually got {}", got);
                    let col = if content_trim.is_empty() { indent } else { indent + 2 };
                    return Err(vec![
                        format!("Summary parsing failed for file=\"{}\"", summary_path.display()),
                        "There was an error parsing the numbered chapters".to_string(),
                        "There was an error parsing the numbered chapters".to_string(),
                        format!("failed to parse SUMMARY.md line {}, column {}: The link items for nested chapters must only contain a hyperlink", line_no, col),
                    ]);
                }
            }
            continue;
        }

        // Paragraph-ish line: standalone link or plain text
        first_element_consumed = true;
        if let Some((name, dest)) = parse_standalone_link(trimmed) {
            let ch = make_chapter(name, dest, &mut seen_paths, summary_path)?;
            if !numbered_started {
                // prefix
                flat.push(FlatEntry { depth: 0, item: Item::Chapter(ch) });
            } else {
                suffix_started = true;
                flat.push(FlatEntry { depth: 0, item: Item::Chapter(ch) });
            }
            continue;
        }
        // Plain paragraph text.
        if numbered_started && !suffix_started {
            // A non-list paragraph after numbered chapters starts the suffix section.
            // But part titles were handled above; plain text itself is ignored.
            suffix_started = true;
        }
        // Otherwise ignore text.
        let _ = line_no;
    }
    let _ = number_stack;

    // Check duplicate paths already done in make_chapter.
    // Assign numbers to numbered chapters.
    // Determine which flat entries are numbered: chapters that are not prefix/suffix.
    // We tracked that implicitly: prefix chapters appear before numbered_started,
    // suffix after suffix_started. But flat lost that info. Recompute by scanning:
    // We recorded depth and item only. Instead we need affix flags. Handle by
    // re-deriving: chapters before the first numbered chapter/part title/separator
    // in numbered section... This is ambiguous; we therefore stored affix info
    // differently below (see Chapter.number = None for affix, assigned later).
    // To assign numbers we need to know boundaries. We kept `numbered_started`
    // transitions in the flat order: we will use a second pass with markers
    // inserted into flat (PartTitle/Separator have no affix info either).
    // Simplest: numbers are assigned in order to all chapters except those we
    // marked with number = Some(vec![]) sentinel for affix.
    let mut flat_items: Vec<Item> = flat.into_iter().map(|e| {
        // depth is encoded via a wrapper we lost; see assemble step in parse_summary_tree
        e.item
    }).collect();
    let _ = &mut flat_items;

    // NOTE: The depth/affix assembly is performed by parse_summary_impl; this
    // function is replaced below.
    let _ = items;
    Ok(Summary { items: flat_items })
}

fn describe_first_token(content: &str) -> String {
    if content.is_empty() {
        return "Some(End(Item))".to_string();
    }
    if content.starts_with("**") || content.starts_with("__") {
        return "Some(Start(Strong))".to_string();
    }
    if content.starts_with('*') || content.starts_with('_') {
        return "Some(Start(Emphasis))".to_string();
    }
    if content.starts_with('<') {
        let tag: String = content.chars().take_while(|c| *c != '>').collect();
        return format!("Some(InlineHtml(Borrowed(\"{}\")))", tag);
    }
    if content.starts_with('`') {
        return "Some(Code(Borrowed(\"\")))".to_string();
    }
    format!("Some(Text(Borrowed(\"{}\")))", content)
}

fn make_chapter(name: String, dest: String, seen: &mut HashSet<String>, summary_path: &Path) -> Result<Chapter, Vec<String>> {
    let name = strip_md_formatting(&name);
    if dest.is_empty() {
        return Ok(Chapter {
            name,
            location: None,
            location_raw: None,
            number: None,
            sub_items: Vec::new(),
            content: String::new(),
            path_html: None,
            source_path_display: String::new(),
        });
    }
    let dest_no_frag = dest.split('#').next().unwrap_or("").to_string();
    // Normalise ./ prefix for duplicate detection and storage
    let normalized = dest_no_frag.trim_start_matches("./").to_string();
    if !normalized.is_empty() {
        if seen.contains(&normalized) {
            return Err(vec![
                format!("Summary parsing failed for file=\"{}\"", summary_path.display()),
                format!("Duplicate file in SUMMARY.md: \"{}\"", normalized),
            ]);
        }
        seen.insert(normalized.clone());
    }
    Ok(Chapter {
        name,
        location: if normalized.is_empty() { None } else { Some(PathBuf::from(&normalized)) },
        location_raw: Some(normalized.clone()),
        number: None,
        sub_items: Vec::new(),
        content: String::new(),
        path_html: None,
        source_path_display: normalized,
    })
}

fn parse_heading_line(trimmed: &str) -> Option<(usize, String)> {
    if !trimmed.starts_with('#') { return None; }
    let mut level = 0;
    for c in trimmed.chars() { if c == '#' { level += 1; } else { break; } }
    if level > 6 { return None; }
    let rest = &trimmed[level..];
    if !rest.is_empty() && !rest.starts_with(' ') && !rest.starts_with('\t') { return None; }
    let text = rest.trim().trim_end_matches('#').trim().to_string();
    Some((level, text))
}

fn is_separator(trimmed: &str) -> bool {
    let compact: String = trimmed.chars().filter(|c| *c != ' ' && *c != '\t').collect();
    compact.len() >= 3 && compact.chars().all(|c| c == '-')
}

pub fn parse_list_marker(line: &str) -> Option<(usize, usize, Option<u64>, String)> {
    let b = line.as_bytes();
    let mut indent = 0;
    while indent < b.len() && b[indent] == b' ' { indent += 1; }
    let rest = &line[indent..];
    let rb = rest.as_bytes();
    if rb.is_empty() { return None; }
    if (rb[0] == b'-' || rb[0] == b'*' || rb[0] == b'+') && (rb.len() == 1 || rb[1] == b' ' || rb[1] == b'\t') {
        let mut sp = 1; while sp < rb.len() && (rb[sp] == b' ' || rb[sp] == b'\t') { sp += 1; }
        let content = if rb.len() > sp { &rest[sp..] } else { "" };
        return Some((indent, indent + sp, None, content.to_string()));
    }
    let mut j = 0; while j < rb.len() && rb[j].is_ascii_digit() { j += 1; }
    if j >= 1 && j <= 9 && j < rb.len() && (rb[j] == b'.' || rb[j] == b')') && (j + 1 >= rb.len() || rb[j+1] == b' ' || rb[j+1] == b'\t') {
        let num: u64 = rest[..j].parse().unwrap_or(1);
        let mut sp = j + 1; while sp < rb.len() && (rb[sp] == b' ' || rb[sp] == b'\t') { sp += 1; }
        let content = if rb.len() > sp { &rest[sp..] } else { "" };
        return Some((indent, indent + sp, Some(num), content.to_string()));
    }
    None
}

fn parse_summary_link(content: &str) -> Option<(String, String)> {
    let (text, inside, _next) = crate::markdown::parse_link(content, 0)?;
    if inside.starts_with('\u{1}') {
        return None; // reference links in summary need ref defs; handled as failure approximation
    }
    let (dest, _title) = crate::markdown::split_dest_title(&inside);
    Some((text, dest))
}

fn parse_standalone_link(trimmed: &str) -> Option<(String, String)> {
    if !trimmed.starts_with('[') { return None; }
    let (text, inside, next) = crate::markdown::parse_link(trimmed, 0)?;
    if inside.starts_with('\u{1}') { return None; }
    if next != trimmed.len() { return None; }
    let (dest, _) = crate::markdown::split_dest_title(&inside);
    Some((text, dest))
}

