use std::collections::HashSet;
use std::path::{Path, PathBuf};

#[derive(Clone, Debug)]
pub struct Chapter {
    pub name: String,
    pub location: Option<PathBuf>, // relative to src dir, as written (without fragment)
    pub location_raw: Option<String>,
    pub number: Option<Vec<u32>>,
    pub sub_items: Vec<Item>,
    pub content: String,
    pub path_html: Option<PathBuf>, // output path relative, e.g. sub/ch.html (after index conversion)
    pub source_path_display: String, // for test logs: "sub/ch.md"
}

#[derive(Clone, Debug)]
pub enum Item {
    Chapter(Chapter),
    Separator,
    PartTitle(String),
}

#[derive(Clone, Debug, Default)]
pub struct Book {
    pub items: Vec<Item>, // prefix, numbered, suffix in order (flat top-level, with sub_items in chapters)
}

impl Book {
    pub fn chapters_flat(&self) -> Vec<&Chapter> {
        let mut out = Vec::new();
        fn walk<'a>(items: &'a [Item], out: &mut Vec<&'a Chapter>) {
            for it in items {
                if let Item::Chapter(ch) = it {
                    out.push(ch);
                    walk(&ch.sub_items, out);
                }
            }
        }
        walk(&self.items, &mut out);
        out
    }
    pub fn chapters_flat_mut(&mut self) -> Vec<&mut Chapter> {
        let mut out = Vec::new();
        fn walk<'a>(items: &'a mut [Item], out: &mut Vec<&'a mut Chapter>) {
            for it in items.iter_mut() {
                if let Item::Chapter(ch) = it {
                    // SAFETY not needed: use raw pointer trick via split? Instead collect with recursion on each
                    out.push(ch as *mut Chapter);
                }
            }
        }
        // The above approach is awkward; implement iterative pointer collection:
        let mut ptrs: Vec<*mut Chapter> = Vec::new();
        fn collect(items: &mut [Item], ptrs: &mut Vec<*mut Chapter>) {
            for it in items.iter_mut() {
                if let Item::Chapter(ch) = it {
                    ptrs.push(ch as *mut Chapter);
                    collect(&mut ch.sub_items, ptrs);
                }
            }
        }
        collect(&mut self.items, &mut ptrs);
        ptrs.into_iter().map(|p| unsafe { &mut *p }).collect()
    }
}

pub struct Summary {
    pub items: Vec<Item>,
}

fn strip_md_formatting(text: &str) -> String {
    crate::markdown::strip_inline(text)
}

struct NumState {
    counters: Vec<u32>,
}

pub fn parse_summary(text: &str, summary_path: &Path) -> Result<Summary, Vec<String>> {
    let mut items: Vec<Item> = Vec::new();
    let mut seen_paths: HashSet<String> = HashSet::new();
    let lines: Vec<&str> = text.lines().collect();
    let mut first_element_consumed = false;
    let mut numbered_started = false;
    let mut suffix_started = false;
    // number stack: numbers per depth
    let mut number_stack: Vec<u32> = Vec::new();

    let mut i = 0usize;
    // list stack for nesting: Vec of (indent, path of chapters pushed?) We maintain
    // a stack of pointers by index path in the tree. Simpler: maintain a nested
    // insertion via a stack of "chapter index paths".
    // We instead keep a stack of levels where each level is a Vec<Item> being built?
    // Approach: build a tree using recursive helper on collected flat list items
    // with their depth, then assemble at the end for the numbered section. But
    // part titles / separators interleave at top level only.
    #[derive(Debug)]
    struct FlatEntry {
        depth: usize,
        item: Item,
    }
    let mut flat: Vec<FlatEntry> = Vec::new();
    let mut list_stack: Vec<(usize, usize)> = Vec::new(); // (indent, content_indent)

    while i < lines.len() {
        let raw_line = lines[i];
        let line_no = i + 1;
        i += 1;
        let trimmed = raw_line.trim();
        if trimmed.is_empty() { continue; }

        // Title / headings
        if let Some(heading) = parse_heading_line(trimmed) {
            let (level, htext) = heading;
            if !first_element_consumed {
                first_element_consumed = true;
                if level == 1 {
                    continue; // summary title
                } else {
                    continue; // h2+ before anything ignored
                }
            }
            if level == 1 {
                // Part title lands in the numbered items.
                if !suffix_started {
                    numbered_started = true; // part titles belong to numbered section, but a following list continues numbering
                    // Note: a lone part title before any chapter marks numbered
                    // section started for sequencing, matching original where
                    // "# PartTitle" after "# Summary" renders as part title.
                    flat.push(FlatEntry { depth: 0, item: Item::PartTitle(strip_md_formatting(&htext)) });
                }
            }
            // other heading levels ignored (do not trigger suffix)
            continue;
        }

        // Separator
        if is_separator(trimmed) {
            first_element_consumed = true;
            if suffix_started {
                // separators in suffix area are suffix items - order preserved by flat anyway
                flat.push(FlatEntry { depth: 0, item: Item::Separator });
            } else {
                flat.push(FlatEntry { depth: 0, item: Item::Separator });
            }
            continue;
        }

        // List item
        if let Some((indent, content_indent, _ord, content)) = parse_list_marker(raw_line) {
            first_element_consumed = true;
            if suffix_started {
                return Err(vec![
                    format!("Summary parsing failed for file=\"{}\"", summary_path.display()),
                    "There was an error parsing the suffix chapters".to_string(),
                    format!("failed to parse SUMMARY.md line {}, column {}: Suffix chapters cannot be followed by a list", line_no, 1),
                ]);
            }
            numbered_started = true;
            // compute depth using list stack
            // pop siblings/deeper levels
            while let Some(&(ind, _ci)) = list_stack.last() {
                if indent < ind {
                    list_stack.pop();
                } else if indent == ind {
                    list_stack.pop();
                    break;
                } else {
                    break;
                }
            }
            // If indent is greater than top but not reaching its content indent, it's a sibling
            if let Some(&(ind, ci)) = list_stack.last() {
                if indent > ind && indent < ci {
                    list_stack.pop();
                }
            }
            let depth = list_stack.len();
            // parse link at start of content
            let content_trim = content.trim_start();
            match parse_summary_link(content_trim) {
                Some((name, dest)) => {
                    let ch = make_chapter(name, dest, &mut seen_paths, summary_path)?;
                    list_stack.push((indent, content_indent));
                    let _ = depth;
                    flat.push(FlatEntry { depth: list_stack.len() - 1, item: Item::Chapter(ch) });
                }
                None => {
                    // warn like original
                    let got = describe_first_token(content_trim);
                    crate::log_warn!("mdbook_summary", "Expected a start of a link, actually got {}", got);
                    let col = if content_trim.is_empty() { indent } else { indent + 2 };
                    return Err(vec![
                        format!("Summary parsing failed for file=\"{}\"", summary_path.display()),
                        "There was an error parsing the numbered chapters".to_string(),
                        "There was an error parsing the numbered chapters".to_string(),
                        format!("failed to parse SUMMARY.md line {}, column {}: The link items for nested chapters must only contain a hyperlink", line_no, col),
                    ]);
                }
            }
            continue;
        }

        // Paragraph-ish line: standalone link or plain text
        first_element_consumed = true;
        if let Some((name, dest)) = parse_standalone_link(trimmed) {
            let ch = make_chapter(name, dest, &mut seen_paths, summary_path)?;
            if !numbered_started {
                // prefix
                flat.push(FlatEntry { depth: 0, item: Item::Chapter(ch) });
            } else {
                suffix_started = true;
                flat.push(FlatEntry { depth: 0, item: Item::Chapter(ch) });
            }
            continue;
        }
        // Plain paragraph text.
        if numbered_started && !suffix_started {
            // A non-list paragraph after numbered chapters starts the suffix section.
            // But part titles were handled above; plain text itself is ignored.
            suffix_started = true;
        }
        // Otherwise ignore text.
        let _ = line_no;
    }
    let _ = number_stack;

    // Check duplicate paths already done in make_chapter.
    // Assign numbers to numbered chapters.
    // Determine which flat entries are numbered: chapters that are not prefix/suffix.
    // We tracked that implicitly: prefix chapters appear before numbered_started,
    // suffix after suffix_started. But flat lost that info. Recompute by scanning:
    // We recorded depth and item only. Instead we need affix flags. Handle by
    // re-deriving: chapters before the first numbered chapter/part title/separator
    // in numbered section... This is ambiguous; we therefore stored affix info
    // differently below (see Chapter.number = None for affix, assigned later).
    // To assign numbers we need to know boundaries. We kept `numbered_started`
    // transitions in the flat order: we will use a second pass with markers
    // inserted into flat (PartTitle/Separator have no affix info either).
    // Simplest: numbers are assigned in order to all chapters except those we
    // marked with number = Some(vec![]) sentinel for affix.
    let mut flat_items: Vec<Item> = flat.into_iter().map(|e| {
        // depth is encoded via a wrapper we lost; see assemble step in parse_summary_tree
        e.item
    }).collect();
    let _ = &mut flat_items;

    // NOTE: The depth/affix assembly is performed by parse_summary_impl; this
    // function is replaced below.
    let _ = items;
    Ok(Summary { items: flat_items })
}

fn describe_first_token(content: &str) -> String {
    if content.is_empty() {
        return "Some(End(Item))".to_string();
    }
    if content.starts_with("**") || content.starts_with("__") {
        return "Some(Start(Strong))".to_string();
    }
    if content.starts_with('*') || content.starts_with('_') {
        return "Some(Start(Emphasis))".to_string();
    }
    if content.starts_with('<') {
        let tag: String = content.chars().take_while(|c| *c != '>').collect();
        return format!("Some(InlineHtml(Borrowed(\"{}\")))", tag);
    }
    if content.starts_with('`') {
        return "Some(Code(Borrowed(\"\")))".to_string();
    }
    format!("Some(Text(Borrowed(\"{}\")))", content)
}

fn make_chapter(name: String, dest: String, seen: &mut HashSet<String>, summary_path: &Path) -> Result<Chapter, Vec<String>> {
    let name = strip_md_formatting(&name);
    if dest.is_empty() {
        return Ok(Chapter {
            name,
            location: None,
            location_raw: None,
            number: None,
            sub_items: Vec::new(),
            content: String::new(),
            path_html: None,
            source_path_display: String::new(),
        });
    }
    let dest_no_frag = dest.split('#').next().unwrap_or("").to_string();
    // Normalise ./ prefix for duplicate detection and storage
    let normalized = dest_no_frag.trim_start_matches("./").to_string();
    if !normalized.is_empty() {
        if seen.contains(&normalized) {
            return Err(vec![
                format!("Summary parsing failed for file=\"{}\"", summary_path.display()),
                format!("Duplicate file in SUMMARY.md: \"{}\"", normalized),
            ]);
        }
        seen.insert(normalized.clone());
    }
    Ok(Chapter {
        name,
        location: if normalized.is_empty() { None } else { Some(PathBuf::from(&normalized)) },
        location_raw: Some(normalized.clone()),
        number: None,
        sub_items: Vec::new(),
        content: String::new(),
        path_html: None,
        source_path_display: normalized,
    })
}

fn parse_heading_line(trimmed: &str) -> Option<(usize, String)> {
    if !trimmed.starts_with('#') { return None; }
    let mut level = 0;
    for c in trimmed.chars() { if c == '#' { level += 1; } else { break; } }
    if level > 6 { return None; }
    let rest = &trimmed[level..];
    if !rest.is_empty() && !rest.starts_with(' ') && !rest.starts_with('\t') { return None; }
    let text = rest.trim().trim_end_matches('#').trim().to_string();
    Some((level, text))
}

fn is_separator(trimmed: &str) -> bool {
    let compact: String = trimmed.chars().filter(|c| *c != ' ' && *c != '\t').collect();
    compact.len() >= 3 && compact.chars().all(|c| c == '-')
}

pub fn parse_list_marker(line: &str) -> Option<(usize, usize, Option<u64>, String)> {
    let b = line.as_bytes();
    let mut indent = 0;
    while indent < b.len() && b[indent] == b' ' { indent += 1; }
    let rest = &line[indent..];
    let rb = rest.as_bytes();
    if rb.is_empty() { return None; }
    if (rb[0] == b'-' || rb[0] == b'*' || rb[0] == b'+') && (rb.len() == 1 || rb[1] == b' ' || rb[1] == b'\t') {
        let mut sp = 1; while sp < rb.len() && (rb[sp] == b' ' || rb[sp] == b'\t') { sp += 1; }
        let content = if rb.len() > sp { &rest[sp..] } else { "" };
        return Some((indent, indent + sp, None, content.to_string()));
    }
    let mut j = 0; while j < rb.len() && rb[j].is_ascii_digit() { j += 1; }
    if j >= 1 && j <= 9 && j < rb.len() && (rb[j] == b'.' || rb[j] == b')') && (j + 1 >= rb.len() || rb[j+1] == b' ' || rb[j+1] == b'\t') {
        let num: u64 = rest[..j].parse().unwrap_or(1);
        let mut sp = j + 1; while sp < rb.len() && (rb[sp] == b' ' || rb[sp] == b'\t') { sp += 1; }
        let content = if rb.len() > sp { &rest[sp..] } else { "" };
        return Some((indent, indent + sp, Some(num), content.to_string()));
    }
    None
}

fn parse_summary_link(content: &str) -> Option<(String, String)> {
    let (text, inside, _next) = crate::markdown::parse_link(content, 0)?;
    if inside.starts_with('\u{1}') {
        return None; // reference links in summary need ref defs; handled as failure approximation
    }
    let (dest, _title) = crate::markdown::split_dest_title(&inside);
    Some((text, dest))
}

fn parse_standalone_link(trimmed: &str) -> Option<(String, String)> {
    if !trimmed.starts_with('[') { return None; }
    let (text, inside, next) = crate::markdown::parse_link(trimmed, 0)?;
    if inside.starts_with('\u{1}') { return None; }
    if next != trimmed.len() { return None; }
    let (dest, _) = crate::markdown::split_dest_title(&inside);
    Some((text, dest))
}

// ================= Revised parser used by callers =================
pub struct ParsedSummary {
    pub items: Vec<Item>,
}

struct Entry {
    depth: usize,
    affix: bool, // prefix or suffix (unnumbered)
    item: Item,
}

pub fn parse_summary2(text: &str, summary_path: &Path) -> Result<ParsedSummary, Vec<String>> {
    let lines: Vec<&str> = text.lines().collect();
    let mut entries: Vec<Entry> = Vec::new();
    let mut seen: HashSet<String> = HashSet::new();
    let mut first_consumed = false;
    let mut numbered_started = false;
    let mut suffix_started = false;
    let mut list_stack: Vec<(usize, usize)> = Vec::new();
    // Reference definitions in SUMMARY (for [A][] style)
    let mut ref_defs: std::collections::HashMap<String, String> = std::collections::HashMap::new();
    for raw in &lines {
        let t = raw.trim();
        if t.starts_with('[') {
            if let Some(end) = t.find("]:") {
                let label = &t[1..end];
                let dest = t[end+2..].trim().to_string();
                ref_defs.insert(crate::markdown::normalize_ref(label), dest);
            }
        }
    }

    let mut i = 0usize;
    while i < lines.len() {
        let raw = lines[i];
        let line_no = i + 1;
        i += 1;
        let trimmed = raw.trim();
        if trimmed.is_empty() { continue; }

        if let Some((level, htext)) = parse_heading_line(trimmed) {
            if !first_consumed {
                first_consumed = true;
                continue;
            }
            if level == 1 {
                entries.push(Entry { depth: 0, affix: false, item: Item::PartTitle(strip_md_formatting(&htext)) });
                if !suffix_started { numbered_started = true; }
            }
            continue;
        }
        if is_separator(trimmed) {
            first_consumed = true;
            entries.push(Entry { depth: 0, affix: false, item: Item::Separator });
            continue;
        }
        if let Some((indent, content_indent, _ord, content)) = parse_list_marker(raw) {
            first_consumed = true;
            if suffix_started {
                return Err(vec![
                    format!("Summary parsing failed for file=\"{}\"", summary_path.display()),
                    "There was an error parsing the suffix chapters".into(),
                    format!("failed to parse SUMMARY.md line {}, column {}: Suffix chapters cannot be followed by a list", line_no, 1),
                ]);
            }
            numbered_started = true;
            // reference def lines are not list items, fine.
            while let Some(&(ind, _)) = list_stack.last() {
                if indent < ind { list_stack.pop(); } else if indent == ind { list_stack.pop(); break; } else { break; }
            }
            if let Some(&(ind, ci)) = list_stack.last() {
                if indent > ind && indent < ci { list_stack.pop(); }
            }
            let depth = list_stack.len();
            let content_trim = content.trim_start();
            let parsed = parse_summary_link(content_trim).or_else(|| {
                // reference-style: [A][] or [A][label]
                let (text, inside, _) = crate::markdown::parse_link(content_trim, 0)?;
                if let Some(label) = inside.strip_prefix('\u{1}').and_then(|s| s.strip_prefix("ref:")) {
                    let dest = ref_defs.get(&crate::markdown::normalize_ref(label))?.clone();
                    let (d, _) = crate::markdown::split_dest_title(&dest);
                    Some((text, d))
                } else { None }
            });
            match parsed {
                Some((name, dest)) => {
                    let ch = make_chapter(name, dest, &mut seen, summary_path)?;
                    list_stack.push((indent, content_indent));
                    entries.push(Entry { depth, affix: false, item: Item::Chapter(ch) });
                }
                None => {
                    crate::log_warn!("mdbook_summary", "Expected a start of a link, actually got {}", describe_first_token(content_trim));
                    let col = if content_trim.is_empty() { indent } else { indent + 2 };
                    return Err(vec![
                        format!("Summary parsing failed for file=\"{}\"", summary_path.display()),
                        "There was an error parsing the numbered chapters".into(),
                        "There was an error parsing the numbered chapters".into(),
                        format!("failed to parse SUMMARY.md line {}, column {}: The link items for nested chapters must only contain a hyperlink", line_no, col),
                    ]);
                }
            }
            continue;
        }
        // standalone links / paragraphs
        first_consumed = true;
        // A reference definition line should be ignored
        if trimmed.starts_with('[') && trimmed.contains("]:") && !trimmed.starts_with("-") {
            if let Some(end) = trimmed.find("]:") {
                let after = trimmed[end+2..].trim();
                if !after.is_empty() && !after.starts_with('[') {
                    continue;
                }
            }
        }
        if let Some((name, dest)) = parse_standalone_link(trimmed) {
            let ch = make_chapter(name, dest, &mut seen, summary_path)?;
            if !numbered_started {
                entries.push(Entry { depth: 0, affix: true, item: Item::Chapter(ch) });
            } else {
                suffix_started = true;
                entries.push(Entry { depth: 0, affix: true, item: Item::Chapter(ch) });
            }
            continue;
        }
        if numbered_started && !suffix_started {
            suffix_started = true;
        }
    }

    // assign numbers and assemble tree
    let items = assemble(entries);
    Ok(ParsedSummary { items })
}

fn assemble(entries: Vec<Entry>) -> Vec<Item> {
    // Assign section numbers: numbered chapters get counters by depth.
    // Affix chapters keep number None.
    let mut entries = entries;
    let mut counters: Vec<u32> = Vec::new();
    for e in entries.iter_mut() {
        if e.affix { continue; }
        if let Item::Chapter(ch) = &mut e.item {
            if ch.location.is_none() && ch.location_raw.is_none() {
                // draft still numbered
            }
            let depth = e.depth;
            if counters.len() <= depth { counters.resize(depth + 1, 0); }
            counters[depth] += 1;
            counters.truncate(depth + 1);
            let mut num: Vec<u32> = counters[..=depth].to_vec();
            // counters for missing intermediate levels may be 0; normalise
            for v in num.iter_mut() { if *v == 0 { *v = 1; } }
            ch.number = Some(num);
        }
    }

    // Build tree: entries with depth>0 become sub_items of the most recent
    // chapter at depth-1.
    fn push_into(items: &mut Vec<Item>, depth: usize, item: Item) {
        if depth == 0 { items.push(item); return; }
        // find last chapter in items
        for it in items.iter_mut().rev() {
            if let Item::Chapter(ch) = it {
                push_into(&mut ch.sub_items, depth - 1, item);
                return;
            }
        }
        items.push(item);
    }
    let mut root: Vec<Item> = Vec::new();
    for e in entries {
        push_into(&mut root, e.depth, e.item);
    }
    root
}

pub fn load_book(root: &Path, cfg: &serde_json::Value) -> Result<Book, Vec<String>> {
    let src = crate::config::src_dir(root, cfg);
    let summary_path = src.join("SUMMARY.md");
    let text = match std::fs::read_to_string(&summary_path) {
        Ok(t) => t,
        Err(e) => {
            return Err(vec![
                format!("Couldn't open SUMMARY.md in \"{}\" directory", src.display()),
                format!("{}", e),
            ]);
        }
    };
    let summary_path_disp = summary_path.clone();
    let parsed = parse_summary2(&text, &summary_path_disp)?;
    let mut book = Book { items: parsed.items };
    let create_missing = crate::config::get_bool(cfg, &["build", "create-missing"]).unwrap_or(true);
    // load chapters
    load_chapters(&mut book.items, &src, create_missing)?;
    Ok(book)
}

fn load_chapters(items: &mut [Item], src: &Path, create_missing: bool) -> Result<(), Vec<String>> {
    for item in items.iter_mut() {
        if let Item::Chapter(ch) = item {
            if let Some(loc) = ch.location.clone() {
                let file_path = src.join(&loc);
                if !file_path.exists() {
                    if create_missing {
                        // create parent dirs and file
                        let parent_res = file_path.parent().map(|p| std::fs::create_dir_all(p)).unwrap_or(Ok(()));
                        if let Err(e) = parent_res {
                            return Err(vec!["Unable to create missing chapters".into(), format!("{}", e)]);
                        }
                        if let Err(e) = std::fs::write(&file_path, format!("# {}\n", ch.name)) {
                            return Err(vec!["Unable to create missing chapters".into(), format!("{}", e)]);
                        }
                    } else {
                        return Err(vec![
                            format!("Chapter file not found, {}", ch.location_raw.clone().unwrap_or_default()),
                            "No such file or directory (os error 2)".into(),
                        ]);
                    }
                }
                match std::fs::read_to_string(&file_path) {
                    Ok(content) => {
                        crate::log_debug!("mdbook_driver::load", "Loading {} ({})", ch.name, ch.source_path_display);
                        ch.content = content;
                    }
                    Err(e) => {
                        return Err(vec![
                            format!("Chapter file not found, {}", ch.location_raw.clone().unwrap_or_default()),
                            format!("{}", e),
                        ]);
                    }
                }
            }
            load_chapters(&mut ch.sub_items, src, create_missing)?;
        }
    }
    Ok(())
}
