pub fn parse_summary(text: &str, summary_path: &Path) -> Result<Summary, Vec<String>> {
    let mut items: Vec<Item> = Vec::new();
    let mut seen_paths: HashSet<String> = HashSet::new();
    let lines: Vec<&str> = text.lines().collect();
    let mut first_element_consumed = false;
    let mut numbered_started = false;
    let mut suffix_started = false;
    // number stack: numbers per depth
    let mut number_stack: Vec<u32> = Vec::new();

    let mut i = 0usize;
    // list stack for nesting: Vec of (indent, path of chapters pushed?) We maintain
    // a stack of pointers by index path in the tree. Simpler: maintain a nested
    // insertion via a stack of "chapter index paths".
    // We instead keep a stack of levels where each level is a Vec<Item> being built?
    // Approach: build a tree using recursive helper on collected flat list items
    // with their depth, then assemble at the end for the numbered section. But
    // part titles / separators interleave at top level only.
    #[derive(Debug)]
    struct FlatEntry {
        depth: usize,
        item: Item,
    }
    let mut flat: Vec<FlatEntry> = Vec::new();
    let mut list_stack: Vec<(usize, usize)> = Vec::new(); // (indent, content_indent)

    while i < lines.len() {
        let raw_line = lines[i];
        let line_no = i + 1;
