                    format!("Summary parsing failed for file=\"{}\"", summary_path.display()),
                    "There was an error parsing the suffix chapters".to_string(),
                    format!("failed to parse SUMMARY.md line {}, column {}: Suffix chapters cannot be followed by a list", line_no, 1),
                ]);
            }
            numbered_started = true;
            // compute depth using list stack
            // pop siblings/deeper levels
            while let Some(&(ind, _ci)) = list_stack.last() {
                if indent < ind {
                    list_stack.pop();
                } else if indent == ind {
                    list_stack.pop();
                    break;
                } else {
                    break;
                }
            }
            // If indent is greater than top but not reaching its content indent, it's a sibling
            if let Some(&(ind, ci)) = list_stack.last() {
                if indent > ind && indent < ci {
                    list_stack.pop();
                }
            }
            let depth = list_stack.len();
            // parse link at start of content
            let content_trim = content.trim_start();
            match parse_summary_link(content_trim) {
                Some((name, dest)) => {
                    let ch = make_chapter(name, dest, &mut seen_paths, summary_path)?;
                    list_stack.push((indent, content_indent));
                    let _ = depth;
                    flat.push(FlatEntry { depth: list_stack.len() - 1, item: Item::Chapter(ch) });
                }
                None => {
                    // warn like original
                    let got = describe_first_token(content_trim);
                    crate::log_warn!("mdbook_summary", "Expected a start of a link, actually got {}", got);
                    let col = if content_trim.is_empty() { indent } else { indent + 2 };
                    return Err(vec![
                        format!("Summary parsing failed for file=\"{}\"", summary_path.display()),
                        "There was an error parsing the numbered chapters".to_string(),
                        "There was an error parsing the numbered chapters".to_string(),
                        format!("failed to parse SUMMARY.md line {}, column {}: The link items for nested chapters must only contain a hyperlink", line_no, col),
                    ]);
                }
            }
            continue;
        }

        // Paragraph-ish line: standalone link or plain text
        first_element_consumed = true;
        if let Some((name, dest)) = parse_standalone_link(trimmed) {
            let ch = make_chapter(name, dest, &mut seen_paths, summary_path)?;
            if !numbered_started {
                // prefix
                flat.push(FlatEntry { depth: 0, item: Item::Chapter(ch) });
            } else {
                suffix_started = true;
                flat.push(FlatEntry { depth: 0, item: Item::Chapter(ch) });
            }
            continue;
        }
        // Plain paragraph text.
        if numbered_started && !suffix_started {
            // A non-list paragraph after numbered chapters starts the suffix section.
            // But part titles were handled above; plain text itself is ignored.
            suffix_started = true;
        }
        // Otherwise ignore text.
        let _ = line_no;
    }
    let _ = number_stack;

    // Check duplicate paths already done in make_chapter.
    // Assign numbers to numbered chapters.
    // Determine which flat entries are numbered: chapters that are not prefix/suffix.
    // We tracked that implicitly: prefix chapters appear before numbered_started,
    // suffix after suffix_started. But flat lost that info. Recompute by scanning:
    // We recorded depth and item only. Instead we need affix flags. Handle by
