{"command":"cat > src/preprocess.rs <<'RS'
use crate::book::{Book, Chapter, Item};
use serde_json::{json, Value};
use std::path::{Path, PathBuf};

pub fn chapter_dir(ch: &Chapter, src_dir: &Path) -> PathBuf {
    match &ch.location {
        Some(loc) => {
            let full = src_dir.join(loc);
            full.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| src_dir.to_path_buf())
        }
        None => src_dir.to_path_buf(),
    }
}

// ---------------- links preprocessor ----------------

pub fn expand_links(content: &str, base_dir: &Path, chapter: &mut Chapter, src_dir: &Path, depth: usize) -> String {
    expand_links_inner(content, base_dir, chapter, src_dir, depth)
}

fn expand_links_inner(content: &str, base_dir: &Path, chapter: &mut Chapter, _src_dir: &Path, depth: usize) -> String {
    if depth > 20 { return content.to_string(); }
    let mut out = String::new();
    let mut rest = content;
    loop {
        // find escaped \{{ first, and normal {{#
        let norm = find_helper(rest);
        match norm {
            None => { out.push_str(rest); break; }
            Some((idx, escaped)) => {
                out.push_str(&rest[..idx]);
                if escaped {
                    // remove the backslash, keep the literal {{...}}
                    // rest[idx] is '\\', the helper starts after it
                    let after_bs = &rest[idx+1..];
                    out.push_str(after_bs.split("}}").next().unwrap_or(""));
                    // handled below by advancing generically
                    // Simpler: push "{{" etc and advance past the opening
                    // We already pushed up to after first }} segment start; instead reconstruct:
                    // To avoid complexity, treat escaped as literal up to "}}"
                    if let Some(end) = after_bs.find("}}") {
                        // out currently has out[..idx] + after_bs[..first }} segment]; fix:
                        // It already contains exactly after_bs up to before }}.
                        // Add the closing and continue.
                        out.push_str("}}");
                        rest = &after_bs[end+2..];
                    } else {
                        rest = after_bs;
                    }
                    continue;
                }
                let start = idx;
                let helper_start = start; // index of "{{"
                let after_open = &rest[helper_start+2..];
                if let Some(end_rel) = after_open.find("}}") {
                    let inner = after_open[..end_rel].trim().to_string();
                    let whole = &rest[helper_start..helper_start+2+end_rel+2];
                    let replacement = handle_helper(&inner, whole, base_dir, chapter, depth);
                    match replacement {
                        Some(rep) => out.push_str(&rep),
                        None => out.push_str(whole),
                    }
                    rest = &rest[helper_start+2+end_rel+2..];
                } else {
                    out.push_str(&rest[helper_start..]);
                    break;
                }
            }
        }
    }
    out
}

fn find_helper(s: &str) -> Option<(usize, bool)> {
    let mut idx = 0usize;
    let b = s.as_bytes();
    while idx < b.len() {
        if s[idx..].starts_with("\\{{") {
            return Some((idx, true));
        }
        if s[idx..].starts_with("{{#") || s[idx..].starts_with("{{ #") {
            return Some((idx, false));
        }
        idx += 1;
        // skip multibyte safely
        while idx < b.len() && (b[idx] & 0xC0) == 0x80 { idx += 1; }
    }
    None
}

fn handle_helper(inner: &str, whole: &str, base_dir: &Path, chapter: &mut Chapter, depth: usize) -> Option<String> {
    let inner_trim = inner.trim_start_matches('#').trim();
    let mut parts = inner_trim.splitn(2, |c: char| c.is_whitespace());
    let kind = parts.next().unwrap_or("");
    let args = parts.next().unwrap_or("").trim();
    match kind {
        "include" => {
            let (file_arg, spec) = split_file_spec(args);
            let path = base_dir.join(&file_arg);
            match read_include(&path, &spec) {
                Ok(text) => {
                    let new_base = path.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| base_dir.to_path_buf());
                    Some(expand_links_inner(&text, &new_base, chapter, base_dir, depth + 1))
                }
                Err(e) => {
                    crate::log_error!("mdbook_driver::builtin_preprocessors::links", "Error updating \"{}\", Could not read file for link {} ({})", whole, whole, path.display());
                    crate::log_warn!("mdbook_driver::builtin_preprocessors::links", "Caused By: {}", e);
                    None
                }
            }
        }
        "rustdoc_include" => {
            let (file_arg, spec) = split_file_spec(args);
            let path = base_dir.join(&file_arg);
            match std::fs::read_to_string(&path) {
                Ok(text) => {
                    let transformed = rustdoc_transform(&text, &spec);
                    let new_base = path.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| base_dir.to_path_buf());
                    Some(expand_links_inner(&transformed, &new_base, chapter, base_dir, depth + 1))
                }
                Err(e) => {
                    crate::log_error!("mdbook_driver::builtin_preprocessors::links", "Error updating \"{}\", Could not read file for link {} ({})", whole, whole, path.display());
                    crate::log_warn!("mdbook_driver::builtin_preprocessors::links", "Caused By: {}", e);
                    None
                }
            }
        }
        "playground" => {
            // first token is file, rest are attributes
            let mut toks = args.split_whitespace();
            let file_arg = toks.next().unwrap_or("");
            let attrs: Vec<&str> = toks.collect();
            let path = base_dir.join(file_arg);
            match std::fs::read_to_string(&path) {
                Ok(text) => {
                    let info = if attrs.is_empty() { "rust".to_string() } else { format!("rust,{}", attrs.join(",")) };
                    let mut code = text.clone();
                    if !code.ends_with('\n') { code.push('\n'); }
                    Some(format!("```{}\n{}```", info, code))
                }
                Err(e) => {
                    crate::log_error!("mdbook_driver::builtin_preprocessors::links", "Error updating \"{}\", Could not read file for link {} ({})", whole, whole, path.display());
                    crate::log_warn!("mdbook_driver::builtin_preprocessors::links", "Caused By: {}", e);
                    None
                }
            }
        }
        "title" => {
            chapter.page_title = Some(args.to_string());
            Some(String::new())
        }
        _ => None,
    }
}

fn split_file_spec(args: &str) -> (String, String) {
    // args is first whitespace token for include/rustdoc
    let token = args.split_whitespace().next().unwrap_or("");
    if let Some(pos) = token.find(':') {
        (token[..pos].to_string(), token[pos+1..].to_string())
    } else {
        (token.to_string(), String::new())
    }
}

fn read_include(path: &Path, spec: &str) -> Result<String, std::io::Error> {
    let text = std::fs::read_to_string(path)?;
    Ok(select_lines(&text, spec, false))
}

pub fn select_lines(text: &str, spec: &str, rustdoc: bool) -> String {
    if spec.is_empty() { return text.to_string(); }
    let lines: Vec<&str> = text.lines().collect();
    // anchor?
    let is_anchor = !spec.is_empty() && spec.split(':').all(|p| p.parse::<i64>().is_err()) && !spec.chars().all(|c| c == ':') && spec.split(':').count() == 1;
    if is_anchor {
        return extract_anchor(&lines, spec);
    }
    let (start, end) = parse_range(spec, lines.len());
    lines[start..end].join("\n")
}

fn parse_range(spec: &str, total: usize) -> (usize, usize) {
    // returns 0-based [start, end)
    let parts: Vec<&str> = spec.split(':').collect();
    let to_idx = |s: &str, default: usize| -> usize {
        if s.is_empty() { default } else { s.parse::<usize>().unwrap_or(default) }
    };
    match parts.len() {
        1 => {
            let n = to_idx(parts[0], 1);
            let s = n.saturating_sub(1).min(total);
            (s, (s + 1).min(total))
        }
        2 => {
            // "a:b" or ":b" (encoded as ":b" => parts ["","b"] but our split_file_spec removed first colon)
            // Here spec is after first colon: for include file.rs::10, spec=":10"
            if parts[0].is_empty() {
                let e = to_idx(parts[1], total).min(total);
                (0, e)
            } else {
                let s = to_idx(parts[0], 1).saturating_sub(1).min(total);
                let e = if parts[1].is_empty() { total } else { to_idx(parts[1], total).min(total) };
                (s, e)
            }
        }
        _ => (0, total),
    }
}

fn extract_anchor(lines: &[&str], name: &str) -> String {
    let start_pat = format!("ANCHOR: {}", name);
    let end_pat = format!("ANCHOR_END: {}", name);
    let mut inside = false;
    let mut out: Vec<&str> = Vec::new();
    for line in lines {
        if !inside && line.contains(&start_pat) { inside = true; continue; }
        if inside && line.contains(&end_pat) { break; }
        if inside {
            if line.contains("ANCHOR:") || line.contains("ANCHOR_END:") { continue; }
            out.push(line);
        }
    }
    out.join("\n")
}

fn rustdoc_transform(text: &str, spec: &str) -> String {
    let lines: Vec<&str> = text.lines().collect();
    if spec.is_empty() {
        return lines.iter().map(|l| hide_line(l, true)).collect::<Vec<_>>().join("\n");
        // Note: with no spec, original treats whole file as hidden? That path
        // is rarely used; see select behaviour below.
    }
    let is_anchor = !spec.is_empty() && spec.split(':').count() == 1 && spec.parse::<i64>().is_err() && !spec.chars().all(|c| c == ':');
    let mut out: Vec<String> = Vec::new();
    if is_anchor {
        // find anchor region
        let start_pat = format!("ANCHOR: {}", spec);
        let end_pat = format!("ANCHOR_END: {}", spec);
        let mut in_anchor = false;
        let mut started = false;
        for line in &lines {
            if !in_anchor && line.contains(&start_pat) { in_anchor = true; started = true; continue; }
            if in_anchor && line.contains(&end_pat) { in_anchor = false; continue; }
            if line.contains("ANCHOR:") || line.contains("ANCHOR_END:") {
                if in_anchor { continue; }
                out.push(hide_line(line, false));
                continue;
            }
            if in_anchor { out.push(line.to_string()); }
            else { out.push(hide_line(line, false)); }
        }
        let _ = started;
        return out.join("\n");
    }
    let (s, e) = parse_range(spec, lines.len());
    for (idx, line) in lines.iter().enumerate() {
        if idx >= s && idx < e { out.push(line.to_string()); }
        else { out.push(hide_line(line, false)); }
    }
    // rustdoc_include outside anchor: original keeps a trailing newline?
    let mut res = out.join("\n");
    if text.ends_with('\n') { res.push('\n'); }
    res
}

fn hide_line(line: &str, _all: bool) -> String {
    if line.is_empty() { "#".to_string() } else { format!("# {}", line) }
}

// ---------------- index preprocessor ----------------

pub fn apply_index(book: &mut Book) {
    fn walk(items: &mut [Item]) {
        for it in items.iter_mut() {
            if let Item::Chapter(ch) = it {
                if let Some(loc) = &ch.location {
                    if let Some(fname) = loc.file_name().and_then(|s| s.to_str()) {
                        if fname.to_ascii_lowercase() == "readme.md" || fname.to_ascii_lowercase() == "readme.markdown" {
                            let mut new_loc = loc.clone();
                            new_loc.set_file_name("index.md");
                            ch.location = Some(new_loc);
                        }
                    }
                }
                walk(&mut ch.sub_items);
            }
        }
    }
    walk(&mut book.items);
}

// ---------------- whole preprocessor pipeline ----------------

pub fn book_to_json(book: &Book) -> Value {
    json!({ "sections": items_to_json(&book.items, &[]), "__non_exhaustive": null })
}

fn items_to_json(items: &[Item], parents: &[String]) -> Value {
    let mut arr = Vec::new();
    for it in items {
        match it {
            Item::Separator => arr.push(json!("Separator")),
            Item::PartTitle(t) => arr.push(json!({"PartTitle": t})),
            Item::Chapter(ch) => {
                let mut new_parents = parents.to_vec();
                // recursive serialisation handles parents via arg below
                arr.push(json!({"Chapter": chapter_to_json(ch, parents)}));
                let _ = &mut new_parents;
            }
        }
    }
    Value::Array(arr)
}

fn chapter_to_json(ch: &Chapter, parents: &[String]) -> Value {
    let mut sub_parents = parents.to_vec();
    sub_parents.push(ch.name.clone());
    json!({
        "name": ch.name,
        "content": ch.content,
        "number": match &ch.number { Some(n) => json!(n), None => Value::Null },
        "sub_items": items_to_json(&ch.sub_items, &sub_parents),
        "path": match &ch.location { Some(p) => json!(p.to_string_lossy().replace('\\', "/")), None => Value::Null },
        "source_path": if ch.location.is_some() || !ch.source_path_display.is_empty() {
            if ch.source_path_display.is_empty() { Value::Null } else { json!(ch.source_path_display) }
        } else { Value::Null },
        "parent_names": parents,
    })
}

pub fn book_from_json(v: &Value) -> Option<Book> {
    let sections = v.get("sections")?.as_array()?;
    Some(Book { items: items_from_json(sections) })
}

fn items_from_json(arr: &[Value]) -> Vec<Item> {
    let mut out = Vec::new();
    for v in arr {
        if let Some(s) = v.as_str() {
            if s == "Separator" { out.push(Item::Separator); }
            continue;
        }
        if let Some(t) = v.get("PartTitle") {
            out.push(Item::PartTitle(t.as_str().unwrap_or("").to_string()));
            continue;
        }
        if let Some(chv) = v.get("Chapter") {
            out.push(Item::Chapter(chapter_from_json(chv)));
        }
    }
    out
}

fn chapter_from_json(v: &Value) -> Chapter {
    let path = v.get("path").and_then(|p| p.as_str()).map(|s| PathBuf::from(s));
    let source = v.get("source_path").and_then(|p| p.as_str()).map(|s| s.to_string());
    let number = v.get("number").and_then(|n| n.as_array()).map(|a| a.iter().filter_map(|x| x.as_u64().map(|u| u as u32)).collect::<Vec<u32>>());
    Chapter {
        name: v.get("name").and_then(|s| s.as_str()).unwrap_or("").to_string(),
        location: path.clone(),
        location_raw: path.as_ref().map(|p| p.to_string_lossy().to_string()),
        number,
        sub_items: v.get("sub_items").and_then(|s| s.as_array()).map(|a| items_from_json(a)).unwrap_or_default(),
        content: v.get("content").and_then(|s| s.as_str()).unwrap_or("").to_string(),
        path_html: None,
        source_path_display: source.clone().unwrap_or_else(|| path.as_ref().map(|p| p.to_string_lossy().to_string()).unwrap_or_default()),
        page_title: None,
    }
}

pub fn context_config(cfg: &Value) -> Value {
    let mut c = cfg.clone();
    if !c.is_object() { c = json!({}); }
    let book = c.as_object_mut().unwrap().entry("book".to_string()).or_insert_with(|| json!({}));
    if book.is_object() {
        let b = book.as_object_mut().unwrap();
        b.entry("authors".to_string()).or_insert_with(|| json!([]));
        b.entry("language".to_string()).or_insert_with(|| json!("en"));
        b.entry("src".to_string()).or_insert_with(|| json!("src"));
    }
    c
}

struct PpDef {
    name: String,
    cfg: Value,
}

pub fn run_preprocessors(book: &Book, cfg: &Value, root: &Path, renderer: &str, src_dir: &Path) -> Result<Book, Vec<String>> {
    let mut book = book.clone();
    // determine definitions
    let use_defaults = crate::config::get_bool(cfg, &["build", "use-default-preprocessors"]).unwrap_or(true);
    let pp_cfg = crate::config::get(cfg, &["preprocessor"]).cloned().unwrap_or_else(|| json!({}));
    let mut names: Vec<String> = Vec::new();
    if use_defaults {
        names.push("index".to_string());
        names.push("links".to_string());
    }
    if let Some(obj) = pp_cfg.as_object() {
        for k in obj.keys() {
            if !names.contains(k) { names.push(k.clone()); }
        }
    }
    // sort with before/after constraints, alphabetical tiebreak
    let ordered = order_preprocessors(&names, &pp_cfg);
    for name in ordered {
        // renderer filter for custom preprocessors
        let this_cfg = pp_cfg.get(&name).cloned().unwrap_or_else(|| json!({}));
        if name != "index" && name != "links" {
            if let Some(renderers) = this_cfg.get("renderers").and_then(|r| r.as_array()) {
                let strs: Vec<String> = renderers.iter().filter_map(|v| v.as_str().map(|s| s.to_string())).collect();
                if !strs.iter().any(|s| s == renderer) { continue; }
            }
        }
        match name.as_str() {
            "index" => {
                crate::log_debug!("mdbook_driver::mdbook", "Running the index preprocessor.");
                apply_index(&mut book);
            }
            "links" => {
                crate::log_debug!("mdbook_driver::mdbook", "Running the links preprocessor.");
                apply_links(&mut book, src_dir);
            }
            _ => {
                let def = PpDef { name: name.clone(), cfg: this_cfg };
                book = run_custom_preprocessor(&def, book, cfg, root, renderer)?;
            }
        }
    }
    Ok(book)
}

pub fn apply_links(book: &mut Book, src_dir: &Path) {
    let mut chapters = book.chapters_flat_mut();
    for ch in chapters.iter_mut() {
        if ch.location.is_some() || !ch.source_path_display.is_empty() {
            // base dir from source_path (original locations before index conversion)
            let src_rel = if !ch.source_path_display.is_empty() { ch.source_path_display.clone() } else { ch.location.as_ref().map(|p| p.to_string_lossy().to_string()).unwrap_or_default() };
            let base = src_dir.join(&src_rel).parent().map(|p| p.to_path_buf()).unwrap_or_else(|| src_dir.to_path_buf());
            let content = ch.content.clone();
            ch.content = expand_links_inner(&content, &base, ch, src_dir, 0);
        }
    }
}

fn order_preprocessors(names: &[String], pp_cfg: &Value) -> Vec<String> {
    // edges: a -> b means a must come before b
    let mut edges: Vec<(String, String)> = Vec::new();
    for name in names {
        if let Some(cfg) = pp_cfg.get(name) {
            if let Some(afters) = cfg.get("after").and_then(|v| v.as_array()) {
                for a in afters.iter().filter_map(|v| v.as_str()) {
                    if names.contains(&a.to_string()) { edges.push((a.to_string(), name.clone())); }
                }
            }
            if let Some(befores) = cfg.get("before").and_then(|v| v.as_array()) {
                for b in befores.iter().filter_map(|v| v.as_str()) {
                    if names.contains(&b.to_string()) { edges.push((name.clone(), b.to_string())); }
                }
            }
        }
    }
    let mut result: Vec<String> = Vec::new();
    let mut remaining: Vec<String> = names.to_vec();
    remaining.sort();
    while !remaining.is_empty() {
        // find a node with no incoming edges from remaining
        let mut picked: Option<String> = None;
        for cand in &remaining {
            let blocked = edges.iter().any(|(a, b)| b == cand && remaining.contains(a));
            if !blocked { picked = Some(cand.clone()); break; }
        }
        match picked {
            Some(p) => { remaining.retain(|x| x != &p); result.push(p); }
            None => {
                // cycle: append the rest alphabetically
                result.extend(remaining.drain(..));
            }
        }
    }
    result
}

fn run_custom_preprocessor(def: &PpDef, book: Book, cfg: &Value, root: &Path, renderer: &str) -> Result<Book, Vec<String>> {
    let command_str = def.cfg.get("command").and_then(|v| v.as_str()).map(|s| s.to_string()).unwrap_or_else(|| format!("mdbook-{}", def.name));
    let args = crate::shell_words::split(&command_str);
    if args.is_empty() {
        return Ok(book);
    }
    let (prog, rest_args) = args.split_first().unwrap();
    // supports check
    let supports = std::process::Command::new(prog).args(rest_args).arg("supports").arg(renderer).stdin(std::process::Stdio::null()).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::inherit()).status();
    match supports {
        Err(e) => {
            if e.kind() == std::io::ErrorKind::NotFound {
                crate::log_warn!("mdbook_driver::builtin_preprocessors::cmd", "The command wasn't found, is the \"{}\" preprocessor installed?", def.name);
                crate::log_warn!("mdbook_driver::builtin_preprocessors::cmd", "\tCommand: {}", command_str);
                return Ok(book);
            }
            return Ok(book);
        }
        Ok(status) => {
            if !status.success() { return Ok(book); }
        }
    }
    let ctx = json!({
        "root": root.to_string_lossy(),
        "config": context_config(cfg),
        "renderer": renderer,
        "mdbook_version": "0.5.0-alpha.1",
    });
    let input = json!([ctx, book_to_json(&book)]).to_string();
    let mut child = match std::process::Command::new(prog).args(rest_args).stdin(std::process::Stdio::piped()).stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::inherit()).spawn() {
        Ok(c) => c,
        Err(e) => {
            if e.kind() == std::io::ErrorKind::NotFound {
                crate::log_warn!("mdbook_driver::builtin_preprocessors::cmd", "The command wasn't found, is the \"{}\" preprocessor installed?", def.name);
                crate::log_warn!("mdbook_driver::builtin_preprocessors::cmd", "\tCommand: {}", command_str);
                return Ok(book);
            }
            return Ok(book);
        }
    };
    use std::io::Write;
    if let Some(mut stdin) = child.stdin.take() {
        let _ = stdin.write_all(input.as_bytes());
    }
    let output = child.wait_with_output().map_err(|e| vec![format!("{}", e)])?;
    if !output.status.success() {
        let code = output.status.code().map(|c| c.to_string()).unwrap_or_else(|| "?".to_string());
        return Err(vec![format!("The \"{}\" preprocessor exited unsuccessfully with exit status: {} status", def.name, code)]);
    }
    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    match serde_json::from_str::<Value>(&stdout) {
        Ok(v) => match book_from_json(&v) {
            Some(b) => Ok(b),
            None => Err(vec![format!("Unable to parse the preprocessed book from \"{}\" processor", def.name), "missing field `sections`".to_string()]),
        },
        Err(e) => Err(vec![format!("Unable to parse the preprocessed book from \"{}\" processor", def.name), e.to_string()]),
    }
}
