pub fn split(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut cur = String::new();
    let mut chars = s.chars().peekable();
    let mut has = false;
    while let Some(c) = chars.next() {
        match c {
            ' ' | '\t' | '\n' => { if has || !cur.is_empty() { out.push(cur.clone()); cur.clear(); has = false; } }
            '"' => { has = true; while let Some(ch) = chars.next() { if ch == '"' { break; } else if ch == '\\' { if let Some(n) = chars.next() { cur.push(n); } } else { cur.push(ch); } } }
            '\'' => { has = true; while let Some(ch) = chars.next() { if ch == '\'' { break; } else { cur.push(ch); } } }
            '\\' => { has = true; if let Some(n) = chars.next() { cur.push(n); } }
            _ => { has = true; cur.push(c); }
        }
    }
    if has || !cur.is_empty() { out.push(cur); }
    out
}
