use serde_json::Value;
use std::collections::HashMap;

pub struct Renderer<'a> {
    pub partials: &'a HashMap<String, String>,
    pub resource_fn: &'a dyn Fn(&str, &Value) -> String,
    pub toc_html: String,
}

fn html_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#x27;"),
            '`' => out.push_str("&#x60;"),
            '=' => out.push_str("&#x3D;"),
            _ => out.push(c),
        }
    }
    out
}

fn truthy(v: &Value) -> bool {
    match v {
        Value::Null => false,
        Value::Bool(b) => *b,
        Value::Number(n) => n.as_f64().map_or(false, |f| f != 0.0),
        Value::String(s) => !s.is_empty(),
        Value::Array(a) => !a.is_empty(),
        Value::Object(_) => true,
    }
}

fn value_to_string(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::String(s) => s.clone(),
        Value::Array(_) | Value::Object(_) => serde_json::to_string(v).unwrap_or_default(),
    }
}

pub fn lookup(ctx: &Value, path: &str) -> Value {
    let p = path.trim();
    if p == "this" || p == "." { return ctx.clone(); }
    let mut cur = ctx.clone();
    let mut parts = p.split('.');
    let first = parts.next().unwrap_or("");
    if first == "this" {
        // continue with cur
    } else if !first.is_empty() {
        match cur.get(first) { Some(v) => cur = v.clone(), None => return Value::Null }
    }
    for part in parts {
        match cur.get(part) { Some(v) => cur = v.clone(), None => return Value::Null }
    }
    cur
}

struct Tag {
    content: String,
    end: usize, // byte index after tag
    triple: bool,
}

fn next_tag(tpl: &str, from: usize) -> Option<(usize, Tag)> {
    let start = tpl[from..].find("{{").map(|p| from + p)?;
    if tpl[start..].starts_with("{{{") {
        let end = tpl[start+3..].find("}}}").map(|p| start + 3 + p)?;
        Some((start, Tag { content: tpl[start+3..end].to_string(), end: end + 3, triple: true }))
    } else if tpl[start..].starts_with("{{!--") {
        let end = tpl[start+4..].find("--}}").map(|p| start + 4 + p)?;
        Some((start, Tag { content: "!comment".to_string(), end: end + 4, triple: false }))
    } else {
        let end = tpl[start+2..].find("}}").map(|p| start + 2 + p)?;
        Some((start, Tag { content: tpl[start+2..end].to_string(), end: end + 2, triple: false }))
    }
}

// Find the matching close for a block beginning after `from`, handling nesting of same-name blocks.
// Returns (inner_end, after_close, else_range) where else_range is the {{else}} split if present.
fn find_block_end(tpl: &str, from: usize, name: &str) -> Option<(usize, usize, Option<(usize, usize)>)> {
    let mut depth = 0usize;
    let mut pos = from;
    let mut else_span: Option<(usize, usize)> = None;
    while let Some((start, tag)) = next_tag(tpl, pos) {
        let c = tag.content.trim().trim_start_matches('~').trim_end_matches('~').trim().to_string();
        if c.starts_with(&format!("#{}", name)) || (name == "if" && c.starts_with("#if")) {
            // Only count same block type openers
            if block_name(&c) == Some(name.to_string()) { depth += 1; }
        } else if c == format!("/{}", name) {
            if depth == 0 {
                return Some((start, tag.end, else_span));
            }
            depth -= 1;
        } else if c == "else" && depth == 0 {
            else_span = Some((start, tag.end));
        }
        pos = tag.end;
    }
    None
}

fn block_name(c: &str) -> Option<String> {
    let t = c.trim_start_matches('#');
    let first = t.split_whitespace().next().unwrap_or("");
    Some(first.to_string())
}

impl<'a> Renderer<'a> {
    pub fn render(&self, tpl: &str, ctx: &Value) -> String {
        self.render_inner(tpl, ctx, 0)
    }

    fn render_inner(&self, tpl: &str, ctx: &Value, depth: usize) -> String {
        if depth > 50 { return tpl.to_string(); }
        let mut out = String::new();
        let mut pos = 0usize;
        while pos < tpl.len() {
            let found = next_tag(tpl, pos);
            match found {
                None => { out.push_str(&tpl[pos..]); break; }
                Some((start, tag)) => {
                    out.push_str(&tpl[pos..start]);
                    let raw = tag.content.clone();
                    let c = raw.trim().trim_start_matches('~').trim_end_matches('~').trim().to_string();
                    if c.starts_with('!') { pos = tag.end; continue; }
                    if tag.triple {
                        // {{{ var }}} or {{{ helper }}}
                        if let Some(v) = self.eval_expr(&c, ctx) {
                            out.push_str(&v);
                        } else {
                            out.push_str(&value_to_string(&lookup(ctx, &c)));
                        }
                        pos = tag.end; continue;
                    }
                    // partial
                    if let Some(name) = c.strip_prefix('>') {
                        let name = name.trim();
                        if let Some(p) = self.partials.get(name) {
                            let cloned = p.clone();
                            out.push_str(&self.render_inner(&cloned, ctx, depth + 1));
                        }
                        pos = tag.end; continue;
