            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#x27;"),
            '`' => out.push_str("&#x60;"),
            '=' => out.push_str("&#x3D;"),
            _ => out.push(c),
        }
    }
    out
}

fn truthy(v: &Value) -> bool {
    match v {
        Value::Null => false,
        Value::Bool(b) => *b,
        Value::Number(n) => n.as_f64().map_or(false, |f| f != 0.0),
        Value::String(s) => !s.is_empty(),
        Value::Array(a) => !a.is_empty(),
        Value::Object(_) => true,
    }
}

fn value_to_string(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => n.to_string(),
        Value::String(s) => s.clone(),
        Value::Array(_) | Value::Object(_) => serde_json::to_string(v).unwrap_or_default(),
    }
}

pub fn lookup(ctx: &Value, path: &str) -> Value {
    let p = path.trim();
    if p == "this" || p == "." { return ctx.clone(); }
    let mut cur = ctx.clone();
    let mut parts = p.split('.');
    let first = parts.next().unwrap_or("");
    if first == "this" {
        // continue with cur
    } else if !first.is_empty() {
        match cur.get(first) { Some(v) => cur = v.clone(), None => return Value::Null }
    }
    for part in parts {
        match cur.get(part) { Some(v) => cur = v.clone(), None => return Value::Null }
    }
    cur
}

struct Tag {
    content: String,
    end: usize, // byte index after tag
    triple: bool,
}

fn next_tag(tpl: &str, from: usize) -> Option<(usize, Tag)> {
    let start = tpl[from..].find("{{").map(|p| from + p)?;
    if tpl[start..].starts_with("{{{") {
        let end = tpl[start+3..].find("}}}").map(|p| start + 3 + p)?;
        Some((start, Tag { content: tpl[start+3..end].to_string(), end: end + 3, triple: true }))
    } else if tpl[start..].starts_with("{{!--") {
        let end = tpl[start+4..].find("--}}").map(|p| start + 4 + p)?;
        Some((start, Tag { content: "!comment".to_string(), end: end + 4, triple: false }))
    } else {
        let end = tpl[start+2..].find("}}").map(|p| start + 2 + p)?;
        Some((start, Tag { content: tpl[start+2..end].to_string(), end: end + 2, triple: false }))
    }
