// Returns (inner_end, after_close, else_range) where else_range is the {{else}} split if present.
fn find_block_end(tpl: &str, from: usize, name: &str) -> Option<(usize, usize, Option<(usize, usize)>)> {
    let mut depth = 0usize;
    let mut pos = from;
