pub const SEARCHER_JS: &str = r##"// Search over the index generated in searchindex.js (window.search).
(function () {
    'use strict';
    var searchbar = document.getElementById('searchbar');
    if (!searchbar) { return; }
    var resultsOuter = document.getElementById('searchresults-outer');
    var results = document.getElementById('searchresults');
    var header = document.getElementById('searchresults-header');
    function docs() {
        if (!window.search || !window.search.index || !window.search.index.documentStore) { return []; }
        var store = window.search.index.documentStore;
        var urls = window.search.doc_urls || [];
        var out = [];
        Object.keys(store.docs || {}).forEach(function (id) {
            var d = store.docs[id];
            out.push({ id: id, title: d.title || '', body: d.body || '', breadcrumbs: d.breadcrumbs || '', url: urls[Number(id)] || '' });
        });
        return out;
    }
    function teaser(body, terms) {
        var words = body.split(/\s+/);
        var limit = (window.search && window.search.results_options && window.search.results_options.teaser_word_count) || 30;
        return words.slice(0, limit).join(' ') + (words.length > limit ? ' ...' : '');
    }
    searchbar.addEventListener('input', function () {
        var query = searchbar.value.trim().toLowerCase();
        results.innerHTML = '';
        if (!query) { resultsOuter.classList.add('hidden'); return; }
        var terms = query.split(/\s+/);
        var opts = (window.search && window.search.search_options) || {};
        var useAnd = opts.bool === 'AND';
        var limit = (window.search && window.search.results_options && window.search.results_options.limit_results) || 30;
        var matches = docs().filter(function (d) {
            var hay = (d.title + ' ' + d.body + ' ' + d.breadcrumbs).toLowerCase();
            return useAnd ? terms.every(function (t) { return hay.indexOf(t) !== -1; }) : terms.some(function (t) { return hay.indexOf(t) !== -1; });
        }).slice(0, limit);
        header.textContent = matches.length ? (matches.length + ' search results for \'' + searchbar.value.trim() + '\'') : 'No search results for \'' + searchbar.value.trim() + '\'.';
        matches.forEach(function (d) {
            var li = document.createElement('li');
            var a = document.createElement('a');
            a.href = (window.path_to_root || '') + d.url;
            a.textContent = d.breadcrumbs || d.title;
            li.appendChild(a);
            var span = document.createElement('span');
            span.className = 'teaser';
            span.textContent = teaser(d.body, terms);
            li.appendChild(span);
            results.appendChild(li);
        });
        resultsOuter.classList.remove('hidden');
    });
})();
"##;

