// Theme and sidebar handling, search toggle, and code block helpers.
(function () {
    var themeToggle = document.getElementById('theme-toggle');
    var themeList = document.getElementById('theme-list');
    if (themeToggle && themeList) {
        themeToggle.addEventListener('click', function () { themeList.classList.toggle('open'); });
        themeList.addEventListener('click', function (e) {
            if (e.target.classList.contains('theme')) {
                var theme = e.target.id === 'default_theme' ? null : e.target.id;
                try { if (theme) { localStorage.setItem('mdbook-theme', theme); } else { localStorage.removeItem('mdbook-theme'); } } catch (err) { }
                location.reload();
            }
        });
    }
    var sidebarToggle = document.getElementById('sidebar-toggle-anchor');
    if (sidebarToggle) {
        sidebarToggle.addEventListener('change', function () {
            document.documentElement.classList.toggle('sidebar-visible', sidebarToggle.checked);
            try { localStorage.setItem('mdbook-sidebar', sidebarToggle.checked ? 'visible' : 'hidden'); } catch (err) { }
        });
    }
    var searchToggle = document.getElementById('search-toggle');
    var searchWrapper = document.getElementById('search-wrapper');
    if (searchToggle && searchWrapper) {
        searchToggle.addEventListener('click', function () {
            searchWrapper.classList.toggle('hidden');
            var bar = document.getElementById('searchbar');
            if (bar) { bar.focus(); }
        });
    }
    document.addEventListener('keydown', function (e) {
        if (e.key === 's' || e.key === '/') {
            var tag = (document.activeElement && document.activeElement.tagName) || '';
            if (tag !== 'INPUT' && tag !== 'TEXTAREA') {
                if (searchWrapper) { searchWrapper.classList.remove('hidden'); }
                var bar2 = document.getElementById('searchbar'); if (bar2) { bar2.focus(); }
            }
        }
        if (e.key === '?') {
            var help = document.getElementById('mdbook-help-container'); if (help) { help.classList.toggle('open'); }
        }
        if (e.key === 'Escape') {
            var help2 = document.getElementById('mdbook-help-container'); if (help2) { help2.classList.remove('open'); }
        }
    });
    // Show hidden ("boring") lines toggles.
    Array.from(document.querySelectorAll('code')).forEach(function (block) {
        var lines = block.querySelectorAll('.boring');
        if (lines.length) { block.classList.add('hide-boring'); }
    });
    // Playground run buttons.
    Array.from(document.querySelectorAll('.playground')).forEach(function (pre) {
        var button = document.createElement('button');
        button.className = 'play-button';
        button.title = 'Run this code in the Rust Playground';
        button.innerHTML = '<i class="fa fa-play"></i>';
        button.addEventListener('click', function () {
            var code = pre.querySelector('code');
            if (!code) { return; }
            var text = code.textContent;
            fetch('https://play.rust-lang.org/execute', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ channel: 'stable', mode: 'debug', edition: '2021', crateType: 'bin', tests: false, code: text, backtrace: false })
            }).then(function (r) { return r.json(); }).then(function (res) {
                var out = document.createElement('pre');
                out.className = 'playground-result';
                out.textContent = (res.stdout || '') + (res.stderr || '');
                pre.parentNode.insertBefore(out, pre.nextSibling);
            }).catch(function () { });
        });
        pre.appendChild(button);
    });
})();
"##;

