pub fn text_direction(cfg: &Value) -> String {
    if let Some(d) = crate::config::get_str(cfg, &["book", "text-direction"]) { return d; }
    let lang = crate::config::get_str(cfg, &["book", "language"]).unwrap_or_else(|| "en".to_string());
    let primary = lang.split(|c| c == '-' || c == '_').next().unwrap_or("en");
    const RTL: &[&str] = &["ar", "arc", "dv", "fa", "ha", "he", "khw", "ks", "ku", "ps", "ur", "yi", "ji", "iw"];
    if RTL.contains(&primary) { "rtl".to_string() } else { "ltr".to_string() }
}

pub fn output_html_path(ch: &Chapter) -> Option<PathBuf> {
    let loc = ch.location.as_ref()?;
    let mut p = loc.clone();
    p.set_extension("html");
    Some(p)
}

pub fn path_to_root(html_path: &Path) -> String {
    let parent = html_path.parent();
    match parent {
        Some(p) => {
            let depth = p.components().count();
            if p.as_os_str().is_empty() { String::new() } else { "../".repeat(depth) }
        }
        None => String::new(),
    }
}

fn slash(p: &Path) -> String { p.to_string_lossy().replace('\\', "/") }

pub fn flatten_with_parents(book: &Book) -> Vec<(Chapter, Vec<String>)> {
    let mut out = Vec::new();
    fn walk(items: &[Item], parents: Vec<String>, out: &mut Vec<(Chapter, Vec<String>)>) {
        for it in items {
            if let Item::Chapter(ch) = it {
                out.push((ch.clone(), parents.clone()));
                let mut np = parents.clone();
                np.push(ch.name.clone());
                walk(&ch.sub_items, np, out);
            }
        }
    }
    walk(&book.items, Vec::new(), &mut out);
    out
}

// ---------- TOC ----------
pub fn toc_html(items: &[Item], hcfg: &HtmlCfg, for_iframe: bool) -> String {
    let mut out = String::from("<ol class=\"chapter\">");
    toc_items(items, hcfg, for_iframe, &mut out);
    out.push_str("</ol>");
    out
}

fn chapter_depth(ch: &Chapter) -> usize {
    ch.number.as_ref().map(|n| n.len().saturating_sub(1)).unwrap_or(0)
}

fn toc_items(items: &[Item], hcfg: &HtmlCfg, iframe: bool, out: &mut String) {
    for it in items {
        match it {
            Item::Separator => {
                out.push_str("<li class=\"chapter-item expanded affix \"><li class=\"spacer\"></li>");
            }
            Item::PartTitle(title) => {
                out.push_str(&format!("<li class=\"chapter-item expanded affix \"><li class=\"part-title\">{}</li>", markdown::escape_html(title)));
            }
            Item::Chapter(ch) => {
                let affix = ch.number.is_none();
                let expanded = if !hcfg.fold_enable { true } else { (chapter_depth(ch) as i64) < hcfg.fold_level };
                let mut class = String::from("chapter-item ");
                if expanded { class.push_str("expanded "); }
                if affix { class.push_str("affix "); }
                let label = if hcfg.no_section_label { String::new() } else if let Some(n) = &ch.number {
                    format!("<strong aria-hidden=\"true\">{}</strong> ", n.iter().map(|v| v.to_string()).collect::<Vec<_>>().join(".") + ".")
                } else { String::new() };
                out.push_str(&format!("<li class=\"{}\">", class));
                match output_html_path(ch) {
                    Some(p) => {
                        let target = if iframe { " target=\"_parent\"" } else { "" };
                        out.push_str(&format!("<a href=\"{}\"{}>{}{}</a>", slash(&p), target, label, markdown::escape_html(&ch.name)));
                    }
                    None => {
                        out.push_str(&format!("<div>{}{}</div>", label, markdown::escape_html(&ch.name)));
                    }
                }
                if hcfg.fold_enable && !ch.sub_items.is_empty() {
                    out.push_str("<a class=\"toggle\"><div>❱</div></a>");
                }
                out.push_str("</li>");
                if !ch.sub_items.is_empty() {
                    out.push_str("<li><ol class=\"section\">");
                    toc_items(&ch.sub_items, hcfg, iframe, out);
                    out.push_str("</ol></li>");
                }
            }
        }
    }
}

// ---------- search ----------
#[derive(Clone)]
struct Section {
    title: String,
    body: String,
    breadcrumbs: String,
    url: String,
}

fn search_enabled_for(ch: &Chapter, hcfg: &HtmlCfg) -> bool {
    if !hcfg.search_enable { return false; }
    if let Value::Object(map) = &hcfg.search_chapter {
        // Find the most specific key matching the chapter source path or a parent dir.
        let src = ch.source_path_display.replace('\\', "/");
        let mut best: Option<(usize, bool)> = None;
        for (key, val) in map {
            let enable = val.get("enable").and_then(|v| v.as_bool()).unwrap_or(true);
            let matches = src == *key || src.starts_with(&format!("{}/", key.trim_end_matches('/')));
            if matches {
                if best.map_or(true, |(len, _)| key.len() >= len) { best = Some((key.len(), enable)); }
            }
        }
        if let Some((_, e)) = best { return e; }
    }
    true
}

fn build_sections(book: &Book, hcfg: &HtmlCfg, md_ctx: &MdCtx) -> Vec<Section> {
    let flat = flatten_with_parents(book);
    let mut sections = Vec::new();
    for (ch, parents) in &flat {
        let html_path = match output_html_path(ch) { Some(p) => p, None => continue };
        if !search_enabled_for(ch, hcfg) { continue; }
        if ch.content.trim().is_empty() { continue; }
        let headings = markdown::extract_headings(&ch.content);
        // Build heading anchor ids with dedup, matching page rendering.
        let mut heading_state = markdown::HeadingState::new();
        let mut anchor_by_idx: Vec<String> = Vec::new();
        for (_, _, base) in &headings {
            anchor_by_idx.push(heading_state.unique_id(base));
        }
        // Split content into segments by lines, tracking headings.
        let mut cur_title: Option<String> = None;
        let mut cur_url: Option<String> = None;
        let mut cur_body: Vec<String> = Vec::new();
        let mut heading_idx = 0usize;
        let mut in_fence = false;
        let mut fence_ch = '`'; let mut fence_len = 0usize;
        for part in ch.content.split('\n') {
            let line = part;
            let t = line.trim_start();
            if let Some((c, n)) = markdown::fence_start(t) {
                if !in_fence { in_fence = true; fence_ch = c; fence_len = n; } else if c == fence_ch && n >= fence_len { in_fence = false; }
                cur_body.push(line.to_string());
                continue;
            }
            if !in_fence {
                if let Some(h) = headings.get(heading_idx) {
                    // Check whether this line is that heading.
                    let is_heading_line = {
                        let mut hl = None;
                        // replicate ATX check via extract: compare line parsing by re-scanning
                        let trimmed = line.trim_start();
                        if trimmed.starts_with('#') { hl = Some(()); }
                        hl.is_some()
                    };
                    if is_heading_line {
                        let (level, text, _) = h.clone();
                        heading_idx += 1;
                        if level <= hcfg.heading_split_level {
                            if cur_title.is_none() {
                                cur_title = Some(text.clone());
                                cur_url = Some(format!("{}#{}", slash(&html_path), anchor_by_idx[heading_idx - 1]));
                                continue;
                            } else {
                                // push current
                                let title = cur_title.take().unwrap();
                                let mut crumbs: Vec<String> = parents.clone();
                                crumbs.push(ch.name.clone());
                                crumbs.push(title.clone());
                                sections.push(Section { title: title.clone(), body: plain_join(&cur_body), breadcrumbs: crumbs.join(" » "), url: cur_url.take().unwrap() });
                                cur_body.clear();
                                cur_title = Some(text.clone());
                                cur_url = Some(format!("{}#{}", slash(&html_path), anchor_by_idx[heading_idx - 1]));
                                continue;
                            }
                        } else {
                            cur_body.push(text);
                            continue;
                        }
                    }
                }
            }
            cur_body.push(line.to_string());
        }
        // final section
        let body = plain_join(&cur_body);
        if let Some(title) = cur_title {
            let mut crumbs: Vec<String> = parents.clone();
            crumbs.push(ch.name.clone());
            crumbs.push(title.clone());
            sections.push(Section { title, body, breadcrumbs: crumbs.join(" » "), url: cur_url.unwrap_or_else(|| slash(&html_path)) });
        } else {
            let mut crumbs: Vec<String> = parents.clone();
            crumbs.push(ch.name.clone());
            sections.push(Section { title: ch.name.clone(), body, breadcrumbs: crumbs.join(" » "), url: slash(&html_path) });
        }
        let _ = md_ctx;
    }
    sections
}

fn plain_join(lines: &[String]) -> String {
    let text = lines.join("\n");
    let plain = markdown::md_to_plain(&text);
    plain.split_whitespace().collect::<Vec<_>>().join(" ")
}

// Elasticlunr-ish tokenisation.
fn tokenize(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    for raw in text.split(|c: char| c.is_whitespace() || c == '-' || c == '/') {
        let trimmed = raw.trim_matches(|c: char| !c.is_alphanumeric());
        if trimmed.is_empty() { continue; }
        let lower = trimmed.to_lowercase();
        if STOPWORDS.contains(&lower.as_str()) { continue; }
        out.push(stem(&lower));
    }
    out
}

const STOPWORDS: &[&str] = &["a","able","about","across","after","all","almost","also","am","among","an","and","any","are","as","at","be","because","been","but","by","can","cannot","could","dear","did","do","does","either","else","ever","every","for","from","get","got","has","have","he","her","hers","him","his","how","however","i","if","in","into","is","it","its","just","least","let","like","likely","may","me","might","most","must","my","neither","no","nor","not","of","off","often","on","only","or","other","our","own","rather","said","say","says","she","should","since","so","some","than","that","the","their","them","then","there","these","they","this","tis","to","too","twas","us","wants","was","we","were","what","when","where","which","while","who","whom","why","will","with","would","yet","you","your"];

fn stem(word: &str) -> String {
    let mut w = word.to_string();
    if w.len() > 4 && w.ends_with("ies") { w = format!("{}y", &w[..w.len()-3]); return w; }
    if w.len() > 5 && w.ends_with("ing") { w = w[..w.len()-3].to_string(); return dedup_end(w); }
    if w.len() > 4 && w.ends_with("ed") { w = w[..w.len()-2].to_string(); return dedup_end(w); }
    if w.len() > 3 && w.ends_with("es") && (w.ends_with("sses") || w.ends_with("ies") || w.ends_with("shes") || w.ends_with("ches") || w.ends_with("xes") || w.ends_with("zes")) { w = w[..w.len()-2].to_string(); return w; }
    if w.len() > 3 && w.ends_with('s') && !w.ends_with("ss") && !w.ends_with("us") { w.pop(); }
    w
}
fn dedup_end(mut w: String) -> String {
    let b: Vec<char> = w.chars().collect();
    if b.len() >= 2 && b[b.len()-1] == b[b.len()-2] && !"aeiou".contains(b[b.len()-1]) { w.pop(); }
    w
}

#[derive(Default)]
struct TrieNode {
    df: usize,
    docs: BTreeMap<String, f64>,
    children: BTreeMap<char, TrieNode>,
}

fn trie_insert(root: &mut TrieNode, token: &str, doc: &str, tf: f64) {
    let mut node = root;
    for ch in token.chars() {
        node = node.children.entry(ch).or_default();
    }
    node.df += 1;
    node.docs.insert(doc.to_string(), tf);
}

fn trie_to_json(node: &TrieNode) -> Value {
    let mut map = serde_json::Map::new();
    for (ch, child) in &node.children {
        map.insert(ch.to_string(), trie_to_json(child));
    }
    map.insert("df".to_string(), json!(node.df));
    let mut docs = serde_json::Map::new();
    for (k, v) in &node.docs { docs.insert(k.clone(), json!({"tf": v})); }
    map.insert("docs".to_string(), Value::Object(docs));
    Value::Object(map)
}

fn build_search_index(sections: &[Section], hcfg: &HtmlCfg) -> String {
    let mut doc_urls: Vec<String> = Vec::new();
    let mut docs = serde_json::Map::new();
    let mut doc_info = serde_json::Map::new();
    let mut tries: HashMap<&str, TrieNode> = HashMap::new();
    tries.insert("title", TrieNode::default());
    tries.insert("body", TrieNode::default());
    tries.insert("breadcrumbs", TrieNode::default());
    for (idx, sec) in sections.iter().enumerate() {
        let id = idx.to_string();
        doc_urls.push(sec.url.clone());
        docs.insert(id.clone(), json!({"body": sec.body, "breadcrumbs": sec.breadcrumbs, "id": id, "title": sec.title}));
        let mut info = serde_json::Map::new();
        for (field, text) in [("title", &sec.title), ("body", &sec.body), ("breadcrumbs", &sec.breadcrumbs)] {
            let tokens = tokenize(text);
            info.insert(field.to_string(), json!(tokens.len()));
            let mut counts: HashMap<String, usize> = HashMap::new();
            for t in &tokens { *counts.entry(t.clone()).or_insert(0) += 1; }
            let trie = tries.get_mut(field).unwrap();
            for (tok, count) in counts {
                trie_insert(trie, &tok, &id, (count as f64).sqrt());
            }
        }
        doc_info.insert(id.clone(), Value::Object(info));
    }
    let mut index_fields = serde_json::Map::new();
    for field in ["body", "breadcrumbs", "title"] {
        index_fields.insert(field.to_string(), json!({"root": trie_to_json(tries.get(field).unwrap())}));
    }
    let data = json!({
        "doc_urls": doc_urls,
        "index": {
            "documentStore": {
                "docInfo": Value::Object(doc_info),
                "docs": Value::Object(docs),
                "length": sections.len(),
                "save": true
            },
            "fields": ["title", "body", "breadcrumbs"],
            "index": Value::Object(index_fields),
            "lang": "English",
            "pipeline": ["trimmer", "stopWordFilter", "stemmer"],
            "ref": "id",
            "version": "0.9.5"
        },
        "results_options": {"limit_results": hcfg.search_limit, "teaser_word_count": hcfg.search_teaser},
        "search_options": {
            "bool": if hcfg.search_bool_and { "AND" } else { "OR" },
            "expand": hcfg.search_expand,
            "fields": {"body": {"boost": hcfg.search_boost_paragraph}, "breadcrumbs": {"boost": hcfg.search_boost_hierarchy}, "title": {"boost": hcfg.search_boost_title}}
        }
    });
    let json_str = serde_json::to_string(&data).unwrap_or_default();
    let escaped = json_str.replace('\\', "\\\\").replace('\'', "\\'");
    format!("window.search = Object.assign(window.search, JSON.parse('{}'));", escaped)
}

// ---------- helpers ----------
fn write_file(dest: &Path, rel: &str, contents: &[u8]) -> Result<(), Vec<String>> {
    let path = dest.join(rel);
    if let Some(parent) = path.parent() { std::fs::create_dir_all(parent).map_err(|e| vec!["Rendering failed".into(), format!("{}", e)])?; }
    std::fs::write(&path, contents).map_err(|e| vec!["Rendering failed".into(), format!("{}", e)])
}

fn collect_files(dir: &Path, base: &Path, out: &mut Vec<PathBuf>) {
    if let Ok(rd) = std::fs::read_dir(dir) {
        let mut entries: Vec<PathBuf> = rd.filter_map(|e| e.ok().map(|e| e.path())).collect();
        entries.sort();
        for e in entries {
            if e.is_dir() { collect_files(&e, base, out); }
            else if e.is_file() { out.push(e); }
            let _ = base;
        }
    }
}

// ---------- HTML renderer ----------
pub fn render_html(book: &Book, cfg: &Value, root: &Path, dest: &Path, live_reload: bool) -> Result<(), Vec<String>> {
    let hcfg = html_cfg(cfg);
    // theme resolution
    let theme_dir: Option<PathBuf> = match &hcfg.theme {
        Some(t) => {
            let p = root.join(t);
            if !p.exists() {
                return Err(vec!["Rendering failed".into(), format!("theme dir {} does not exist", p.display())]);
            }
            Some(p)
        }
        None => {
            let p = root.join("theme");
            if p.is_dir() { Some(p) } else { None }
        }
    };
    let mut theme_files: BTreeMap<String, Vec<u8>> = BTreeMap::new();
    if let Some(td) = &theme_dir {
        let mut files = Vec::new();
        collect_files(td, td, &mut files);
        for f in files {
            let rel = f.strip_prefix(td).unwrap().to_string_lossy().replace('\\', "/");
            if let Ok(content) = std::fs::read(&f) { theme_files.insert(rel, content); }
        }
    }

    // Clean destination
    if dest.is_dir() {
        let _ = std::fs::remove_dir_all(dest);
    } else if dest.exists() {
        let _ = std::fs::remove_file(dest);
    }
    std::fs::create_dir_all(dest).map_err(|e| vec!["Rendering failed".to_string(), format!("{}", e)])?;

    let md_ctx = MdCtx { smart_punctuation: hcfg.smart_punctuation, hidelines: hcfg.hidelines.clone() };
    // set code renderer options via thread-local-ish: markdown rendering uses cfg each call below

    // Additional css/js (must exist relative to root)
    let mut additional_contents: BTreeMap<String, Vec<u8>> = BTreeMap::new();
    for rel in hcfg.additional_css.iter().chain(hcfg.additional_js.iter()) {
        let p = root.join(rel);
        match std::fs::read(&p) {
            Ok(c) => { additional_contents.insert(rel.clone(), c); }
            Err(e) => {
                return Err(vec!["Rendering failed".into(), "Unable to copy across static files".into(), format!("{}", e)]);
            }
        }
    }

    // Base assets
    let mut assets: BTreeMap<String, Vec<u8>> = BTreeMap::new();
    assets.insert(".nojekyll".into(), crate::theme::NOJEKYLL.as_bytes().to_vec());
    assets.insert("css/variables.css".into(), crate::theme::VARIABLES_CSS.as_bytes().to_vec());
    assets.insert("css/general.css".into(), crate::theme::GENERAL_CSS.as_bytes().to_vec());
    assets.insert("css/chrome.css".into(), crate::theme::CHROME_CSS.as_bytes().to_vec());
    assets.insert("css/print.css".into(), crate::theme::PRINT_CSS.as_bytes().to_vec());
    assets.insert("FontAwesome/css/font-awesome.css".into(), crate::theme::FONT_AWESOME_CSS.as_bytes().to_vec());
    for f in crate::theme::fontawesome_files() {
        assets.insert(format!("FontAwesome/fonts/{}", f), crate::theme::dummy_font(&f));
    }
    if hcfg.copy_fonts {
        assets.insert("fonts/fonts.css".into(), crate::theme::FONTS_CSS.as_bytes().to_vec());
        assets.insert("fonts/OPEN-SANS-LICENSE.txt".into(), crate::theme::OPEN_SANS_LICENSE.as_bytes().to_vec());
        assets.insert("fonts/SOURCE-CODE-PRO-LICENSE.txt".into(), crate::theme::SOURCE_CODE_PRO_LICENSE.as_bytes().to_vec());
        for f in crate::theme::font_files() {
            assets.insert(format!("fonts/{}", f), crate::theme::dummy_font(&f));
        }
    }
    assets.insert("favicon.svg".into(), crate::theme::FAVICON_SVG.as_bytes().to_vec());
    assets.insert("favicon.png".into(), crate::theme::favicon_png());
    assets.insert("highlight.css".into(), crate::theme::HIGHLIGHT_CSS.as_bytes().to_vec());
    assets.insert("tomorrow-night.css".into(), crate::theme::TOMORROW_NIGHT_CSS.as_bytes().to_vec());
    assets.insert("ayu-highlight.css".into(), crate::theme::AYU_HIGHLIGHT_CSS.as_bytes().to_vec());
    assets.insert("book.js".into(), crate::theme::BOOK_JS.as_bytes().to_vec());
    assets.insert("clipboard.min.js".into(), crate::theme::CLIPBOARD_JS.as_bytes().to_vec());
    assets.insert("highlight.js".into(), crate::theme::HIGHLIGHT_JS.as_bytes().to_vec());
    let search_js_enabled = hcfg.search_enable && hcfg.search_copy_js;
    if search_js_enabled {
        assets.insert("elasticlunr.min.js".into(), crate::theme::ELASTICLUNR_JS.as_bytes().to_vec());
        assets.insert("mark.min.js".into(), crate::theme::MARK_JS.as_bytes().to_vec());
        assets.insert("searcher.js".into(), crate::theme::SEARCHER_JS.as_bytes().to_vec());
    }
    if hcfg.playground_editable {
        assets.insert("ace.js".into(), crate::theme::ACE_JS.as_bytes().to_vec());
        assets.insert("editor.js".into(), crate::theme::EDITOR_JS.as_bytes().to_vec());
        assets.insert("mode-rust.js".into(), crate::theme::MODE_RUST_JS.as_bytes().to_vec());
        assets.insert("theme-dawn.js".into(), crate::theme::THEME_DAWN_JS.as_bytes().to_vec());
        assets.insert("theme-tomorrow_night.js".into(), crate::theme::THEME_TOMORROW_JS.as_bytes().to_vec());
    }
    // Theme overrides (except .hbs templates)
    for (rel, content) in &theme_files {
        if rel.ends_with(".hbs") { continue; }
        assets.insert(rel.clone(), content.clone());
    }
    // Additional files
    for (rel, content) in &additional_contents {
        assets.insert(rel.clone(), content.clone());
    }

    // Generated toc.js and searchindex.js
    let toc = toc_html(&book.items, &hcfg, false);
    let toc_js = build_toc_js(&toc);
    assets.insert("toc.js".into(), toc_js.into_bytes());

    let sections = if hcfg.search_enable { build_sections(book, &hcfg, &md_ctx) } else { Vec::new() };
    let searchindex = build_search_index(&sections, &hcfg);
    if search_js_enabled {
        assets.insert("searchindex.js".into(), searchindex.clone().into_bytes());
    }

    // Hashing
    let mut resource_map: HashMap<String, String> = HashMap::new();
    if hcfg.hash_files {
        for (rel, content) in &assets {
            if is_hashable(rel) {
                let hash = &crate::sha256::sha256_hex(content)[..8];
                resource_map.insert(rel.clone(), hashed_name(rel, hash));
            }
        }
        // Rewrite urls inside css/js assets to hashed names.
        // Build basename replacements.
        let mut replacements: Vec<(String, String)> = Vec::new();
        for (orig, hashed) in &resource_map {
            let ob = orig.rsplit('/').next().unwrap_or(orig).to_string();
            let hb = hashed.rsplit('/').next().unwrap_or(hashed).to_string();
            if ob != hb { replacements.push((ob, hb)); }
        }
        replacements.sort_by(|a, b| b.0.len().cmp(&a.0.len()));
        for (rel, content) in assets.iter_mut() {
            if rel.ends_with(".css") || rel.ends_with(".js") {
                if let Ok(text) = String::from_utf8(content.clone()) {
                    let mut new_text = text.clone();
                    for (ob, hb) in &replacements {
                        new_text = new_text.replace(ob.as_str(), hb.as_str());
                    }
                    // don't let a file rewrite its own name references incorrectly for toc/search (they contain their toc html not names)
                    if new_text != text { *content = new_text.into_bytes(); }
                }
            }
        }
    }
    let resource_name = |rel: &str| resource_map.get(rel).cloned().unwrap_or_else(|| rel.to_string());

    // Write assets
    for (rel, content) in &assets {
        write_file(dest, &resource_name(rel), content)?;
    }

    // Copy static files from the source directory (non-markdown)
    let src_dir = crate::config::src_dir(root, cfg);
    copy_static_files(&src_dir, dest)?;

    // Redirect grouping (compute before pages so fragment maps known)
    let (redirect_files, fragment_maps, redirect_err) = process_redirects(&hcfg, book);
    if let Some(err) = redirect_err { return Err(err); }

    // Templates
    let index_tpl = theme_files.get("index.hbs").and_then(|b| String::from_utf8(b.clone()).ok()).unwrap_or_else(|| crate::theme::INDEX_HBS.to_string());
    let toc_tpl = theme_files.get("toc.hbs").and_then(|b| String::from_utf8(b.clone()).ok()).unwrap_or_else(|| crate::theme::TOC_HBS.to_string());
    let mut partials: HashMap<String, String> = HashMap::new();
    if let Some(h) = theme_files.get("head.hbs") { partials.insert("head".into(), String::from_utf8_lossy(h).to_string()); }
    if let Some(h) = theme_files.get("header.hbs") { partials.insert("header".into(), String::from_utf8_lossy(h).to_string()); }

    let book_title_raw = crate::config::get_str(cfg, &["book", "title"]);
    let book_title = book_title_raw.clone().unwrap_or_default();
    let language = crate::config::get_str(cfg, &["book", "language"]).unwrap_or_else(|| "en".to_string());
    let description = crate::config::get_str(cfg, &["book", "description"]).unwrap_or_default();
    let flat = flatten_with_parents(book);
    let page_paths: Vec<(Chapter, Vec<String>, PathBuf)> = flat.iter().filter_map(|(ch, parents)| output_html_path(ch).map(|p| (ch.clone(), parents.clone(), p))).collect();

    // Precompute chapters context
    let chapters_ctx: Vec<Value> = {
        let mut arr = Vec::new();
        fn walk_ctx(items: &[Item], arr: &mut Vec<Value>) {
            for it in items {
                match it {
                    Item::Chapter(ch) => {
                        let mut obj = serde_json::Map::new();
                        obj.insert("name".into(), json!(ch.name));
                        if let Some(loc) = &ch.location { obj.insert("path".into(), json!(slash(loc))); }
                        if let Some(n) = &ch.number { obj.insert("section".into(), json!(n.iter().map(|v| v.to_string()).collect::<Vec<_>>().join(".") + ".")); }
                        arr.push(Value::Object(obj));
                        walk_ctx(&ch.sub_items, arr);
                    }
                    Item::Separator => arr.push(json!({})),
                    Item::PartTitle(_) => arr.push(json!({})),
                }
            }
        }
        walk_ctx(&book.items, &mut arr);
        arr
    };

    let render_page = |title: String, chapter_title: &str, content: String, path_to_root_s: String, rel_path: &str, section: Option<&Vec<u32>>, previous: Option<Value>, next: Option<Value>, is_print: bool, base_url: Option<String>, fragment_map: Option<String>| -> String {
        let mut ctx = serde_json::Map::new();
        ctx.insert("language".into(), json!(language));
        ctx.insert("text_direction".into(), json!(text_direction(cfg)));
        ctx.insert("title".into(), json!(title));
        ctx.insert("book_title".into(), json!(book_title));
        ctx.insert("chapter_title".into(), json!(chapter_title));
        ctx.insert("description".into(), json!(description));
        ctx.insert("path".into(), json!(rel_path));
        ctx.insert("content".into(), json!(content));
        ctx.insert("path_to_root".into(), json!(path_to_root_s));
        ctx.insert("chapters".into(), Value::Array(chapters_ctx.clone()));
        ctx.insert("is_print".into(), json!(is_print));
        if let Some(b) = base_url { ctx.insert("base_url".into(), json!(b)); }
        ctx.insert("favicon_svg".into(), json!(assets.contains_key("favicon.svg")));
        ctx.insert("favicon_png".into(), json!(assets.contains_key("favicon.png")));
        ctx.insert("print_enable".into(), json!(hcfg.print_enable));
        ctx.insert("copy_fonts".into(), json!(hcfg.copy_fonts));
        ctx.insert("additional_css".into(), json!(hcfg.additional_css));
        ctx.insert("additional_js".into(), json!(hcfg.additional_js));
        ctx.insert("mathjax_support".into(), json!(hcfg.mathjax_support));
        ctx.insert("default_theme".into(), json!(hcfg.default_theme));
        ctx.insert("preferred_dark_theme".into(), json!(hcfg.preferred_dark_theme));
        ctx.insert("search_js".into(), json!(search_js_enabled));
        ctx.insert("search_enabled".into(), json!(hcfg.search_enable));
        if let Some(u) = &hcfg.git_repository_url { ctx.insert("git_repository_url".into(), json!(u)); }
        ctx.insert("git_repository_icon".into(), json!(hcfg.git_repository_icon));
        // edit url filled by callers through `section` hack not used; handled via thread value below
        ctx.insert("section".into(), match section { Some(n) => json!(n.iter().map(|v| v.to_string()).collect::<Vec<_>>().join(".") + "."), None => json!("") });
        ctx.insert("playground_line_numbers".into(), json!(hcfg.playground_line_numbers));
        ctx.insert("playground_copyable".into(), json!(hcfg.playground_copyable));
        ctx.insert("playground_js".into(), json!(hcfg.playground_editable));
        if live_reload { ctx.insert("live_reload_endpoint".into(), json!("__livereload")); }
        if let Some(p) = previous { ctx.insert("previous".into(), p); }
        if let Some(n) = next { ctx.insert("next".into(), n); }
        if let Some(fm) = fragment_map { ctx.insert("fragment_map".into(), json!(fm)); }
        let ctx_val = Value::Object(ctx);
        let resource_fn = |rel: &str, c: &Value| -> String {
            let ptr = crate::hbs::lookup(c, "path_to_root");
            let ptr_s = if let Value::String(s) = ptr { s } else { String::new() };
            format!("{}{}", ptr_s, resource_map.get(rel).cloned().unwrap_or_else(|| rel.to_string()))
        };
        let renderer = crate::hbs::Renderer { partials: &partials, resource_fn: &resource_fn, toc_html: toc.clone() };
        renderer.render(&index_tpl, &ctx_val)
    };

    // chapter pages
    let mut written_pages: HashSet<String> = HashSet::new();
    for (idx, (ch, _parents, html_path)) in page_paths.iter().enumerate() {
        let content_html = render_chapter_content(&ch.content, &md_ctx, &hcfg);
        let title = page_title_for(ch, &book_title_raw);
        let prev = if idx == 0 { None } else { let (pch, _, ppath) = &page_paths[idx-1]; Some(json!({"link": slash(ppath), "title": pch.name})) };
        let next = if idx + 1 >= page_paths.len() { None } else { let (nch, _, npath) = &page_paths[idx+1]; Some(json!({"link": slash(npath), "title": nch.name})) };
        let frag = fragment_maps.get(&slash(html_path)).cloned();
        let mut page = {
            // need edit url: inject after render by direct context build is inside closure;
            // simpler: build locally via render_page plus post handling for edit url not possible.
            // We handle git_repository_edit_url by encoding it into title-independent pass:
            // call render_page then, if edit template exists, the template's {{git_repository_edit_url}} resolves empty;
            // so instead handle it in context through a global we set below.
            render_page(title, &ch.name, content_html, path_to_root(html_path), &ch.location.as_ref().map(|p| slash(p)).unwrap_or_default(), ch.number.as_ref(), prev, next, false, None, frag)
        };
        // If edit-url-template configured, the rendered page will lack the edit link
        // because context didn't include it. Re-render with it included:
        if let Some(tpl) = &hcfg.edit_url_template {
            let src_rel = {
                let src_dir_path = crate::config::src_dir(root, cfg);
                let rel_src = src_dir_path.strip_prefix(root).map(|p| slash(p)).unwrap_or_else(|_| "".to_string());
                let source = if ch.source_path_display.is_empty() { ch.location.as_ref().map(|p| slash(p)).unwrap_or_default() } else { ch.source_path_display.clone() };
                if rel_src.is_empty() { source } else { format!("{}/{}", rel_src.trim_end_matches('/'), source) }
            };
            let edit_url = tpl.replace("{path}", &src_rel);
            page = render_page_with_edit(&index_tpl, &partials, &mut page_context_extra(), edit_url);
            let _ = page;
            // The above approach is confusing; instead do a full re-render below:
            page = render_one_page(&index_tpl, &partials, cfg, &hcfg, &language, &book_title, &description, &chapters_ctx, &toc, &resource_map, RenderOne {
                title: page_title_for(ch, &book_title_raw),
                chapter_title: ch.name.clone(),
                content: render_chapter_content(&ch.content, &md_ctx, &hcfg),
                path_to_root: path_to_root(html_path),
                rel_path: ch.location.as_ref().map(|p| slash(p)).unwrap_or_default(),
                section: ch.number.clone(),
                previous: if idx == 0 { None } else { let (pch, _, ppath) = &page_paths[idx-1]; Some(json!({"link": slash(ppath), "title": pch.name})) },
                next: if idx + 1 >= page_paths.len() { None } else { let (nch, _, npath) = &page_paths[idx+1]; Some(json!({"link": slash(npath), "title": nch.name})) },
                is_print: false,
                base_url: None,
                fragment_map: fragment_maps.get(&slash(html_path)).cloned(),
                edit_url: Some(edit_url),
                live_reload,
                search_js_enabled,
                assets_has_favicon_svg: assets.contains_key("favicon.svg"),
                assets_has_favicon_png: assets.contains_key("favicon.png"),
            });
        }
        write_file(dest, &slash(html_path), page.as_bytes())?;
        written_pages.insert(slash(html_path));
    }

    // index alias: first page rendered with path_to_root ""
    if let Some((ch, _p, html_path)) = page_paths.first() {
        if slash(html_path) != "index.html" {
            let title = page_title_for(ch, &book_title_raw);
            let next = if page_paths.len() > 1 { let (nch, _, npath) = &page_paths[1]; Some(json!({"link": slash(npath), "title": nch.name})) } else { None };
            let content_html = render_chapter_content(&ch.content, &md_ctx, &hcfg);
            let edit_url = hcfg.edit_url_template.as_ref().map(|tpl| {
                let src_dir_path = crate::config::src_dir(root, cfg);
                let rel_src = src_dir_path.strip_prefix(root).map(|p| slash(p)).unwrap_or_default();
                let source = if ch.source_path_display.is_empty() { ch.location.as_ref().map(|p| slash(p)).unwrap_or_default() } else { ch.source_path_display.clone() };
                tpl.replace("{path}", &if rel_src.is_empty() { source } else { format!("{}/{}", rel_src, source) })
            });
            let page = render_one_page(&index_tpl, &partials, cfg, &hcfg, &language, &book_title, &description, &chapters_ctx, &toc, &resource_map, RenderOne {
                title, chapter_title: ch.name.clone(), content: content_html, path_to_root: String::new(),
                rel_path: ch.location.as_ref().map(|p| slash(p)).unwrap_or_default(), section: ch.number.clone(),
                previous: None, next, is_print: false, base_url: None,
                fragment_map: fragment_maps.get("index.html").cloned(), edit_url, live_reload, search_js_enabled,
                assets_has_favicon_svg: assets.contains_key("favicon.svg"), assets_has_favicon_png: assets.contains_key("favicon.png"),
            });
            write_file(dest, "index.html", page.as_bytes())?;
            written_pages.insert("index.html".to_string());
        } else {
            written_pages.insert("index.html".to_string());
        }
    }

    // print page
    if hcfg.print_enable {
        let mut content = String::new();
        for (i, (ch, _, _)) in page_paths.iter().enumerate() {
            if i > 0 && hcfg.print_page_break {
                content.push_str("<div style=\"break-before: page; page-break-before: always;\"></div>");
            }
            content.push_str(&render_chapter_content(&ch.content, &md_ctx, &hcfg));
        }
        let page = render_one_page(&index_tpl, &partials, cfg, &hcfg, &language, &book_title, &description, &chapters_ctx, &toc, &resource_map, RenderOne {
            title: book_title.clone(), chapter_title: String::new(), content, path_to_root: String::new(),
            rel_path: "print.md".into(), section: None, previous: None, next: None, is_print: true, base_url: None,
            fragment_map: None, edit_url: None, live_reload, search_js_enabled,
            assets_has_favicon_svg: assets.contains_key("favicon.svg"), assets_has_favicon_png: assets.contains_key("favicon.png"),
        });
        write_file(dest, "print.html", page.as_bytes())?;
    }

    // 404 page
    {
        let content_md = {
            let p = src_dir.join(&hcfg.input_404);
            if p.is_file() {
                std::fs::read_to_string(&p).unwrap_or_else(|_| default_404_md())
            } else { default_404_md() }
        };
        let content_html = render_chapter_content(&content_md, &md_ctx, &hcfg);
        let title = match &book_title_raw { Some(t) => format!("Page not found - {}", t), None => "Page not found".into() };
        let base = hcfg.site_url.clone().unwrap_or_else(|| "/".to_string());
        let page = render_one_page(&index_tpl, &partials, cfg, &hcfg, &language, &book_title, &description, &chapters_ctx, &toc, &resource_map, RenderOne {
            title, chapter_title: "Page not found".into(), content: content_html, path_to_root: String::new(),
            rel_path: hcfg.input_404.clone(), section: None, previous: None, next: None, is_print: false, base_url: Some(base),
            fragment_map: fragment_maps.get("404.html").cloned(), edit_url: None, live_reload, search_js_enabled,
            assets_has_favicon_svg: assets.contains_key("favicon.svg"), assets_has_favicon_png: assets.contains_key("favicon.png"),
        });
        write_file(dest, "404.html", page.as_bytes())?;
    }

    // toc.html
    {
        let toc_iframe = toc_html(&book.items, &hcfg, true);
        let mut ctx = serde_json::Map::new();
        ctx.insert("language".into(), json!(language));
        ctx.insert("text_direction".into(), json!(text_direction(cfg)));
        ctx.insert("default_theme".into(), json!(hcfg.default_theme));
        ctx.insert("path_to_root".into(), json!(""));
        let ctx_val = Value::Object(ctx);
        let resource_fn = |rel: &str, _c: &Value| -> String { resource_map.get(rel).cloned().unwrap_or_else(|| rel.to_string()) };
        let renderer = crate::hbs::Renderer { partials: &partials, resource_fn: &resource_fn, toc_html: toc_iframe };
        let page = renderer.render(&toc_tpl, &ctx_val);
        write_file(dest, "toc.html", page.as_bytes())?;
    }

    // CNAME
    if let Some(cname) = &hcfg.cname {
        write_file(dest, "CNAME", format!("{}\n", cname).as_bytes())?;
    }

    // Redirect files
    for (path, content) in &redirect_files {
        write_file(dest, path, content.as_bytes())?;
    }

    crate::log_info!("mdbook_html::html_handlebars::hbs_renderer", "HTML book written to `{}`", dest.display());
    Ok(())
}

fn page_context_extra() -> Value { json!({}) }
fn render_page_with_edit(_tpl: &str, _partials: &HashMap<String, String>, _ctx: &mut Value, _edit: String) -> String { String::new() }

pub struct RenderOne {
    pub title: String,
    pub chapter_title: String,
    pub content: String,
    pub path_to_root: String,
    pub rel_path: String,
    pub section: Option<Vec<u32>>,
    pub previous: Option<Value>,
    pub next: Option<Value>,
    pub is_print: bool,
    pub base_url: Option<String>,
    pub fragment_map: Option<String>,
    pub edit_url: Option<String>,
    pub live_reload: bool,
    pub search_js_enabled: bool,
    pub assets_has_favicon_svg: bool,
    pub assets_has_favicon_png: bool,
}

pub fn render_one_page(tpl: &str, partials: &HashMap<String, String>, cfg: &Value, hcfg: &HtmlCfg, language: &str, book_title: &str, description: &str, chapters_ctx: &[Value], toc: &str, resource_map: &HashMap<String, String>, r: RenderOne) -> String {
    let mut ctx = serde_json::Map::new();
    ctx.insert("language".into(), json!(language));
    ctx.insert("text_direction".into(), json!(text_direction(cfg)));
    ctx.insert("title".into(), json!(r.title));
    ctx.insert("book_title".into(), json!(book_title));
    ctx.insert("chapter_title".into(), json!(r.chapter_title));
    ctx.insert("description".into(), json!(description));
    ctx.insert("path".into(), json!(r.rel_path));
    ctx.insert("content".into(), json!(r.content));
    ctx.insert("path_to_root".into(), json!(r.path_to_root));
    ctx.insert("chapters".into(), Value::Array(chapters_ctx.to_vec()));
    ctx.insert("is_print".into(), json!(r.is_print));
    if let Some(b) = r.base_url { ctx.insert("base_url".into(), json!(b)); }
    ctx.insert("favicon_svg".into(), json!(r.assets_has_favicon_svg));
    ctx.insert("favicon_png".into(), json!(r.assets_has_favicon_png));
    ctx.insert("print_enable".into(), json!(hcfg.print_enable));
    ctx.insert("copy_fonts".into(), json!(hcfg.copy_fonts));
    ctx.insert("additional_css".into(), json!(hcfg.additional_css));
    ctx.insert("additional_js".into(), json!(hcfg.additional_js));
    ctx.insert("mathjax_support".into(), json!(hcfg.mathjax_support));
    ctx.insert("default_theme".into(), json!(hcfg.default_theme));
    ctx.insert("preferred_dark_theme".into(), json!(hcfg.preferred_dark_theme));
    ctx.insert("search_js".into(), json!(r.search_js_enabled));
    ctx.insert("search_enabled".into(), json!(hcfg.search_enable));
    if let Some(u) = &hcfg.git_repository_url { ctx.insert("git_repository_url".into(), json!(u)); }
    ctx.insert("git_repository_icon".into(), json!(hcfg.git_repository_icon));
    if let Some(e) = r.edit_url { ctx.insert("git_repository_edit_url".into(), json!(e)); }
    ctx.insert("section".into(), match &r.section { Some(n) => json!(n.iter().map(|v| v.to_string()).collect::<Vec<_>>().join(".") + "."), None => json!("") });
    ctx.insert("playground_line_numbers".into(), json!(hcfg.playground_line_numbers));
    ctx.insert("playground_copyable".into(), json!(hcfg.playground_copyable));
    ctx.insert("playground_js".into(), json!(hcfg.playground_editable));
    if r.live_reload { ctx.insert("live_reload_endpoint".into(), json!("__livereload")); }
    if let Some(p) = r.previous { ctx.insert("previous".into(), p); }
    if let Some(n) = r.next { ctx.insert("next".into(), n); }
    if let Some(fm) = r.fragment_map { ctx.insert("fragment_map".into(), json!(fm)); }
    let ctx_val = Value::Object(ctx);
    let resource_fn = |rel: &str, c: &Value| -> String {
        let ptr = crate::hbs::lookup(c, "path_to_root");
        let ptr_s = if let Value::String(s) = ptr { s } else { String::new() };
        format!("{}{}", ptr_s, resource_map.get(rel).cloned().unwrap_or_else(|| rel.to_string()))
    };
    let renderer = crate::hbs::Renderer { partials, resource_fn: &resource_fn, toc_html: toc.to_string() };
    renderer.render(tpl, &ctx_val)
}

fn page_title_for(ch: &Chapter, book_title: &Option<String>) -> String {
    if let Some(t) = &ch.page_title { return t.clone(); }
    match book_title {
        Some(bt) if !bt.is_empty() => format!("{} - {}", ch.name, bt),
        _ => ch.name.clone(),
    }
}

fn default_404_md() -> String {
    "# Document not found (404)\n\nThis URL is invalid, sorry. Please use the navigation bar or search to continue.\n".to_string()
}

pub fn render_chapter_content(md: &str, md_ctx: &MdCtx, hcfg: &HtmlCfg) -> String {
    // Need code-block options (playground runnable) applied; MdCtx carries hidelines,
    // and crate::markdown uses crate::codeblock with runnable default true.
    // We adjust by pre-processing through markdown rendering which uses codeblock defaults.
    let _ = hcfg;
    // The playground_runnable flag is applied by temporarily handling in codeblock via a global.
    crate::codeblock::set_playground_runnable(hcfg.playground_runnable);
    let out = markdown::render_markdown(md, md_ctx);
    crate::codeblock::set_playground_runnable(true);
    out
}

fn build_toc_js(toc: &str) -> String {
    let escaped = toc.replace('\\', "\\\\").replace('\'', "\\'");
    format!(r##"// Populate the sidebar
//
// This is a script, and not included directly in the page, to control the total size of the book.
// The TOC contains an entry for each page, so if each page includes a copy of the TOC,
// the total size of the page becomes O(n**2).
class MDBookSidebarScrollbox extends HTMLElement {{
    constructor() {{
        super();
    }}
    connectedCallback() {{
        this.innerHTML = '{}';
        // Set the current, active page, and reveal it if it's hidden
        let current_page = document.location.href.toString().split("#")[0].split("?")[0];
        if (current_page.endsWith("/")) {{
            current_page += "index.html";
        }}
        var links = Array.prototype.slice.call(this.querySelectorAll("a"));
        var l = links.length;
        for (var i = 0; i < l; ++i) {{
            var link = links[i];
            var href = link.getAttribute("href");
            if (href && !href.startsWith("#") && !/^(?:[a-z+]+:)?\/\//.test(href)) {{
                link.href = path_to_root + href;
            }}
            // The "index" page is supposed to alias the first chapter in the book.
            if (link.href === current_page || (i === 0 && path_to_root === "" && current_page.endsWith("/index.html"))) {{
                link.classList.add("active");
                var parent = link.parentElement;
                if (parent && parent.classList.contains("chapter-item")) {{
                    parent.classList.add("expanded");
                }}
                while (parent) {{
                    if (parent.tagName === "LI" && parent.previousElementSibling) {{
                        if (parent.previousElementSibling.classList.contains("chapter-item")) {{
                            parent.previousElementSibling.classList.add("expanded");
                        }}
                    }}
                    parent = parent.parentElement;
                }}
            }}
        }}
        // Track and set sidebar scroll position
        this.addEventListener('click', function(e) {{
            if (e.target.tagName === 'A') {{
                sessionStorage.setItem('sidebar-scroll', this.scrollTop);
            }}
        }}, {{ passive: true }});
        var sidebarScrollTop = sessionStorage.getItem('sidebar-scroll');
        sessionStorage.removeItem('sidebar-scroll');
        if (sidebarScrollTop) {{
            // preserve sidebar scroll position when navigating via links within sidebar
            this.scrollTop = sidebarScrollTop;
        }} else {{
            // scroll sidebar to current active section when navigating via "next/previous chapter" buttons
            var activeSection = document.querySelector('#sidebar .active');
            if (activeSection) {{
                activeSection.scrollIntoView({{ block: 'center' }});
            }}
        }}
        // Toggle buttons
        var sidebarAnchorToggles = document.querySelectorAll('#sidebar a.toggle');
        function toggleSection(ev) {{
            ev.currentTarget.parentElement.classList.toggle('expanded');
        }}
        Array.from(sidebarAnchorToggles).forEach(function (el) {{
            el.addEventListener('click', toggleSection);
        }});
    }}
}}
window.customElements.define("mdbook-sidebar-scrollbox", MDBookSidebarScrollbox);
"##, escaped)
}

fn is_hashable(rel: &str) -> bool {
    let lower = rel.to_ascii_lowercase();
    [".css", ".js", ".png", ".svg", ".woff", ".woff2", ".jpg", ".jpeg", ".gif", ".webp", ".ico"].iter().any(|e| lower.ends_with(e))
}

fn hashed_name(rel: &str, hash: &str) -> String {
    // Insert -hash before the first dot of the file name.
    let (dir, name) = match rel.rfind('/') { Some(i) => (&rel[..i+1], &rel[i+1..]), None => ("", rel) };
    match name.find('.') {
        Some(dot) => format!("{}-{}", &format!("{}{}", dir, &name[..dot]), hash) + &name[dot..],
        None => format!("{}{}-{}", dir, name, hash),
    }
}

fn copy_static_files(src_dir: &Path, dest: &Path) -> Result<(), Vec<String>> {
    let mut files = Vec::new();
    collect_files(src_dir, src_dir, &mut files);
    for f in files {
        let rel = f.strip_prefix(src_dir).unwrap().to_path_buf();
        let ext_is_md = rel.extension().and_then(|e| e.to_str()).map(|e| e.eq_ignore_ascii_case("md")).unwrap_or(false);
        if ext_is_md { continue; }
        let out = dest.join(&rel);
        if let Some(parent) = out.parent() { std::fs::create_dir_all(parent).map_err(|e| vec!["Rendering failed".into(), format!("{}", e)])?; }
        std::fs::copy(&f, &out).map_err(|e| vec!["Rendering failed".into(), format!("{}", e)])?;
    }
    Ok(())
}

fn process_redirects(hcfg: &HtmlCfg, book: &Book) -> (Vec<(String, String)>, HashMap<String, String>, Option<Vec<String>>) {
    // Determine existing chapter pages for fragment injection.
    let mut existing: HashSet<String> = HashSet::new();
    for (ch, _) in flatten_with_parents(book) {
        if let Some(p) = output_html_path(&ch) { existing.insert(slash(&p)); }
    }
    existing.insert("index.html".to_string());
    if hcfg.print_enable { existing.insert("print.html".to_string()); }
    existing.insert("404.html".to_string());

    // Group by source path (without fragment)
    let mut groups: BTreeMap<String, BTreeMap<Option<String>, String>> = BTreeMap::new();
    for (src, dst) in &hcfg.redirect {
        let (path, frag) = match src.split_once('#') { Some((p, f)) => (p.to_string(), Some(format!("#{}", f))), None => (src.clone(), None) };
        let clean = path.trim_start_matches('/').to_string();
        groups.entry(clean).or_default().insert(frag, dst.clone());
    }
    let mut files: Vec<(String, String)> = Vec::new();
    let mut fragment_maps: HashMap<String, String> = HashMap::new();
    for (path, entries) in &groups {
        let frag_entries: BTreeMap<String, String> = entries.iter().filter_map(|(k, v)| k.clone().map(|f| (f, v.clone()))).collect();
        if existing.contains(path) {
            if !frag_entries.is_empty() {
                fragment_maps.insert(path.clone(), serde_json::to_string(&frag_entries).unwrap_or_default());
            }
            continue;
        }
        let default_dest = match entries.get(&None) {
            Some(d) => d.clone(),
            None => {
                let err = vec![
                    "Rendering failed".to_string(),
                    "Unable to emit redirects".to_string(),
                    format!("redirect entry for `{}` only has source paths with `#` fragments\nThere must be an entry without the `#` fragment to determine the default destination.", path.trim_end_matches(".html")),
                ];
                return (files, fragment_maps, Some(err));
            }
        };
        let frag_json = serde_json::to_string(&frag_entries).unwrap_or_default();
        files.push((path.clone(), redirect_page(&default_dest, &frag_json)));
    }
    (files, fragment_maps, None)
}

fn redirect_page(dest: &str, frag_json: &str) -> String {
    format!(r##"<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <title>Redirecting...</title>
    <meta http-equiv="refresh" content="0; URL={dest}">
    <link rel="canonical" href="{dest}">
  </head>
  <body>
      <p>Redirecting to... <a href="{dest}">{dest}</a>.</p>

<script>
    // This handles redirects that involve fragments.
    document.addEventListener('DOMContentLoaded', function() {{
        const fragmentMap =
            {frag_json}
        ;
        const fragment = window.location.hash;
        if (fragment) {{
            let redirectUrl = "{dest}";
            const target = fragmentMap[fragment];
            if (target) {{
                let url = new URL(target, window.location.href);
                redirectUrl = url.href;
            }} else {{
                let url = new URL(redirectUrl, window.location.href);
                url.hash = window.location.hash;
                redirectUrl = url.href;
            }}
            window.location.replace(redirectUrl);
        }}
        // else redirect handled by http-equiv
    }});
</script>
  </body>
</html>
"##, dest = dest, frag_json = frag_json)
}

// ---------- markdown renderer ----------
pub fn render_markdown_backend(book: &Book, dest: &Path) -> Result<(), Vec<String>> {
    if dest.is_dir() { let _ = std::fs::remove_dir_all(dest); }
    std::fs::create_dir_all(dest).map_err(|e| vec![format!("{}", e)])?;
    for (ch, _) in flatten_with_parents(book) {
        if let Some(loc) = &ch.location {
            let out = dest.join(loc);
            if let Some(parent) = out.parent() { std::fs::create_dir_all(parent).map_err(|e| vec![format!("{}", e)])?; }
            std::fs::write(&out, &ch.content).map_err(|e| vec![format!("{}", e)])?;
        }
    }
    Ok(())
}

// ---------- custom backend ----------
pub fn run_custom_backend(name: &str, cfg_table: &Value, book: &Book, cfg: &Value, root: &Path, dest: &Path) -> Result<(), Vec<String>> {
    crate::log_info!("mdbook_driver::builtin_renderers", "Invoking the \"{}\" renderer", name);
    let optional = cfg_table.get("optional").and_then(|v| v.as_bool()).unwrap_or(false);
    let command_str = cfg_table.get("command").and_then(|v| v.as_str()).map(|s| s.to_string()).unwrap_or_else(|| format!("mdbook-{}", name));
    std::fs::create_dir_all(dest).map_err(|e| vec!["Rendering failed".into(), format!("{}", e)])?;
    let ctx = json!({
        "version": "0.5.0-alpha.1",
        "root": root.to_string_lossy(),
        "book": crate::preprocess::book_to_json(book),
        "config": crate::preprocess::context_config(cfg),
        "destination": dest.to_string_lossy(),
    });
    let args = crate::shell_words::split(&command_str);
    if args.is_empty() { return Ok(()); }
    let (prog, rest) = args.split_first().unwrap();
    let mut cmd = std::process::Command::new(prog);
    cmd.args(rest).current_dir(dest).stdin(std::process::Stdio::piped());
    let mut child = match cmd.spawn() {
        Ok(c) => c,
        Err(e) => {
            if e.kind() == std::io::ErrorKind::NotFound {
                if optional {
                    crate::log_warn!("mdbook_driver::builtin_renderers", "The command `{}` for backend `{}` was not found, but was marked as optional.", command_str, name);
                    return Ok(());
                }
                crate::log_error!("mdbook_driver::builtin_renderers", "The command `{}` wasn't found, is the \"{}\" backend installed? If you want to ignore this error when the \"{}\" backend is not installed, set `optional = true` in the `[output.{name}]` section of the book.toml configuration file.", prog, name, name, name = name);
                return Err(vec!["Rendering failed".into(), "Unable to start the backend".into(), format!("{}", e)]);
            }
            return Err(vec!["Rendering failed".into(), "Unable to start the backend".into(), format!("{}", e)]);
        }
    };
    use std::io::Write;
    if let Some(mut stdin) = child.stdin.take() {
        let _ = stdin.write_all(ctx.to_string().as_bytes());
    }
    let status = child.wait().map_err(|e| vec!["Rendering failed".into(), format!("{}", e)])?;
    if !status.success() {
        crate::log_error!("mdbook_driver::builtin_renderers", "Renderer exited with non-zero return code.");
        return Err(vec!["Rendering failed".into(), format!("The \"{}\" renderer failed", name)]);
    }
    Ok(())
}
