use std::collections::HashMap;
use std::io::{Read, Write};
use std::net::{TcpListener, TcpStream, ToSocketAddrs};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use std::time::{Duration, SystemTime};

pub type Snapshot = HashMap<PathBuf, (SystemTime, u64)>;

pub fn snapshot_dirs(dirs: &[PathBuf]) -> Snapshot {
    let mut map = HashMap::new();
    for d in dirs {
        if d.is_file() {
            if let Ok(m) = std::fs::metadata(d) {
                map.insert(d.clone(), (m.modified().unwrap_or(SystemTime::UNIX_EPOCH), m.len()));
            }
            continue;
        }
        collect(d, &mut map);
    }
    map
}

fn collect(dir: &Path, map: &mut Snapshot) {
    if let Ok(rd) = std::fs::read_dir(dir) {
        let mut entries: Vec<PathBuf> = rd.filter_map(|e| e.ok().map(|e| e.path())).collect();
        entries.sort();
        for e in entries {
            if e.is_dir() { collect(&e, map); }
            else if let Ok(m) = std::fs::metadata(&e) {
                map.insert(e, (m.modified().unwrap_or(SystemTime::UNIX_EPOCH), m.len()));
            }
        }
    }
}

pub fn changed_paths(old: &Snapshot, new: &Snapshot) -> Vec<PathBuf> {
    let mut changed = Vec::new();
    for (k, v) in new {
        if old.get(k) != Some(v) { changed.push(k.clone()); }
    }
    for k in old.keys() {
        if !new.contains_key(k) { changed.push(k.clone()); }
    }
    changed.sort();
    changed.dedup();
    changed
}

fn http_date(t: SystemTime) -> String {
