        "html" | "htm" => "text/html",
        "css" => "text/css",
        "js" => "text/javascript",
        "json" => "application/json",
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "svg" => "image/svg+xml",
        "ico" => "image/x-icon",
        "woff" => "font/woff",
        "woff2" => "font/woff2",
        "ttf" => "font/ttf",
        "eot" => "application/vnd.ms-fontobject",
        "txt" => "text/plain",
        "xml" => "text/xml",
        "md" => "text/markdown",
        _ => "application/octet-stream",
    }
}

pub struct ServerState {
    pub dest: PathBuf,
    pub ws_clients: Mutex<Vec<std::sync::mpsc::Sender<String>>>,
}

pub fn notify_reload(state: &Arc<ServerState>) {
    let mut clients = state.ws_clients.lock().unwrap();
    clients.retain(|tx| tx.send("reload".to_string()).is_ok());
}

pub fn serve_http(state: Arc<ServerState>, listener: TcpListener) {
    for stream in listener.incoming() {
        match stream {
            Ok(s) => {
                let st = state.clone();
                std::thread::spawn(move || handle_connection(s, st));
            }
            Err(_) => continue,
        }
    }
}

fn handle_connection(mut stream: TcpStream, state: Arc<ServerState>) {
    let _ = stream.set_read_timeout(Some(Duration::from_secs(10)));
    let mut buf: Vec<u8> = Vec::new();
    let mut tmp = [0u8; 4096];
    let head_end;
    loop {
        match stream.read(&mut tmp) {
            Ok(0) => return,
            Ok(n) => {
                buf.extend_from_slice(&tmp[..n]);
                if let Some(pos) = find_subslice(&buf, b"\r\n\r\n") { head_end = pos; break; }
                if buf.len() > 65536 { return; }
            }
            Err(_) => return,
        }
    }
    let head = String::from_utf8_lossy(&buf[..head_end]).to_string();
    let mut lines = head.lines();
    let first = lines.next().unwrap_or("");
    let mut parts = first.split_whitespace();
    let method = parts.next().unwrap_or("GET").to_string();
    let raw_path = parts.next().unwrap_or("/").to_string();
    let mut headers: HashMap<String, String> = HashMap::new();
    for line in lines {
        if let Some((k, v)) = line.split_once(':') {
            headers.insert(k.trim().to_ascii_lowercase(), v.trim().to_string());
        }
    }

    // Websocket for livereload.
    if raw_path.split('?').next().unwrap_or("") == "/__livereload" {
        let upgrade = headers.get("upgrade").map(|s| s.to_ascii_lowercase()).unwrap_or_default();
        if upgrade.contains("websocket") {
            if let Some(key) = headers.get("sec-websocket-key") {
                let accept_src = format!("{}258EAFA5-E914-47DA-95CA-C5AB0DC85B11", key);
                let digest = crate::sha256::hex_to_bytes(&crate::sha256::sha1_hex(accept_src.as_bytes()));
                let accept = crate::sha256::base64_encode(&digest);
                let resp = format!("HTTP/1.1 101 Switching Protocols\r\nconnection: upgrade\r\nupgrade: websocket\r\nsec-websocket-accept: {}\r\ndate: {}\r\n\r\n", accept, http_date(SystemTime::now()));
                if stream.write_all(resp.as_bytes()).is_err() { return; }
                let (tx, rx) = std::sync::mpsc::channel::<String>();
                state.ws_clients.lock().unwrap().push(tx);
                // Send messages as they arrive; also drain incoming frames.
                let _ = stream.set_read_timeout(Some(Duration::from_millis(200)));
                let mut ws_stream = stream;
                loop {
                    match rx.recv_timeout(Duration::from_millis(200)) {
                        Ok(msg) => {
                            if send_ws_text(&mut ws_stream, &msg).is_err() { break; }
                        }
                        Err(std::sync::mpsc::RecvTimeoutError::Timeout) => {
                            // Try reading a frame (to notice close).
                            let mut b = [0u8; 2];
                            match ws_stream.read(&mut b) {
                                Ok(0) => break,
                                Ok(_) => {
                                    if b[0] & 0x0F == 0x8 { break; }
                                    // ignore other frames (payload handling is minimal)
                                }
                                Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock || e.kind() == std::io::ErrorKind::TimedOut => continue,
                                Err(_) => break,
                            }
                        }
                        Err(_) => break,
                    }
                }
                return;
            }
        }
    }

    if method != "GET" && method != "HEAD" {
        let body = b"Method Not Allowed";
        let resp = format!("HTTP/1.1 405 Method Not Allowed\r\ncontent-length: {}\r\ndate: {}\r\n\r\n", body.len(), http_date(SystemTime::now()));
        let _ = stream.write_all(resp.as_bytes());
        if method != "HEAD" { let _ = stream.write_all(body); }
        return;
    }

    let path_only = raw_path.split('?').next().unwrap_or("/").to_string();
    let decoded = percent_decode(&path_only);
    let mut rel = decoded.trim_start_matches('/').to_string();
    if rel.is_empty() { rel = "index.html".to_string(); }
    let mut file_path = state.dest.join(&rel);
    // Prevent traversal outside dest.
    let dest_canon = state.dest.canonicalize().unwrap_or_else(|_| state.dest.clone());
    if let Ok(canon) = file_path.canonicalize() {
        if !canon.starts_with(&dest_canon) {
            file_path = state.dest.join("404.html");
        } else {
            file_path = canon;
        }
    }
    if file_path.is_dir() {
        file_path = file_path.join("index.html");
    }

    if file_path.is_file() {
        let meta = std::fs::metadata(&file_path).ok();
        let modified = meta.as_ref().and_then(|m| m.modified().ok()).unwrap_or_else(SystemTime::now);
        // Range support
        if let Some(range) = headers.get("range") {
            if let Ok(data) = std::fs::read(&file_path) {
                if let Some((start, end)) = parse_range(range, data.len()) {
                    let slice = &data[start..=end];
                    let resp = format!("HTTP/1.1 206 Partial Content\r\ncontent-type: {}\r\naccept-ranges: bytes\r\ncontent-range: bytes {}-{}/{}\r\nlast-modified: {}\r\ncontent-length: {}\r\ndate: {}\r\n\r\n", content_type(&file_path), start, end, data.len(), http_date(modified), slice.len(), http_date(SystemTime::now()));
                    let _ = stream.write_all(resp.as_bytes());
                    if method == "GET" { let _ = stream.write_all(slice); }
                    return;
                }
            }
        }
        match std::fs::read(&file_path) {
            Ok(data) => {
                let resp = format!("HTTP/1.1 200 OK\r\ncontent-type: {}\r\naccept-ranges: bytes\r\nlast-modified: {}\r\ncontent-length: {}\r\ndate: {}\r\n\r\n", content_type(&file_path), http_date(modified), data.len(), http_date(SystemTime::now()));
                let _ = stream.write_all(resp.as_bytes());
                if method == "GET" { let _ = stream.write_all(&data); }
            }
            Err(_) => {}
        }
        return;
    }

    // 404 fallback with the book's 404 page.
    let not_found = state.dest.join("404.html");
    let (body, ct, lm) = if not_found.is_file() {
        let m = std::fs::metadata(&not_found).and_then(|md| md.modified()).unwrap_or_else(|_| SystemTime::now());
        (std::fs::read(&not_found).unwrap_or_default(), "text/html", m)
    } else {
        (b"404 Not Found".to_vec(), "text/plain", SystemTime::now())
    };
    let resp = format!("HTTP/1.1 404 Not Found\r\ncontent-type: {}\r\naccept-ranges: bytes\r\nlast-modified: {}\r\ncontent-length: {}\r\ndate: {}\r\n\r\n", ct, http_date(lm), body.len(), http_date(SystemTime::now()));
    let _ = stream.write_all(resp.as_bytes());
    if method == "GET" { let _ = stream.write_all(&body); }
}

fn parse_range(range: &str, total: usize) -> Option<(usize, usize)> {
    let spec = range.strip_prefix("bytes=")?;
    let (a, b) = spec.split_once('-')?;
    if a.is_empty() {
        let suffix: usize = b.parse().ok()?;
        if suffix == 0 || total == 0 { return None; }
        return Some((total.saturating_sub(suffix), total - 1));
    }
    let start: usize = a.parse().ok()?;
    let end: usize = if b.is_empty() { total - 1 } else { b.parse().ok()? };
    if start > end || start >= total { return None; }
    Some((start, end.min(total - 1)))
}

fn send_ws_text(stream: &mut TcpStream, msg: &str) -> std::io::Result<()> {
    let payload = msg.as_bytes();
    let mut frame = Vec::new();
    frame.push(0x81u8);
    if payload.len() < 126 {
        frame.push(payload.len() as u8);
    } else {
        frame.push(126);
        frame.extend_from_slice(&(payload.len() as u16).to_be_bytes());
    }
    frame.extend_from_slice(payload);
    stream.write_all(&frame)
}

fn find_subslice(hay: &[u8], needle: &[u8]) -> Option<usize> {
    hay.windows(needle.len()).position(|w| w == needle)
}

fn percent_decode(s: &str) -> String {
    let b = s.as_bytes();
    let mut out = Vec::new();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() {
            if let Ok(v) = u8::from_str_radix(&s[i+1..i+3], 16) { out.push(v); i += 3; continue; }
        }
        if b[i] == b'+' { out.push(b' '); i += 1; continue; }
        out.push(b[i]); i += 1;
    }
    String::from_utf8_lossy(&out).to_string()
}

pub fn resolve_addr(hostname: &str, port: &str) -> Result<std::net::SocketAddr, Vec<String>> {
    // Port validity is checked separately by the caller in the original
    // (it reports "invalid port value" after building).
    let addr_str = format!("{}:{}", hostname, port);
    match addr_str.to_socket_addrs() {
        Ok(mut iter) => match iter.next() {
            Some(a) => Ok(a),
            None => Err(vec![format!("Couldn't resolve hostname {}", hostname)]),
        },
        Err(e) => Err(vec![format!("{}", e)]),
    }
}
