                .arg(dest_arg())
                .arg(Arg::new("chapter").short('c').long("chapter").value_name("chapter"))
                .arg(Arg::new("library-path").short('L').long("library-path").value_name("dir").action(ArgAction::Append)
                    .help("A comma-separated list of directories to add to the crate search path\nwhen building tests"))
                .arg(dir_arg("Root directory for the book\n(Defaults to the current directory when omitted)")),
        )
        .subcommand(
            Command::new("clean").version(VERSION).about("Deletes a built book")
                .arg(dest_arg())
                .arg(dir_arg("Root directory for the book\n(Defaults to the current directory when omitted)")),
        )
        .subcommand(
            Command::new("completions").version(VERSION).about("Generate shell completions for your shell to stdout")
                .arg(Arg::new("shell").value_name("SHELL").required(true).value_parser(["bash", "elvish", "fish", "powershell", "zsh"]).help("the shell to generate completions for")),
        )
        .subcommand(
            Command::new("watch").version(VERSION).about("Watches a book's files and rebuilds it on changes")
                .arg(dest_arg())
                .arg(Arg::new("open").short('o').long("open").action(ArgAction::SetTrue).help("Opens the compiled book in a web browser"))
                .arg(Arg::new("watcher").long("watcher").value_name("watcher").default_value("poll").value_parser(["poll", "native"]).help("The filesystem watching technique"))
                .arg(dir_arg("Root directory for the book\n(Defaults to the current directory when omitted)")),
        )
        .subcommand(
            Command::new("serve").version(VERSION).about("Serves a book at http://localhost:3000, and rebuilds it on changes")
                .arg(dest_arg())
                .arg(Arg::new("hostname").short('n').long("hostname").value_name("hostname").default_value("localhost").help("Hostname to listen on for HTTP connections"))
                .arg(Arg::new("port").short('p').long("port").value_name("port").default_value("3000").help("Port to use for HTTP connections"))
                .arg(Arg::new("open").short('o').long("open").action(ArgAction::SetTrue).help("Opens the compiled book in a web browser"))
                .arg(Arg::new("watcher").long("watcher").value_name("watcher").default_value("poll").value_parser(["poll", "native"]).help("The filesystem watching technique"))
                .arg(dir_arg("Root directory for the book\n(Defaults to the current directory when omitted)")),
        )
}

fn main() {
    let matches = cli().get_matches();
    match matches.subcommand() {
        Some(("init", sub)) => cmd_init(sub),
        Some(("build", sub)) => {
            let root = config::root_dir(sub.get_one::<String>("dir"));
            let dest = sub.get_one::<String>("dest-dir");
            if let Err(chain) = execute_build(&root, dest, false) {
                logger::fatal(&chain);
            }
            if sub.get_flag("open") {
                open_browser(&root, dest);
            }
        }
        Some(("test", sub)) => cmd_test(sub),
        Some(("clean", sub)) => cmd_clean(sub),
        Some(("completions", sub)) => {
            let shell = sub.get_one::<String>("shell").unwrap();
            let sh = match shell.as_str() {
                "bash" => clap_complete::Shell::Bash,
                "elvish" => clap_complete::Shell::Elvish,
                "fish" => clap_complete::Shell::Fish,
                "powershell" => clap_complete::Shell::PowerShell,
                "zsh" => clap_complete::Shell::Zsh,
                _ => unreachable!(),
            };
            let mut cmd = cli();
            clap_complete::generate(sh, &mut cmd, "mdbook", &mut std::io::stdout());
        }
        Some(("watch", sub)) => cmd_watch(sub),
        Some(("serve", sub)) => cmd_serve(sub),
        _ => unreachable!(),
    }
}

fn get_dest(sub: &clap::ArgMatches) -> Option<&String> { sub.get_one::<String>("dest-dir") }

fn execute_build(root: &Path, dest_arg: Option<&String>, live_reload: bool) -> Result<PathBuf, Vec<String>> {
    let cfg = config::load_config(root);
    let src_dir = config::src_dir(root, &cfg);
    log_debug!("mdbook_driver::load", "Loading the book from disk");
    let book = book::load_book(root, &cfg)?;
    log_info!("mdbook_driver::mdbook", "Book building has started");
    let build_dir = config::build_dir(root, &cfg, dest_arg);
    // determine renderers
    let output = config::get(&cfg, &["output"]).cloned();
    let mut renderer_names: Vec<String> = Vec::new();
    if let Some(Value::Object(map)) = &output {
        for k in map.keys() { renderer_names.push(k.clone()); }
    }
    if renderer_names.is_empty() { renderer_names.push("html".to_string()); }
    // The original executes backends in a non-deterministic map order; use
    // a stable order here.
    for name in &renderer_names {
        let processed = preprocess::run_preprocessors(&book, &cfg, root, name, &src_dir)?;
        let dest = if renderer_names.len() > 1 { build_dir.join(name) } else { build_dir.clone() };
        log_info!("mdbook_driver::mdbook", "Running the {} backend", name);
        match name.as_str() {
            "html" => render::render_html(&processed, &cfg, root, &dest, live_reload)?,
            "markdown" => render::render_markdown_backend(&processed, &dest)?,
            _ => {
                let table = config::get(&cfg, &["output", name]).cloned().unwrap_or_else(|| json!({}));
                render::run_custom_backend(name, &table, &processed, &cfg, root, &dest)?;
            }
        }
    }
    Ok(build_dir)
}

fn rendered_index_path(root: &Path, dest_arg: Option<&String>) -> PathBuf {
    // Re-load just enough config to figure the destination and whether html
    // output ended up in a subfolder.
    let cfg = config::load_config(root);
    let build_dir = config::build_dir(root, &cfg, dest_arg);
    let output = config::get(&cfg, &["output"]).cloned();
    let mut names: Vec<String> = Vec::new();
    if let Some(Value::Object(map)) = &output { for k in map.keys() { names.push(k.clone()); } }
    if names.len() > 1 && names.iter().any(|n| n == "html") { build_dir.join("html").join("index.html") }
    else { build_dir.join("index.html") }
}

fn open_browser(root: &Path, dest_arg: Option<&String>) {
    let index = rendered_index_path(root, dest_arg);
    log_info!("mdbook", "Opening web browser");
    open_path(&index);
}

fn open_path(path: &Path) {
    #[cfg(target_os = "macos")]
    let prog = "open";
    #[cfg(target_os = "windows")]
    let prog = "explorer";
    #[cfg(not(any(target_os = "macos", target_os = "windows")))]
    let prog = "xdg-open";
    let _ = std::process::Command::new(prog).arg(path).stdin(std::process::Stdio::null()).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).spawn();
}

// ---------------- init ----------------

fn read_line() -> String {
    let mut s = String::new();
    let _ = std::io::Read::read_line(&mut std::io::stdin().lock(), &mut s);
    s
}

fn toml_string(s: &str) -> String {
    // Match the style the original produces: a literal string when the
    // value contains double quotes, otherwise a basic string.
    if s.contains('"') && !s.contains('\'') && !s.contains('\n') {
        format!("'{}'", s)
    } else {
        let mut out = String::from("\"");
        for c in s.chars() {
            match c {
                '"' => out.push_str("\\\""),
                '\\' => out.push_str("\\\\"),
                '\n' => out.push_str("\\n"),
                '\r' => out.push_str("\\r"),
                '\t' => out.push_str("\\t"),
                c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04X}", c as u32)),
                c => out.push(c),
            }
        }
        out.push('"');
        out
    }
}

fn cmd_init(sub: &clap::ArgMatches) {
    log_info!("mdbook_driver::init", "Creating a new book with stub content");
    let root = config::root_dir(sub.get_one::<String>("dir"));
    let force = sub.get_flag("force");
    let copy_theme = sub.get_flag("theme");

    let mut ignore_git: bool;
    match sub.get_one::<String>("ignore").map(|s| s.as_str()) {
        Some("git") => ignore_git = true,
        Some(_) => ignore_git = false,
        None => {
            if force {
                ignore_git = false;
            } else {
                println!("\nDo you want a .gitignore to be created? (y/n)");
                let answer = read_line();
                let a = answer.trim();
                ignore_git = matches!(a, "y" | "Y" | "yes" | "Yes");
            }
        }
    }
    let title: Option<String> = match sub.get_one::<String>("title") {
        Some(t) => Some(t.clone()),
        None => {
            if force {
                None
            } else {
                println!("What title would you like to give the book? ");
                let t = read_line().trim().to_string();
                if t.is_empty() { None } else { Some(t) }
            }
        }
    };
    let _ = &mut ignore_git;

    if let Err(chain) = do_init(&root, title.as_deref(), ignore_git, copy_theme) {
        logger::fatal(&chain);
    }
    println!("\nAll done, no errors...");
}

fn do_init(root: &Path, title: Option<&str>, ignore_git: bool, copy_theme: bool) -> Result<(), Vec<String>> {
    log_debug!("mdbook_driver::init", "Creating directory tree");
    // directory tree: root/, root/src, root/book
    for dir in [root.to_path_buf(), root.join("src"), root.join("book")] {
        std::fs::create_dir_all(&dir).map_err(|e| vec!["Unable to create directory structure".to_string(), format!("{}", e)])?;
    }
    let src = root.join("src");
    log_debug!("mdbook_driver::init", "Creating example book contents");
    let summary_path = src.join("SUMMARY.md");
    if summary_path.exists() {
        // Generate missing chapters named in the existing summary.
        if let Ok(text) = std::fs::read_to_string(&summary_path) {
            if let Ok(parsed) = book::parse_summary2(&text, &summary_path) {
                let tmp_book = book::Book { items: parsed.items };
                for ch in tmp_book.chapters_flat() {
                    if let Some(loc) = &ch.location {
                        let p = src.join(loc);
                        if !p.exists() {
                            if let Some(parent) = p.parent() { let _ = std::fs::create_dir_all(parent); }
                            let _ = std::fs::write(&p, format!("# {}\n", ch.name));
                        }
                    }
                }
            }
        }
    } else {
        std::fs::write(&summary_path, "# Summary\n\n- [Chapter 1](./chapter_1.md)\n").map_err(|e| vec![format!("{}", e)])?;
        std::fs::write(src.join("chapter_1.md"), "# Chapter 1\n").map_err(|e| vec![format!("{}", e)])?;
    }
    // book.toml
    log_debug!("mdbook_driver::init", "Writing book.toml");
    let mut toml = String::from("[book]\nauthors = []\nlanguage = \"en\"\nsrc = \"src\"\n");
    if let Some(t) = title { toml.push_str(&format!("title = {}\n", toml_string(t))); }
    std::fs::write(root.join("book.toml"), toml).map_err(|e| vec![format!("{}", e)])?;
    if ignore_git {
        let _ = std::fs::write(root.join(".gitignore"), "book\n");
    }
    if copy_theme {
        let theme_dir = root.join("theme");
        println!("\nCopying the default theme to {}", theme_dir.display());
        write_default_theme(&theme_dir).map_err(|e| vec![format!("{}", e)])?;
    }
    Ok(())
}

fn write_default_theme(theme_dir: &Path) -> std::io::Result<()> {
    let mut files: Vec<(String, Vec<u8>)> = Vec::new();
    files.push(("index.hbs".into(), theme::INDEX_HBS.as_bytes().to_vec()));
    files.push(("book.js".into(), theme::BOOK_JS.as_bytes().to_vec()));
    files.push(("css/variables.css".into(), theme::VARIABLES_CSS.as_bytes().to_vec()));
    files.push(("css/general.css".into(), theme::GENERAL_CSS.as_bytes().to_vec()));
    files.push(("css/chrome.css".into(), theme::CHROME_CSS.as_bytes().to_vec()));
    files.push(("css/print.css".into(), theme::PRINT_CSS.as_bytes().to_vec()));
    files.push(("favicon.svg".into(), theme::FAVICON_SVG.as_bytes().to_vec()));
    files.push(("favicon.png".into(), theme::favicon_png()));
    files.push(("fonts/fonts.css".into(), theme::FONTS_CSS.as_bytes().to_vec()));
    files.push(("fonts/OPEN-SANS-LICENSE.txt".into(), theme::OPEN_SANS_LICENSE.as_bytes().to_vec()));
    files.push(("fonts/SOURCE-CODE-PRO-LICENSE.txt".into(), theme::SOURCE_CODE_PRO_LICENSE.as_bytes().to_vec()));
    for f in theme::font_files() { files.push((format!("fonts/{}", f), theme::dummy_font(&f))); }
    files.push(("highlight.css".into(), theme::HIGHLIGHT_CSS.as_bytes().to_vec()));
    files.push(("highlight.js".into(), theme::HIGHLIGHT_JS.as_bytes().to_vec()));
    for (rel, content) in files {
        let p = theme_dir.join(&rel);
        if let Some(parent) = p.parent() { std::fs::create_dir_all(parent)?; }
        std::fs::write(&p, content)?;
    }
    Ok(())
}

// ---------------- clean ----------------

fn human_size(n: u64) -> String {
    if n < 1024 { format!("{}B", n) }
    else if n < 1024 * 1024 { format!("{:.2}KiB", n as f64 / 1024.0) }
    else if n < 1024 * 1024 * 1024 { format!("{:.2}MiB", n as f64 / 1048576.0) }
    else { format!("{:.2}GiB", n as f64 / 1073741824.0) }
}

fn cmd_clean(sub: &clap::ArgMatches) {
    let root = config::root_dir(sub.get_one::<String>("dir"));
    let cfg = config::load_config(&root);
    // Loading the book validates that SUMMARY.md exists in the original.
    match book::load_book(&root, &cfg) {
        Ok(_) => {}
        Err(chain) => logger::fatal(&chain),
    }
    let dest = config::build_dir(&root, &cfg, get_dest(sub));
    if dest.is_dir() {
        let (files, dirs, total) = count_removable(&dest);
        let _ = std::fs::remove_dir_all(&dest);
        if files > 0 {
            println!("Removed {} {}, {} total", files, if files == 1 { "file" } else { "files" }, human_size(total));
        } else if dirs > 0 {
            println!("Removed {} {}, {} total", dirs, if dirs == 1 { "directory" } else { "directories" }, human_size(total));
        } else {
            println!("Removed 0 files");
        }
    } else {
        println!("Removed 0 files");
    }
}

fn count_removable(dest: &Path) -> (u64, u64, u64) {
    let mut files = 0u64; let mut dirs = 0u64; let mut total = 0u64;
    fn walk(p: &Path, files: &mut u64, dirs: &mut u64, total: &mut u64) {
        if let Ok(md) = std::fs::metadata(p) { *total += md.len(); } 
        if p.is_dir() {
            *dirs += 1;
            if let Ok(rd) = std::fs::read_dir(p) {
                let mut entries: Vec<PathBuf> = rd.filter_map(|e| e.ok().map(|e| e.path())).collect();
                entries.sort();
                for e in entries { walk(&e, files, dirs, total); }
            }
        } else {
            *files += 1;
        }
    }
    walk(dest, &mut files, &mut dirs, &mut total);
    (files, dirs, total)
}

// ---------------- test ----------------

fn cmd_test(sub: &clap::ArgMatches) {
    let root = config::root_dir(sub.get_one::<String>("dir"));
    let cfg = config::load_config(&root);
    let src_dir = config::src_dir(&root, &cfg);
    let book = match book::load_book(&root, &cfg) {
        Ok(b) => b,
        Err(chain) => logger::fatal(&chain),
    };
    let chapter_filter = sub.get_one::<String>("chapter").cloned();
    if let Some(ch_name) = &chapter_filter {
        let exists = book.chapters_flat().iter().any(|c| c.name == *ch_name || c.source_path_display == *ch_name || c.location.as_ref().map(|p| p.to_string_lossy().to_string()) == Some(ch_name.clone()));
        if !exists {
            logger::fatal(&[format!("Chapter not found: {}", ch_name)]);
        }
    }
    let processed = match preprocess::run_preprocessors(&book, &cfg, &root, "test", &src_dir) {
        Ok(b) => b,
        Err(chain) => logger::fatal(&chain),
    };
    // library paths
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let mut lib_dirs: Vec<PathBuf> = Vec::new();
    if let Some(vals) = sub.get_many::<String>("library-path") {
        for v in vals {
            for part in v.split(',') {
                if part.is_empty() { continue; }
                let p = PathBuf::from(part);
                if p.is_absolute() { lib_dirs.push(p); } else { lib_dirs.push(cwd.join(p)); }
            }
        }
    }
    let edition = config::get_str(&cfg, &["rust", "edition"]);
    // temp directory /tmp/mdbook-XXXXXX
    let tmp_dir = make_temp_dir();
    let mut any_failed = false;
    for ch in processed.chapters_flat() {
        let source_rel = if !ch.source_path_display.is_empty() { ch.source_path_display.clone() } else if let Some(loc) = &ch.location { loc.to_string_lossy().to_string() } else { continue };
        if let Some(filter) = &chapter_filter {
            if !(ch.name == *filter || source_rel == *filter || ch.location.as_ref().map(|p| p.to_string_lossy().to_string()) == Some(filter.clone())) { continue; }
        }
        if ch.location.is_none() { continue; }
        log_info!("mdbook_driver::mdbook", "Testing chapter '{}': {:?}", ch.name, source_rel);
        let file_path = tmp_dir.join(&source_rel);
        if let Some(parent) = file_path.parent() { let _ = std::fs::create_dir_all(parent); }
        let _ = std::fs::write(&file_path, &ch.content);
        let mut cmd = std::process::Command::new("rustdoc");
        cmd.arg(&source_rel).arg("--test").current_dir(&tmp_dir);
        for lib in &lib_dirs { cmd.arg("-L").arg(lib); }
        if let Some(ed) = &edition { cmd.arg("--edition").arg(ed); }
        match cmd.output() {
            Ok(out) => {
                if !out.status.success() {
                    any_failed = true;
                    let msg = format!("rustdoc returned an error:\n\n--- stdout\n{}\n--- stderr\n{}", String::from_utf8_lossy(&out.stdout), String::from_utf8_lossy(&out.stderr));
                    log_error!("mdbook_driver::mdbook", "{}", msg);
                }
            }
            Err(e) => {
                any_failed = true;
                log_error!("mdbook_driver::mdbook", "rustdoc returned an error:\n\n--- stdout\n\n--- stderr\n{}", e);
            }
        }
    }
    let _ = std::fs::remove_dir_all(&tmp_dir);
    if any_failed {
        logger::fatal(&["One or more tests failed".to_string()]);
    }
}

fn make_temp_dir() -> PathBuf {
    let base = std::env::temp_dir();
    let pid = std::process::id();
    for attempt in 0..100u32 {
        let nanos = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_nanos()).unwrap_or(0);
        let mut seed = (nanos as u64) ^ ((pid as u64) << 20) ^ (attempt as u64 * 0x9e37);
        let mut rand_str = String::new();
        const CHARS: &[u8] = b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        for _ in 0..6 {
            seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            rand_str.push(CHARS[((seed >> 40) % 62) as usize] as char);
        }
        let dir = base.join(format!("mdbook-{}", rand_str));
        if std::fs::create_dir(&dir).is_ok() { return dir; }
    }
    base.join("mdbook-temp")
}

// ---------------- watch / serve ----------------

fn watched_dirs(root: &Path, cfg: &Value) -> Vec<PathBuf> {
    let mut dirs = Vec::new();
    dirs.push(config::src_dir(root, cfg));
    dirs.push(root.join("book.toml"));
    let theme = config::get_str(cfg, &["output", "html", "theme"]).map(|t| root.join(t)).unwrap_or_else(|| root.join("theme"));
    dirs.push(theme);
    for extra in config::get_str_list(cfg, &["build", "extra-watch-dirs"]) {
        let p = PathBuf::from(&extra);
        dirs.push(if p.is_absolute() { p } else { root.join(p) });
    }
    dirs
}

fn watch_loop(root: &Path, dest_arg: Option<&String>, open: bool, live: bool, state: Option<std::sync::Arc<serve::ServerState>>) {
    // caller logs the "watching" message
    let cfg = config::load_config(root);
    let dirs = watched_dirs(root, &cfg);
    let mut snapshot = serve::snapshot_dirs(&dirs);
    let mut opened = false;
    loop {
        std::thread::sleep(Duration::from_secs(1));
        // Reload config in case book.toml/theme changed the watched set.
        let cfg2 = config::load_config(root);
        let dirs2 = watched_dirs(root, &cfg2);
        let new_snapshot = serve::snapshot_dirs(&dirs2);
        let changed = serve::changed_paths(&snapshot, &new_snapshot);
        snapshot = new_snapshot;
        if changed.is_empty() { continue; }
        if live {
            log_info!("mdbook::cmd::watch::poller", "Files changed: {:?}", changed);
        } else {
            log_info!("mdbook::cmd::watch::poller", "Files changed: {:?}", changed);
        }
        match execute_build(root, dest_arg, live) {
            Ok(_) => {
                if let Some(state) = &state { serve::notify_reload(state); }
                if open && !opened {
                    opened = true;
                    open_browser(root, dest_arg);
                }
            }
            Err(chain) => {
                if let Some((first, rest)) = chain.split_first() {
                    log_error!("mdbook_core::utils", "Error: {}", first);
                    for c in rest { log_error!("mdbook_core::utils", "\tCaused By: {}", c); }
                }
            }
        }
    }
}

fn cmd_watch(sub: &clap::ArgMatches) {
    let root = config::root_dir(sub.get_one::<String>("dir"));
    let cfg = config::load_config(&root);
    // The original attempts to load the book before watching.
    if let Err(chain) = book::load_book(&root, &cfg) { logger::fatal(&chain); }
    let watcher = sub.get_one::<String>("watcher").cloned().unwrap_or_else(|| "poll".to_string());
    if watcher == "native" {
        log_info!("mdbook::cmd::watch::native", "Listening for changes...");
    } else {
        log_info!("mdbook::cmd::watch::poller", "Watching for changes...");
    }
    watch_loop(&root, get_dest(sub), sub.get_flag("open"), false, None);
}

fn cmd_serve(sub: &clap::ArgMatches) {
    let root = config::root_dir(sub.get_one::<String>("dir"));
    let hostname = sub.get_one::<String>("hostname").cloned().unwrap_or_else(|| "localhost".to_string());
    let port = sub.get_one::<String>("port").cloned().unwrap_or_else(|| "3000".to_string());
    // Build first (with live reload scripts).
    if let Err(chain) = execute_build(&root, get_dest(sub), true) {
        logger::fatal(&chain);
    }
    // Port validation happens after the initial build in the original.
    if port.parse::<u16>().is_err() {
        logger::fatal(&["invalid port value".to_string()]);
    }
    let addr = match serve::resolve_addr(&hostname, &port) {
        Ok(a) => a,
        Err(chain) => logger::fatal(&chain),
    };
    log_info!("mdbook::cmd::serve", "Serving on: http://{}:{}", hostname, port);
    let watcher = sub.get_one::<String>("watcher").cloned().unwrap_or_else(|| "poll".to_string());
    // Determine destination for serving.
    let cfg = config::load_config(&root);
    let build_dir = config::build_dir(&root, &cfg, get_dest(sub));
    let output = config::get(&cfg, &["output"]).cloned();
    let mut names: Vec<String> = Vec::new();
    if let Some(Value::Object(map)) = &output { for k in map.keys() { names.push(k.clone()); } }
    let dest = if names.len() > 1 && names.iter().any(|n| n == "html") { build_dir.join("html") } else { build_dir.clone() };
    let listener = match std::net::TcpListener::bind(addr) {
        Ok(l) => l,
        Err(e) => {
            log_error!("mdbook::cmd::serve", "Unable to serve: panicked at src/cmd/serve.rs:142:29:\nUnable to bind to {}: {}", addr, e);
            std::process::exit(1);
        }
    };
    if sub.get_flag("open") {
        open_browser(&root, get_dest(sub));
    }
    let state = std::sync::Arc::new(serve::ServerState { dest: dest.clone(), ws_clients: std::sync::Mutex::new(Vec::new()) });
    // watcher thread
    {
        let root_clone = root.clone();
        let dest_arg = get_dest(sub).cloned();
        let state_clone = state.clone();
        std::thread::spawn(move || {
            // Log watching message from the watcher thread.
            if watcher == "native" {
                log_info!("mdbook::cmd::watch::native", "Listening for changes...");
            } else {
                log_info!("mdbook::cmd::watch::poller", "Watching for changes...");
            }
            watch_loop(&root_clone, dest_arg.as_ref(), false, true, Some(state_clone));
        });
    }
    serve::serve_http(state, listener);
}
