    // Split out fenced code blocks so their contents are preserved
    // verbatim (and not given injected playground wrappers).
    let mut segments: Vec<String> = Vec::new();
    let mut buf: Vec<String> = Vec::new();
    let mut i = 0usize;
    let flush = |buf: &mut Vec<String>, segments: &mut Vec<String>| {
        if !buf.is_empty() {
            let text = buf.join("\\n");
