            let cleaned = plain.split_whitespace().collect::<Vec<_>>().join(" ");
            if !cleaned.is_empty() { segments.push(cleaned); }
            buf.clear();
        }
    };
    while i < lines.len() {
        let line = &lines[i];
        let t = line.trim_start();
        if let Some((fch, flen)) = markdown::fence_start(t) {
            flush(&mut buf, &mut segments);
            let mut code_lines: Vec<String> = Vec::new();
            i += 1;
            while i < lines.len() {
                let lt = lines[i].trim_start();
                if let Some((c2, n2)) = markdown::fence_start(lt) {
                    if c2 == fch && n2 >= flen { i += 1; break; }
                }
                code_lines.push(lines[i].clone());
                i += 1;
            }
            let code = code_lines.join("\\n");
            let code = code.trim_end().to_string();
            if !code.is_empty() { segments.push(code); }
            continue;
        }
        buf.push(line.clone());
        i += 1;
    }
    flush(&mut buf, &mut segments);
    segments.join(" ")
}

fn html_to_plain(html: &str) -> String {
    let mut out = String::new();
    let mut rest = html;
    loop {
        match rest.find('<') {
            None => { out.push_str(&decode_entities(rest)); break; }
            Some(i) => {
                out.push_str(&decode_entities(&rest[..i]));
                match rest[i..].find('>') {
