// ---------- [output.html] deserialisation (non-fatal, like the original) ----------

fn html_exp_error(v: &Value, expected: &str, path: &str) -> String {
    // Negative / out-of-range numbers are reported as "invalid value".
    if let Some(n) = v.as_i64() {
        if (expected == "u32" && (n < 0 || n > u32::MAX as i64)) || (expected == "u8" && (n < 0 || n > u8::MAX as i64)) {
            return format!("invalid value: integer `{}`, expected {}\nin `{}`", n, expected, path);
        }
    }
    if v.is_number() && (expected == "u32" || expected == "u8") {
        return format!("invalid value: {}, expected {}\nin `{}`", type_desc(v), expected, path);
    }
    format!("invalid type: {}, expected {}\nin `{}`", type_desc(v), expected, path)
}

fn check_html_value(v: &Value, expected: &str, path: &str) -> Option<String> {
    let ok = match expected {
        "a string" | "path string" => v.is_string(),
        "a boolean" => v.as_bool().is_some(),
        "a sequence" => v.is_array(),
        "a map" => v.is_object(),
        "u32" => v.as_u64().map_or(false, |n| n <= u32::MAX as u64) || v.as_i64().map_or(false, |n| n >= 0 && n <= u32::MAX as i64),
        "u8" => v.as_u64().map_or(false, |n| n <= u8::MAX as u64) || v.as_i64().map_or(false, |n| n >= 0 && n <= u8::MAX as i64),
        _ => true,
    };
    if ok { None } else { Some(html_exp_error(v, expected, path)) }
}

pub fn html_config_error(cfg: &Value) -> Option<String> {
    let html = get(cfg, &["output", "html"])?;
    if !html.is_object() {
        return Some(html_exp_error(html, "a map", "html"));
    }
    let obj = html.as_object().unwrap();
    let top: &[(&str, &str)] = &[
        ("theme", "path string"), ("default-theme", "a string"), ("preferred-dark-theme", "a string"),
        ("smart-punctuation", "a boolean"), ("curly-quotes", "a boolean"), ("mathjax-support", "a boolean"),
        ("copy-fonts", "a boolean"), ("additional-css", "a sequence"), ("additional-js", "a sequence"),
        ("no-section-label", "a boolean"), ("git-repository-url", "a string"), ("git-repository-icon", "a string"),
        ("edit-url-template", "a string"), ("input-404", "a string"), ("site-url", "a string"), ("cname", "a string"),
        ("hash-files", "a boolean"),
    ];
    for (k, exp) in top {
        if let Some(v) = obj.get(*k) {
            if let Some(e) = check_html_value(v, exp, k) { return Some(e); }
            if *exp == "a sequence" {
                if let Some(arr) = v.as_array() {
                    for item in arr {
                        if !item.is_string() { return Some(html_exp_error(item, "path string", k)); }
                    }
                }
            }
        }
    }
    // nested tables
    let nested: &[(&str, &[(&str, &str)])] = &[
        ("print", &[("enable", "a boolean"), ("page-break", "a boolean")]),
        ("fold", &[("enable", "a boolean"), ("level", "u8")]),
        ("playground", &[("editable", "a boolean"), ("copyable", "a boolean"), ("line-numbers", "a boolean"), ("runnable", "a boolean")]),
        ("search", &[
            ("enable", "a boolean"), ("limit-results", "u32"), ("teaser-word-count", "u32"), ("use-boolean-and", "a boolean"),
            ("boost-title", "u8"), ("boost-hierarchy", "u8"), ("boost-paragraph", "u8"), ("expand", "a boolean"),
            ("heading-split-level", "u8"), ("copy-js", "a boolean"),
        ]),
    ];
    for (name, fields) in nested {
        if let Some(v) = obj.get(*name) {
            if !v.is_object() { return Some(html_exp_error(v, "a map", name)); }
            for (fk, fexp) in *fields {
                if let Some(fv) = v.get(*fk) {
                    if let Some(e) = check_html_value(fv, fexp, &format!("{}.{}", name, fk)) { return Some(e); }
                }
            }
            if *name == "search" {
                if let Some(ch) = v.get("chapter") {
                    if !ch.is_object() { return Some(html_exp_error(ch, "a map", "search.chapter")); }
                    for (_key, cv) in ch.as_object().unwrap() {
                        if !cv.is_object() { return Some(html_exp_error(cv, "a map", "search.chapter")); }
                        if let Some(ev) = cv.get("enable") {
                            if let Some(e) = check_html_value(ev, "a boolean", "search.chapter") { return Some(e); }
                        }
                    }
                }
            }
        }
    }
    if let Some(code) = obj.get("code") {
        if !code.is_object() { return Some(html_exp_error(code, "a map", "code")); }
        if let Some(h) = code.get("hidelines") {
            if !h.is_object() { return Some(html_exp_error(h, "a map", "code.hidelines")); }
            for (_k, v) in h.as_object().unwrap() {
                if !v.is_string() { return Some(html_exp_error(v, "a string", "code.hidelines")); }
            }
        }
    }
    if let Some(r) = obj.get("redirect") {
        if !r.is_object() { return Some(html_exp_error(r, "a map", "redirect")); }
        for (_k, v) in r.as_object().unwrap() {
            if !v.is_string() { return Some(html_exp_error(v, "a string", "redirect")); }
        }
    }
    None
}

pub fn log_html_config_error(cfg: &Value) {
    if let Some(msg) = html_config_error(cfg) {
        crate::logger::log(crate::logger::Level::Error, "mdbook_core::utils", "Error: Parsing configuration [output.html]");
        crate::logger::log(crate::logger::Level::Error, "mdbook_core::utils", "\tCaused By: Couldn't deserialize the value");
        crate::logger::log(crate::logger::Level::Error, "mdbook_core::utils", &format!("\tCaused By: {}\n", msg));
    }
}
