        match v {
            Value::Array(a) => {
                for item in a { if !item.is_string() { return Err(err_invalid_type(item, "a string", "authors")); } }
            }
            _ => return Err(err_invalid_type(v, "a sequence", "authors")),
        }
    }
    if let Some(v) = get(cfg, &["book", "text-direction"]) {
        match v.as_str() {
            None => return Err(vec!["Invalid configuration file".to_string(), format!("invalid type: unit variant, expected string only\nin `text-direction`\n\n")]),
            Some("ltr") | Some("rtl") => {}
            Some(other) => return Err(err_unknown_variant(other, "`ltr` or `rtl`", "text-direction")),
        }
    }
    if let Some(v) = get(cfg, &["rust", "edition"]) {
        match v.as_str() {
            None => return Err(vec!["Invalid configuration file".to_string(), format!("invalid type: unit variant, expected string only\nin `edition`\n\n")]),
            Some("2015") | Some("2018") | Some("2021") | Some("2024") => {}
            Some(other) => return Err(err_unknown_variant(other, "one of `2024`, `2021`, `2018`, `2015`", "edition")),
        }
    }
    check_str!(&["build", "build-dir"], "build-dir", "path string");
    for p in [&["build", "create-missing"][..], &["build", "use-default-preprocessors"][..]] {
        let key = p[1];
        if let Some(v) = get(cfg, p) {
            if v.as_bool().is_none() { return Err(err_invalid_type(v, "a boolean", key)); }
        }
    }
    Ok(())
}

pub fn try_load_config(root: &Path) -> Result<Value, Vec<String>> {
    let cfg_path = root.join("book.toml");
    let mut cfg = json!({});
    if cfg_path.exists() {
        crate::log_debug!("mdbook_driver::mdbook", "Loading config from {}", cfg_path.display());
        match std::fs::read_to_string(&cfg_path) {
            Ok(text) => {
                match text.parse::<toml::Table>() {
                    Ok(table) => {
                        cfg = serde_json::to_value(table).unwrap_or_else(|_| json!({}));
                    }
                    Err(e) => {
                        return Err(vec![
                            "Invalid configuration file".to_string(),
                            format!("{}\n", e.to_string().trim_end()),
                        ]);
                    }
                }
            }
            Err(e) => {
                return Err(vec!["Couldn't read the file".to_string(), format!("{}", e)]);
            }
        }
    }
    apply_env(&mut cfg);
    if let Some(obj) = cfg.as_object() {
        let known = ["book", "build", "rust", "preprocessor", "output"];
        for k in obj.keys() {
            if !known.contains(&k.as_str()) {
                crate::log_warn!("mdbook_core::config", "Invalid field \"{}\" in book.toml", k);
            }
        }
    }
    validate(&cfg)?;
    log_html_config_error(&cfg);
    Ok(cfg)
}

