new='''#[derive(Clone)]
struct IgnorePattern {
    negate: bool,
    anchored: bool,
    segments: Vec<String>,
}

fn load_ignore(root: &Path) -> Vec<IgnorePattern> {
    let mut out = Vec::new();
    let path = root.join(".gitignore");
    let text = match std::fs::read_to_string(&path) { Ok(t) => t, Err(_) => return out };
    for raw in text.lines() {
        let mut line = raw.trim_end().to_string();
        if line.is_empty() || line.starts_with('#') { continue; }
        let mut negate = false;
        if let Some(rest) = line.strip_prefix('!') { negate = true; line = rest.to_string(); }
        else if let Some(rest) = line.strip_prefix("\\\\!") { line = rest.to_string(); }
        else if let Some(rest) = line.strip_prefix("\\\\#") { line = rest.to_string(); }
        let dir_only = line.ends_with('/');
        let trimmed = line.trim_end_matches('/').to_string();
        if trimmed.is_empty() { continue; }
        let anchored = trimmed.starts_with('/') || trimmed[..trimmed.len()].contains('/');
        let clean = trimmed.trim_start_matches('/').to_string();
        let _ = dir_only;
        out.push(IgnorePattern { negate, anchored, segments: clean.split('/').map(|s| s.to_string()).collect() });
    }
    out
}

fn glob_segment(pat: &str, text: &str) -> bool {
    // Wildcard matching within a single path segment.
    fn inner(p: &[char], t: &[char]) -> bool {
        if p.is_empty() { return t.is_empty(); }
        match p[0] {
            '*' => {
                for i in 0..=t.len() {
                    if inner(&p[1..], &t[i..]) { return true; }
                }
                false
            }
            '?' => !t.is_empty() && inner(&p[1..], &t[1..]),
            '[' => {
                if t.is_empty() { return false; }
                let mut i = 1;
                let negate = i < p.len() && (p[i] == '!' || p[i] == '^');
                if negate { i += 1; }
                let mut matched = false;
                let mut first = true;
                while i < p.len() && (p[i] != ']' || first) {
                    first = false;
                    if i + 2 < p.len() && p[i+1] == '-' && p[i+2] != ']' {
                        if t[0] >= p[i] && t[0] <= p[i+2] { matched = true; }
                        i += 3;
                    } else {
                        if t[0] == p[i] { matched = true; }
                        i += 1;
                    }
                }
                if i >= p.len() { return false; }
                if matched != negate { inner(&p[i+1..], &t[1..]) } else { false }
            }
            '\\\\' => !t.is_empty() && p.len() > 1 && p[1] == t[0] && inner(&p[2..], &t[1..]),
            c => !t.is_empty() && t[0] == c && inner(&p[1..], &t[1..]),
        }
    }
    let p: Vec<char> = pat.chars().collect();
    let tt: Vec<char> = text.chars().collect();
    inner(&p, &tt)
}

fn match_segments(pat: &[String], path: &[String]) -> bool {
    if pat.is_empty() { return path.is_empty(); }
    if pat[0] == "**" {
        for i in 0..=path.len() {
            if match_segments(&pat[1..], &path[i..]) { return true; }
        }
        return false;
    }
    if path.is_empty() { return false; }
    glob_segment(&pat[0], &path[0]) && match_segments(&pat[1..], &path[1..])
}

fn is_ignored(root: &Path, path: &Path, patterns: &[IgnorePattern]) -> bool {
    let rel = match path.strip_prefix(root) { Ok(r) => r, Err(_) => return false };
    let segments: Vec<String> = rel.components().map(|c| c.as_os_str().to_string_lossy().to_string()).collect();
    if segments.is_empty() { return false; }
    let mut ignored = false;
    for pat in patterns {
        let candidates: Vec<Vec<String>> = if pat.anchored {
            let mut cands = vec![segments.clone()];
            for k in 1..segments.len() { cands.push(segments[..k].to_vec()); }
            cands
        } else if pat.segments.len() == 1 {
            segments.iter().map(|s| vec![s.clone()]).collect()
        } else {
            // Unanchored multi-segment patterns match against any suffix.
            let mut cands = Vec::new();
            for start in 0..segments.len() {
                cands.push(segments[start..].to_vec());
                for k in start+1..segments.len() { cands.push(segments[start..k].to_vec()); }
            }
            cands
        };
        if candidates.iter().any(|c| match_segments(&pat.segments, c)) {
            ignored = !pat.negate;
        }
    }
    ignored
}

pub fn snapshot_dirs(root: &Path, dirs: &[PathBuf]) -> Snapshot {
    let patterns = load_ignore(root);
    let mut map = HashMap::new();
    for d in dirs {
        if d.is_file() {
            if !is_ignored(root, d, &patterns) {
                if let Ok(m) = std::fs::metadata(d) {
                    map.insert(d.clone(), (m.modified().unwrap_or(SystemTime::UNIX_EPOCH), m.len()));
                }
            }
            continue;
        }
        collect_filtered(d, &mut map, root, &patterns);
    }
    map
}

fn collect_filtered(dir: &Path, map: &mut Snapshot, root: &Path, patterns: &[IgnorePattern]) {
    if let Ok(rd) = std::fs::read_dir(dir) {
        let mut entries: Vec<PathBuf> = rd.filter_map(|e| e.ok().map(|e| e.path())).collect();
        entries.sort();
        for e in entries {
            if e.is_dir() { collect_filtered(&e, map, root, patterns); }
            else if !is_ignored(root, &e, patterns) {
                if let Ok(m) = std::fs::metadata(&e) {
                    map.insert(e, (m.modified().unwrap_or(SystemTime::UNIX_EPOCH), m.len()));
                }
            }
        }
    }
