{"command":"cat >> src/hbs.rs <<'RS'

fn valid_expr(content: &str) -> Result<(), String> {
    let c = content.trim().trim_start_matches('~').trim_end_matches('~').trim();
    if c.is_empty() { return Err("empty expression".to_string()); }
    // Tokenise respecting quotes.
    let mut tokens: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut chars = c.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch.is_whitespace() {
            if !cur.is_empty() { tokens.push(cur.clone()); cur.clear(); }
            continue;
        }
        if ch == '"' || ch == '\'' {
            if !cur.is_empty() { tokens.push(cur.clone()); cur.clear(); }
            let mut s = String::new();
            s.push(ch);
            let mut closed = false;
            while let Some(nc) = chars.next() {
                s.push(nc);
                if nc == '\\' {
                    if let Some(e) = chars.next() { s.push(e); }
                } else if nc == ch { closed = true; break; }
            }
            if !closed { return Err("unterminated string".to_string()); }
            tokens.push(s);
            continue;
        }
        cur.push(ch);
    }
    if !cur.is_empty() { tokens.push(cur); }
    if tokens.is_empty() { return Err("empty expression".to_string()); }
    for tok in &tokens {
        if tok == "(" || tok == ")" || tok == "=" { continue; }
        // hash params key=value
        let core = match tok.split_once('=') {
            Some((k, v)) => {
                if k.is_empty() || !k.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-') { return Err(format!("invalid token {}", tok)); }
                if v.is_empty() { continue; }
                v
            }
            None => tok.as_str(),
        };
        if core.starts_with('"') || core.starts_with('\'') { continue; }
        if core == "true" || core == "false" || core == "null" { continue; }
        if core.chars().all(|c| c.is_ascii_digit() || c == '.' || c == '-') && core.chars().any(|c| c.is_ascii_digit()) { continue; }
        if core.starts_with('@') {
            if core[1..].chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-' || c == '.') { continue; }
            return Err(format!("invalid token {}", tok));
        }
        // Path segments can include ../, ./, this, brackets.
        let cleaned: String = core.chars().filter(|c| *c != '[' && *c != ']').collect();
        if cleaned.is_empty() { return Err(format!("invalid token {}", tok)); }
        if !cleaned.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-' || c == '.' || c == '/') {
            return Err(format!("invalid token {}", tok));
        }
    }
    // parenthesis balance
    let mut depth = 0i32;
    for tok in &tokens {
        if tok == "(" { depth += 1; }
        if tok == ")" { depth -= 1; if depth < 0 { return Err("unbalanced parenthesis".to_string()); } }
    }
    if depth != 0 { return Err("unbalanced parenthesis".to_string()); }
    Ok(())
}

pub fn validate_template(tpl: &str, template_name: &str) -> Result<(), String> {
    let mut stack: Vec<String> = Vec::new();
    let mut pos = 0usize;
    while pos < tpl.len() {
        let start = match tpl[pos..].find("{{") {
            Some(p) => pos + p,
            None => break,
        };
        if tpl[start..].starts_with("{{{") {
            let end = tpl[start+3..].find("}}}").ok_or_else(|| format!("Template error: invalid handlebars syntax: unclosed triple-mustache in \"{}\"", template_name))?;
            let content = &tpl[start+3..start+3+end];
            valid_expr(content).map_err(|e| format!("Template error: invalid handlebars syntax: {} in \"{}\"", e, template_name))?;
            pos = start + 3 + end + 3;
            continue;
        }
        if tpl[start..].starts_with("{{!--") {
            let end = tpl[start+4..].find("--}}").ok_or_else(|| format!("Template error: invalid handlebars syntax: unclosed comment in \"{}\"", template_name))?;
            pos = start + 4 + end + 4;
            continue;
        }
        let end = tpl[start+2..].find("}}").ok_or_else(|| format!("Template error: invalid handlebars syntax: unclosed expression in \"{}\"", template_name))?;
        let content = tpl[start+2..start+2+end].trim().trim_start_matches('~').trim_end_matches('~').trim().to_string();
        pos = start + 2 + end + 2;
        if content.starts_with('!') { continue; }
        if content == "else" {
            if stack.is_empty() { return Err(format!("Template error: invalid handlebars syntax: unexpected else in \"{}\"", template_name)); }
            continue;
        }
        if let Some(block) = content.strip_prefix('#') {
            let name = block.split_whitespace().next().unwrap_or("");
            if name.is_empty() || !name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-') {
                return Err(format!("Template error: invalid handlebars syntax: invalid block in \"{}\"", template_name));
            }
            let args = block[name.len()..].trim();
            if (name == "if" || name == "each" || name == "unless") && args.is_empty() {
                return Err(format!("Template error: invalid handlebars syntax: missing parameter for \"{}\" in \"{}\"", name, template_name));
            }
            if !args.is_empty() {
                valid_expr(args).map_err(|e| format!("Template error: invalid handlebars syntax: {} in \"{}\"", e, template_name))?;
            }
            stack.push(name.to_string());
            continue;
        }
        if let Some(block) = content.strip_prefix('^') {
            let name = block.split_whitespace().next().unwrap_or("");
            if name.is_empty() { return Err(format!("Template error: invalid handlebars syntax in \"{}\"", template_name)); }
            stack.push(name.to_string());
            continue;
        }
        if let Some(close) = content.strip_prefix('/') {
            let name = close.trim();
            match stack.pop() {
                Some(open) if open == name => {}
                Some(open) => return Err(format!("Template error: helper \"{}\" was opened, but \"{}\" is closing in \"{}\"", open, name, template_name)),
                None => return Err(format!("Template error: invalid handlebars syntax: unexpected closing \"{}\" in \"{}\"", name, template_name)),
            }
            continue;
        }
        if let Some(partial) = content.strip_prefix('>') {
            let name = partial.trim();
            if name.is_empty() || !name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-' || c == '/' || c == '.') {
                return Err(format!("Template error: invalid handlebars syntax: invalid partial in \"{}\"", template_name));
            }
            continue;
        }
        valid_expr(&content).map_err(|e| format!("Template error: invalid handlebars syntax: {} in \"{}\"", e, template_name))?;
    }
    if let Some(open) = stack.last() {
        return Err(format!("Template error: invalid handlebars syntax: unclosed block \"{}\" in \"{}\"", open, template_name));
    }
    Ok(())
}
