            continue;
        }
        let end = tpl[start+2..].find("}}").ok_or_else(|| format!("Template error: invalid handlebars syntax: unclosed expression in \"{}\"", template_name))?;
        let content = tpl[start+2..start+2+end].trim().trim_start_matches('~').trim_end_matches('~').trim().to_string();
        pos = start + 2 + end + 2;
        if content.starts_with('!') { continue; }
        if content == "else" {
            if stack.is_empty() { return Err(format!("Template error: invalid handlebars syntax: unexpected else in \"{}\"", template_name)); }
            continue;
        }
        if let Some(block) = content.strip_prefix('#') {
            let name = block.split_whitespace().next().unwrap_or("");
            if name.is_empty() || !name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-') {
                return Err(format!("Template error: invalid handlebars syntax: invalid block in \"{}\"", template_name));
            }
