                if let Some(v) = b.get(key) { book.insert(key.to_string(), v.clone()); }
            }
        }
        book.insert("authors".to_string(), src_book.and_then(|b| b.get("authors")).cloned().unwrap_or_else(|| json!([])));
        book.insert("language".to_string(), src_book.and_then(|b| b.get("language")).cloned().unwrap_or_else(|| json!("en")));
        book.insert("src".to_string(), src_book.and_then(|b| b.get("src")).cloned().unwrap_or_else(|| json!("src")));
        out.insert("book".to_string(), Value::Object(book));
    }
    // build: only present when it differs from the defaults.
    {
        let build_dir = dest_override.cloned().or_else(|| crate::config::get_str(cfg, &["build", "build-dir"])).unwrap_or_else(|| "book".to_string());
        let create_missing = crate::config::get_bool(cfg, &["build", "create-missing"]).unwrap_or(true);
        let extra_watch = crate::config::get(cfg, &["build", "extra-watch-dirs"]).cloned().unwrap_or_else(|| json!([]));
        let use_defaults = crate::config::get_bool(cfg, &["build", "use-default-preprocessors"]).unwrap_or(true);
        let is_default = build_dir == "book" && create_missing && extra_watch == json!([]) && use_defaults;
        if !is_default {
            out.insert("build".to_string(), json!({
                "build-dir": build_dir,
                "create-missing": create_missing,
                "extra-watch-dirs": extra_watch,
                "use-default-preprocessors": use_defaults,
            }));
        }
    }
    if let Some(rust) = crate::config::get(cfg, &["rust"]) {
        if let Some(ed) = rust.get("edition") {
            out.insert("rust".to_string(), json!({ "edition": ed }));
        }
    }
    if let Some(pp) = crate::config::get(cfg, &["preprocessor"]) {
        out.insert("preprocessor".to_string(), pp.clone());
    }
    if let Some(output) = crate::config::get(cfg, &["output"]) {
        out.insert("output".to_string(), output.clone());
    }
    Value::Object(out)
}

